INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),1,1,'{"it":"Dove va il contenuto visibile della pagina?","en":"Where does the visible content of the page go?"}','[{"it":"<head>","en":"<head>"},{"it":"<body>","en":"<body>"},{"it":"<title>","en":"<title>"},{"it":"<meta>","en":"<meta>"}]',1,'{"it":"Tutto ciò che si vede nella pagina sta dentro `<body>`.","en":"Everything visible on the page sits inside `<body>`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),2,1,'{"it":"A cosa serve `<!doctype html>`?","en":"What is `<!doctype html>` for?"}','[{"it":"Crea un titolo","en":"It creates a heading"},{"it":"Dice al browser che è una pagina HTML moderna","en":"It tells the browser this is a modern HTML page"},{"it":"Collega un foglio di stile","en":"It links a stylesheet"},{"it":"Chiude il documento e lo prepara per la stampa","en":"It closes the document and prepares it for printing"}]',1,'{"it":"Va sempre sulla prima riga: evita che il browser usi la vecchia modalità di compatibilità.","en":"It always goes on the first line: it stops the browser using the old compatibility mode."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),3,1,'{"it":"Quale tag imposta il testo della scheda del browser?","en":"Which tag sets the text of the browser tab?"}','[{"it":"<h1>","en":"<h1>"},{"it":"<header>","en":"<header>"},{"it":"<title>","en":"<title>"},{"it":"<tab>","en":"<tab>"}]',2,'{"it":"`<title>` sta in `<head>` e dà il nome alla scheda.","en":"`<title>` sits in `<head>` and names the tab."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),1,1,'{"it":"Qual è il titolo più importante?","en":"Which is the most important heading?"}','[{"it":"<h6>","en":"<h6>"},{"it":"<h1>","en":"<h1>"},{"it":"<head>","en":"<head>"},{"it":"<p>","en":"<p>"}]',1,'{"it":"La numerazione va dal più importante, `h1`, al meno importante, `h6`.","en":"Numbering goes from the most important, `h1`, to the least, `h6`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),2,1,'{"it":"Quale tag indica un testo importante?","en":"Which tag marks important text?"}','[{"it":"<i>","en":"<i>"},{"it":"<strong>","en":"<strong>"},{"it":"<big>","en":"<big>"},{"it":"<u>","en":"<u>"}]',1,'{"it":"`<strong>` dà importanza al testo, anche per chi usa uno screen reader.","en":"`<strong>` gives the text importance, also for screen reader users."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),3,1,'{"it":"Quale di questi tag non ha un tag di chiusura?","en":"Which of these tags has no closing tag?"}','[{"it":"<p>","en":"<p>"},{"it":"<em>","en":"<em>"},{"it":"<br>","en":"<br>"},{"it":"<h2>","en":"<h2>"}]',2,'{"it":"`<br>` è un elemento vuoto: non ha contenuto e non si chiude.","en":"`<br>` is an empty element: it has no content and is not closed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),1,1,'{"it":"Quale attributo contiene la destinazione di un link?","en":"Which attribute holds the destination of a link?"}','[{"it":"src","en":"src"},{"it":"href","en":"href"},{"it":"link","en":"link"},{"it":"to","en":"to"}]',1,'{"it":"`href` sta per «hypertext reference».","en":"`href` stands for “hypertext reference”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),2,1,'{"it":"A cosa serve l’attributo `alt`?","en":"What is the `alt` attribute for?"}','[{"it":"Allinea l’immagine al centro del paragrafo","en":"It aligns the image to the centre of the paragraph"},{"it":"Descrive l’immagine a chi non può vederla","en":"It describes the image to whoever cannot see it"},{"it":"Indica l’altezza","en":"It sets the height"},{"it":"Apre un link","en":"It opens a link"}]',1,'{"it":"Lo leggono gli screen reader e compare se l’immagine non si carica.","en":"Screen readers read it and it appears if the image fails to load."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),3,1,'{"it":"Quale riga è corretta?","en":"Which line is correct?"}','[{"it":"<a src=\\"a.html\\">Vai</a>","en":"<a src=\\"a.html\\">Vai</a>"},{"it":"<img href=\\"a.jpg\\">","en":"<img href=\\"a.jpg\\">"},{"it":"<a href=\\"a.html\\">Vai</a>","en":"<a href=\\"a.html\\">Vai</a>"},{"it":"<link a=\\"a.html\\">Vai</link>","en":"<link a=\\"a.html\\">Vai</link>"}]',2,'{"it":"I link usano `href`, le immagini `src`.","en":"Links use `href`, images use `src`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),1,1,'{"it":"Quale tag crea una lista numerata?","en":"Which tag creates a numbered list?"}','[{"it":"<ul>","en":"<ul>"},{"it":"<ol>","en":"<ol>"},{"it":"<li>","en":"<li>"},{"it":"<nl>","en":"<nl>"}]',1,'{"it":"`ol` sta per «ordered list».","en":"`ol` stands for “ordered list”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),2,1,'{"it":"Con quale tag si scrive ogni voce?","en":"Which tag is used for each item?"}','[{"it":"<item>","en":"<item>"},{"it":"<li>","en":"<li>"},{"it":"<ul>","en":"<ul>"},{"it":"<dd>","en":"<dd>"}]',1,'{"it":"`<li>` vale sia per `ul` sia per `ol`.","en":"`<li>` works for both `ul` and `ol`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),3,1,'{"it":"Dove va una lista annidata?","en":"Where does a nested list go?"}','[{"it":"Dentro un `<li>`","en":"Inside an `<li>`"},{"it":"Tra due `<li>`","en":"Between two `<li>`"},{"it":"Fuori dalla lista","en":"Outside the list"},{"it":"Dentro `<head>`","en":"Inside `<head>`"}]',0,'{"it":"Figli diretti di `ul` e `ol` possono essere solo gli `li`.","en":"Only `li` elements can be direct children of `ul` and `ol`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),1,2,'{"it":"Quale tag crea una riga?","en":"Which tag creates a row?"}','[{"it":"<td>","en":"<td>"},{"it":"<th>","en":"<th>"},{"it":"<tr>","en":"<tr>"},{"it":"<row>","en":"<row>"}]',2,'{"it":"`tr` sta per «table row».","en":"`tr` stands for “table row”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),2,2,'{"it":"Quale tag crea una cella di intestazione?","en":"Which tag creates a header cell?"}','[{"it":"<th>","en":"<th>"},{"it":"<td>","en":"<td>"},{"it":"<thead>","en":"<thead>"},{"it":"<header>","en":"<header>"}]',0,'{"it":"`<th>` è la cella, `<thead>` è il gruppo delle righe di intestazione.","en":"`<th>` is the cell, `<thead>` the group of header rows."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),3,2,'{"it":"Come fai occupare a una cella due colonne?","en":"How do you make a cell span two columns?"}','[{"it":"rowspan=\\"2\\"","en":"rowspan=\\"2\\""},{"it":"colspan=\\"2\\"","en":"colspan=\\"2\\""},{"it":"width=\\"2\\"","en":"width=\\"2\\""},{"it":"cols=\\"2\\"","en":"cols=\\"2\\""}]',1,'{"it":"`colspan` unisce colonne, `rowspan` unisce righe.","en":"`colspan` merges columns, `rowspan` merges rows."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),1,2,'{"it":"Come si collega una `label` a un campo?","en":"How do you tie a `label` to a field?"}','[{"it":"Con `for` uguale all’`id` del campo","en":"With `for` equal to the field’s `id`"},{"it":"Con `name` uguale a `class`","en":"With `name` equal to `class`"},{"it":"Con `href`","en":"With `href`"},{"it":"Mettendola subito prima","en":"By placing it right before"}]',0,'{"it":"`for` e `id` devono avere lo stesso valore.","en":"`for` and `id` must have the same value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),2,2,'{"it":"Quale attributo rende obbligatorio un campo?","en":"Which attribute makes a field mandatory?"}','[{"it":"needed","en":"needed"},{"it":"mandatory","en":"mandatory"},{"it":"required","en":"required"},{"it":"must","en":"must"}]',2,'{"it":"Con `required` il browser blocca l’invio se il campo è vuoto.","en":"With `required` the browser blocks sending if the field is empty."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),3,2,'{"it":"A cosa serve `name` in un campo?","en":"What is `name` for in a field?"}','[{"it":"È il testo mostrato all’utente dentro il campo","en":"It is the text shown to the user inside the field"},{"it":"È il nome con cui il dato viene inviato","en":"It is the name the data is sent with"},{"it":"È il suo stile","en":"It is its style"},{"it":"Dà un titolo alla pagina","en":"It titles the page"}]',1,'{"it":"Senza `name` il valore del campo non viene inviato.","en":"Without `name` the value of the field is not sent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'entities'),1,2,'{"it":"Come si mostra il simbolo `<` nel testo?","en":"How do you show the `<` symbol in text?"}','[{"it":"&lt;","en":"&lt;"},{"it":"&gt;","en":"&gt;"},{"it":"<<","en":"<<"},{"it":"\\\\<","en":"\\\\<"}]',0,'{"it":"`lt` sta per «less than».","en":"`lt` stands for “less than”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'entities'),2,2,'{"it":"Come inizia un commento HTML?","en":"How does an HTML comment start?"}','[{"it":"//","en":"//"},{"it":"/*","en":"/*"},{"it":"<!--","en":"<!--"},{"it":"#","en":"#"}]',2,'{"it":"Si apre con `<!--` e si chiude con `-->`.","en":"It opens with `<!--` and closes with `-->`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'entities'),3,2,'{"it":"Un commento è segreto?","en":"Is a comment secret?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, si legge nel sorgente","en":"No, it can be read in the source"},{"it":"Solo in `<head>`","en":"Only in `<head>`"},{"it":"Solo sul server","en":"Only on the server"}]',1,'{"it":"Mai scrivere password o dati privati in un commento.","en":"Never write passwords or private data in a comment."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'page-project'),1,2,'{"it":"Quanti `<h1>` conviene avere in una pagina?","en":"How many `<h1>` should a page have?"}','[{"it":"Uno","en":"One"},{"it":"Almeno tre","en":"At least three"},{"it":"Uno per paragrafo","en":"One per paragraph"},{"it":"Nessuno","en":"None"}]',0,'{"it":"`h1` è il titolo della pagina: gli altri scendono di livello.","en":"`h1` is the title of the page: the others go down a level."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'page-project'),2,2,'{"it":"Che cosa manca a `<img src=\\"a.jpg\\">`?","en":"What is `<img src=\\"a.jpg\\">` missing?"}','[{"it":"alt","en":"alt"},{"it":"href","en":"href"},{"it":"title","en":"title"},{"it":"width","en":"width"}]',0,'{"it":"`alt` descrive l’immagine a chi non può vederla.","en":"`alt` describes the image to those who cannot see it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'page-project'),3,2,'{"it":"Che cosa va scritto per primo?","en":"What should you write first?"}','[{"it":"Il contenuto","en":"The content"},{"it":"I colori","en":"The colours"},{"it":"Le animazioni","en":"The animations"},{"it":"Il logo","en":"The logo"}]',0,'{"it":"Lo stile si appoggia alla struttura, non il contrario.","en":"Style rests on the structure, not the other way round."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'attributes'),1,1,'{"it":"Quante classi può avere un elemento?","en":"How many classes can an element have?"}','[{"it":"Quante vuoi","en":"As many as you like"},{"it":"Una","en":"One"},{"it":"Due","en":"Two"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Si separano con uno spazio.","en":"They are separated by a space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'attributes'),2,1,'{"it":"Quale attributo nasconde un elemento?","en":"Which attribute hides an element?"}','[{"it":"hidden","en":"hidden"},{"it":"none","en":"none"},{"it":"invisible","en":"invisible"},{"it":"off","en":"off"}]',0,'{"it":"`hidden` non ha bisogno di un valore.","en":"`hidden` needs no value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'attributes'),3,1,'{"it":"Due elementi possono avere lo stesso `id`?","en":"Can two elements share the same `id`?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo i `div`","en":"Only `div`s"},{"it":"Solo in `<body>`","en":"Only in `<body>`"}]',0,'{"it":"Un `id` è unico nella pagina.","en":"An `id` is unique in the page."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'anchors'),1,1,'{"it":"Che cosa fa `href=\\"#menu\\"`?","en":"What does `href=\\"#menu\\"` do?"}','[{"it":"Salta all’elemento con id menu","en":"Jumps to the element with id menu"},{"it":"Apre il file menu.html in una nuova scheda","en":"Opens the file menu.html in a new tab"},{"it":"Cerca su Google","en":"Searches Google"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Il cancelletto indica un punto della pagina.","en":"The hash marks a spot in the page."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'anchors'),2,1,'{"it":"Che cosa significa `../`?","en":"What does `../` mean?"}','[{"it":"La cartella sopra","en":"The folder above"},{"it":"La cartella sotto","en":"The folder below"},{"it":"La home","en":"The home page"},{"it":"Il server","en":"The server"}]',0,'{"it":"Due punti risalgono di un livello.","en":"Two dots go up one level."}',NULL);
