INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),3,1,'{"it":"Che cosa fa `margin: 0 auto`?","en":"What does `margin: 0 auto` do?"}','[{"it":"Toglie il bordo","en":"Removes the border"},{"it":"Centra orizzontalmente un blocco","en":"Centres a block horizontally"},{"it":"Centra il testo","en":"Centres the text"},{"it":"Nasconde il blocco","en":"Hides the block"}]',1,'{"it":"I margini laterali automatici si dividono lo spazio libero.","en":"Automatic side margins share the free space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),1,1,'{"it":"Quale elemento è `inline` di natura?","en":"Which element is `inline` by default?"}','[{"it":"<div>","en":"<div>"},{"it":"<p>","en":"<p>"},{"it":"<a>","en":"<a>"},{"it":"<h1>","en":"<h1>"}]',2,'{"it":"`<a>` scorre nel testo senza andare a capo.","en":"`<a>` flows in the text without a line break."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),2,1,'{"it":"Qual è la differenza tra `display: none` e `visibility: hidden`?","en":"What is the difference between `display: none` and `visibility: hidden`?"}','[{"it":"Nessuna","en":"None"},{"it":"Il primo toglie anche lo spazio","en":"The first removes the space too"},{"it":"Il secondo toglie lo spazio","en":"The second removes the space"},{"it":"Il primo è solo per il testo","en":"The first is only for text"}]',1,'{"it":"`visibility: hidden` lascia un buco della stessa misura.","en":"`visibility: hidden` leaves a hole of the same size."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),3,1,'{"it":"Quale valore scorre nel testo e accetta `width`?","en":"Which value flows in the text and accepts `width`?"}','[{"it":"block","en":"block"},{"it":"inline","en":"inline"},{"it":"inline-block","en":"inline-block"},{"it":"flow","en":"flow"}]',2,'{"it":"È una via di mezzo tra `inline` e `block`.","en":"It is halfway between `inline` and `block`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),1,2,'{"it":"Rispetto a cosa si posiziona un elemento `absolute`?","en":"What is an `absolute` element positioned against?"}','[{"it":"Sempre la pagina","en":"Always the page"},{"it":"Il primo antenato posizionato","en":"The nearest positioned ancestor"},{"it":"L’elemento precedente","en":"The previous element"},{"it":"Lo schermo","en":"The screen"}]',1,'{"it":"Per questo si mette `position: relative` sul contenitore.","en":"That is why you set `position: relative` on the container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),2,2,'{"it":"Quale valore resta fermo durante lo scorrimento della pagina?","en":"Which value stays still while the page scrolls?"}','[{"it":"static","en":"static"},{"it":"relative","en":"relative"},{"it":"fixed","en":"fixed"},{"it":"float","en":"float"}]',2,'{"it":"`fixed` si aggancia allo schermo.","en":"`fixed` is anchored to the screen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),3,2,'{"it":"Quale proprietà decide cosa sta sopra?","en":"Which property decides what is on top?"}','[{"it":"z-index","en":"z-index"},{"it":"layer","en":"layer"},{"it":"top","en":"top"},{"it":"order-top","en":"order-top"}]',0,'{"it":"Funziona sugli elementi posizionati e sui figli di flex e grid.","en":"It works on positioned elements and on flex and grid children."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),1,2,'{"it":"Chi vince tra `.nota` e `#box` sullo stesso elemento?","en":"Which wins between `.nota` and `#box` on the same element?"}','[{"it":".nota","en":".nota"},{"it":"#box","en":"#box"},{"it":"L’ultima scritta","en":"The last one written"},{"it":"Nessuna","en":"Neither"}]',1,'{"it":"L’`id` ha una specificità più alta della classe.","en":"An `id` has higher specificity than a class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),2,2,'{"it":"Con la stessa specificità chi vince?","en":"With the same specificity, which wins?"}','[{"it":"La prima scritta","en":"The first written"},{"it":"L’ultima scritta","en":"The last written"},{"it":"La più corta","en":"The shortest"},{"it":"Nessuna","en":"Neither"}]',1,'{"it":"È il senso della parola «cascata».","en":"That is the meaning of the word “cascade”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),3,2,'{"it":"Quale proprietà si eredita?","en":"Which property is inherited?"}','[{"it":"margin","en":"margin"},{"it":"border","en":"border"},{"it":"color","en":"color"},{"it":"padding","en":"padding"}]',2,'{"it":"Il colore del testo passa dai genitori ai figli.","en":"The text colour passes from parents to children."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),1,2,'{"it":"Quale funzione crea una sfumatura?","en":"Which function creates a gradient?"}','[{"it":"linear-gradient()","en":"linear-gradient()"},{"it":"fade()","en":"fade()"},{"it":"blend()","en":"blend()"},{"it":"mix()","en":"mix()"}]',0,'{"it":"Esiste anche `radial-gradient()`.","en":"There is also `radial-gradient()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),2,2,'{"it":"Che cosa fa il terzo valore di `box-shadow: 0 4px 12px`?","en":"What does the third value of `box-shadow: 0 4px 12px` do?"}','[{"it":"La sfocatura","en":"The blur"},{"it":"Il colore","en":"The colour"},{"it":"Il raggio","en":"The radius"},{"it":"L’opacità","en":"The opacity"}]',0,'{"it":"Più è alto, più l’ombra è morbida.","en":"The higher it is, the softer the shadow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),3,2,'{"it":"Quale proprietà mette un’ombra al testo?","en":"Which property puts a shadow on text?"}','[{"it":"text-shadow","en":"text-shadow"},{"it":"font-shadow","en":"font-shadow"},{"it":"shadow","en":"shadow"},{"it":"box-shadow","en":"box-shadow"}]',0,'{"it":"`box-shadow` vale per la scatola.","en":"`box-shadow` is for the box."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),1,2,'{"it":"`50%` di che cosa?","en":"`50%` of what?"}','[{"it":"Del contenitore","en":"Of the container"},{"it":"Dello schermo, sempre","en":"Of the screen, always"},{"it":"Del testo","en":"Of the text"},{"it":"Del file","en":"Of the file"}]',0,'{"it":"Le percentuali guardano al genitore.","en":"Percentages look at the parent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),2,2,'{"it":"Quanto vale `100vh`?","en":"What is `100vh`?"}','[{"it":"Tutta l’altezza dello schermo","en":"The full height of the screen"},{"it":"100 pixel","en":"100 pixels"},{"it":"La larghezza","en":"The width"},{"it":"Il doppio del testo","en":"Twice the text"}]',0,'{"it":"`vh` è l’1% dell’altezza della finestra.","en":"`vh` is 1% of the window height."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),3,2,'{"it":"Da che cosa dipende `rem`?","en":"What does `rem` depend on?"}','[{"it":"Dalla radice del documento","en":"On the root of the document"},{"it":"Dal genitore","en":"On the parent"},{"it":"Dallo schermo","en":"On the screen"},{"it":"Da nulla","en":"On nothing"}]',0,'{"it":"`r` sta per root.","en":"`r` stands for root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),1,1,'{"it":"Che cosa sceglie `ul > li`?","en":"What does `ul > li` pick?"}','[{"it":"I figli diretti","en":"The direct children"},{"it":"Tutti i discendenti","en":"All descendants"},{"it":"Il primo","en":"The first one"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Il `>` si ferma al primo livello.","en":"The `>` stops at the first level."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),2,1,'{"it":"Che cosa sceglie `h1 + p`?","en":"What does `h1 + p` pick?"}','[{"it":"Il `p` subito dopo `h1`","en":"The `p` right after `h1`"},{"it":"Tutti i `p`","en":"All `p`s"},{"it":"`h1` e `p`","en":"`h1` and `p`"},{"it":"I `p` dentro `h1`","en":"The `p`s inside `h1`"}]',0,'{"it":"`+` è il fratello adiacente.","en":"`+` is the adjacent sibling."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),3,1,'{"it":"Che cosa significa `[href$=\\".pdf\\"]`?","en":"What does `[href$=\\".pdf\\"]` mean?"}','[{"it":"Finisce con .pdf","en":"Ends with .pdf"},{"it":"Inizia con .pdf","en":"Starts with .pdf"},{"it":"Contiene pdf","en":"Contains pdf"},{"it":"Costa pdf","en":"Costs pdf"}]',0,'{"it":"Il dollaro indica la fine.","en":"The dollar marks the end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),1,1,'{"it":"Quale pseudo-classe vale mentre premi?","en":"Which pseudo-class applies while pressing?"}','[{"it":":active","en":":active"},{"it":":press","en":":press"},{"it":":hover","en":":hover"},{"it":":down","en":":down"}]',0,'{"it":"`:hover` è il passaggio del mouse.","en":"`:hover` is the mouse passing over."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),2,1,'{"it":"Perché `:focus-visible` è utile?","en":"Why is `:focus-visible` useful?"}','[{"it":"Mostra il focus a chi usa la tastiera","en":"It shows focus to keyboard users"},{"it":"Nasconde il mouse","en":"It hides the mouse"},{"it":"Cambia il font","en":"It changes the font"},{"it":"Blocca il click","en":"It blocks the click"}]',0,'{"it":"Non disturba chi clicca col mouse.","en":"It does not bother those clicking with a mouse."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),3,1,'{"it":"Quando vale `input:invalid`?","en":"When does `input:invalid` apply?"}','[{"it":"Il valore non rispetta le regole","en":"The value breaks the rules"},{"it":"Il campo è vuoto sempre","en":"The field is always empty"},{"it":"Il campo è nascosto","en":"The field is hidden"},{"it":"Mai","en":"Never"}]',0,'{"it":"Dipende da `required`, `type`, `pattern`.","en":"It depends on `required`, `type`, `pattern`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),1,1,'{"it":"Quale proprietà cambia lo spazio tra le righe?","en":"Which property changes the space between lines?"}','[{"it":"line-height","en":"line-height"},{"it":"row-gap","en":"row-gap"},{"it":"letter-spacing","en":"letter-spacing"},{"it":"margin","en":"margin"}]',0,'{"it":"Un valore tra 1.4 e 1.7 è comodo.","en":"A value from 1.4 to 1.7 is comfortable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),2,1,'{"it":"Che cos’è `65ch`?","en":"What is `65ch`?"}','[{"it":"Circa 65 caratteri","en":"About 65 characters"},{"it":"65 pixel","en":"65 pixels"},{"it":"65% dello schermo","en":"65% of the screen"},{"it":"65 righe","en":"65 lines"}]',0,'{"it":"Si basa sulla larghezza dello zero.","en":"It is based on the width of the zero."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),3,1,'{"it":"Che cosa carica un font personale?","en":"What loads a custom font?"}','[{"it":"@font-face","en":"@font-face"},{"it":"@import-font","en":"@import-font"},{"it":"font-load","en":"font-load"},{"it":"@text","en":"@text"}]',0,'{"it":"Si indicano nome e file.","en":"You give a name and a file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),1,2,'{"it":"Quale valore mette le barre solo se servono?","en":"Which value adds scrollbars only if needed?"}','[{"it":"auto","en":"auto"},{"it":"scroll","en":"scroll"},{"it":"hidden","en":"hidden"},{"it":"bars","en":"bars"}]',0,'{"it":"`scroll` le mostra sempre.","en":"`scroll` always shows them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),2,2,'{"it":"`z-index` funziona su un elemento `static`?","en":"Does `z-index` work on a `static` element?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo sui link","en":"Only on links"},{"it":"Solo su `body`","en":"Only on `body`"}]',0,'{"it":"Serve un elemento posizionato.","en":"It needs a positioned element."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),3,2,'{"it":"Che cosa aggiunge `text-overflow: ellipsis`?","en":"What does `text-overflow: ellipsis` add?"}','[{"it":"I puntini","en":"An ellipsis"},{"it":"Una barra","en":"A scrollbar"},{"it":"Un’ombra","en":"A shadow"},{"it":"Un link","en":"A link"}]',0,'{"it":"Funziona con `overflow: hidden`.","en":"It works with `overflow: hidden`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),1,2,'{"it":"Che cosa toglie la sottolineatura?","en":"What removes the underline?"}','[{"it":"text-decoration: none","en":"text-decoration: none"},{"it":"underline: 0","en":"underline: 0"},{"it":"border: none","en":"border: none"},{"it":"font-style: none","en":"font-style: none"}]',0,'{"it":"I link la hanno di serie.","en":"Links have it by default."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),2,2,'{"it":"Quale cursore indica che si può cliccare?","en":"Which cursor shows you can click?"}','[{"it":"pointer","en":"pointer"},{"it":"hand","en":"hand"},{"it":"click","en":"click"},{"it":"finger","en":"finger"}]',0,'{"it":"`cursor: pointer`.","en":"`cursor: pointer`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),3,2,'{"it":"Quanto dovrebbe essere alto un bottone su telefono?","en":"How high should a button be on phones?"}','[{"it":"Almeno 44px","en":"At least 44px"},{"it":"10px","en":"10px"},{"it":"Non importa","en":"It does not matter"},{"it":"500px","en":"500px"}]',0,'{"it":"Le dita sono meno precise del mouse.","en":"Fingers are less precise than a mouse."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),1,2,'{"it":"Quale proprietà distribuisce lungo l’asse principale?","en":"Which property distributes along the main axis?"}','[{"it":"align-items","en":"align-items"},{"it":"justify-content","en":"justify-content"},{"it":"flex-wrap","en":"flex-wrap"},{"it":"gap","en":"gap"}]',1,'{"it":"Con `flex-direction: row` l’asse principale è orizzontale.","en":"With `flex-direction: row` the main axis is horizontal."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),2,2,'{"it":"Dove si scrive `display: flex`?","en":"Where do you write `display: flex`?"}','[{"it":"Sul contenitore","en":"On the container"},{"it":"Su ogni figlio","en":"On each child"},{"it":"Su `html`","en":"On `html`"},{"it":"Sul primo figlio","en":"On the first child"}]',0,'{"it":"Il contenitore diventa flex e i figli diretti ne seguono le regole.","en":"The container becomes flex and its direct children follow its rules."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),3,2,'{"it":"Come centri un elemento in entrambi i sensi?","en":"How do you centre an element both ways?"}','[{"it":"margin: center","en":"margin: center"},{"it":"`align-content` e `text-align` su `middle`","en":"`align-content` and `text-align` set to `middle`"},{"it":"`justify-content` e `align-items` su `center`","en":"`justify-content` and `align-items` set to `center`"},{"it":"float: center","en":"float: center"}]',2,'{"it":"Sono i due assi del contenitore flex.","en":"They are the two axes of the flex container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),1,2,'{"it":"Che cos’è l’unità `fr`?","en":"What is the `fr` unit?"}','[{"it":"Una frazione dello spazio libero","en":"A fraction of the free space"},{"it":"Un pixel","en":"A pixel"},{"it":"La larghezza del font","en":"The width of the font"},{"it":"Un frame","en":"A frame"}]',0,'{"it":"`1fr 2fr` divide lo spazio in tre parti: una e due.","en":"`1fr 2fr` splits the space into three parts: one and two."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),2,2,'{"it":"Come scrivi tre colonne uguali?","en":"How do you write three equal columns?"}','[{"it":"grid-columns: 3 equal-width auto-fill","en":"grid-columns: 3 equal-width auto-fill"},{"it":"grid-template-columns: repeat(3, 1fr)","en":"grid-template-columns: repeat(3, 1fr)"},{"it":"grid: 3","en":"grid: 3"},{"it":"flex: 3","en":"flex: 3"}]',1,'{"it":"`repeat()` evita di ripetere `1fr 1fr 1fr`.","en":"`repeat()` saves writing `1fr 1fr 1fr`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),3,2,'{"it":"Che cosa fa `grid-column: 1 / 3`?","en":"What does `grid-column: 1 / 3` do?"}','[{"it":"Occupa tre colonne","en":"It takes three columns"},{"it":"Va dalla linea 1 alla linea 3","en":"It goes from line 1 to line 3"},{"it":"Divide per tre","en":"It divides by three"},{"it":"Crea tre righe","en":"It creates three rows"}]',1,'{"it":"Le linee sono i bordi tra le colonne: l’elemento occupa due colonne.","en":"Lines are the edges between columns: the element takes two columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),1,2,'{"it":"Che cosa significa *mobile first*?","en":"What does *mobile first* mean?"}','[{"it":"Sviluppare solo per telefoni e nascondere il sito ai computer","en":"Developing for phones only and hiding the site from computers"},{"it":"Partire dal telefono e aggiungere regole per gli schermi grandi","en":"Starting from the phone and adding rules for large screens"},{"it":"Usare un’app","en":"Using an app"},{"it":"Nascondere il desktop","en":"Hiding the desktop"}]',1,'{"it":"Si usano media query con `min-width`.","en":"It uses media queries with `min-width`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),2,2,'{"it":"Quando si applica `@media (min-width: 700px)`?","en":"When does `@media (min-width: 700px)` apply?"}','[{"it":"Sotto i 700px","en":"Under 700px"},{"it":"Da 700px in su","en":"From 700px up"},{"it":"Solo a 700px","en":"Only at 700px"},{"it":"Sempre","en":"Always"}]',1,'{"it":"`min-width` significa «almeno questa larghezza».","en":"`min-width` means “at least this width”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),3,2,'{"it":"Che cosa fa `clamp(1rem, 4vw, 2rem)`?","en":"What does `clamp(1rem, 4vw, 2rem)` do?"}','[{"it":"Sceglie a caso","en":"Picks at random"},{"it":"Tiene `4vw` tra 1rem e 2rem","en":"Keeps `4vw` between 1rem and 2rem"},{"it":"Somma i valori","en":"Adds the values"},{"it":"Blocca il font","en":"Locks the font"}]',1,'{"it":"Un valore fluido, con un minimo e un massimo.","en":"A fluid value, with a minimum and a maximum."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),1,2,'{"it":"Come si dichiara una variabile CSS?","en":"How do you declare a CSS variable?"}','[{"it":"$brand: red","en":"$brand: red"},{"it":"--brand: red","en":"--brand: red"},{"it":"@brand: red","en":"@brand: red"},{"it":"var brand = red","en":"var brand = red"}]',1,'{"it":"Inizia con due trattini e si dichiara dentro un selettore.","en":"It starts with two dashes and is declared inside a selector."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),2,2,'{"it":"Dove si dichiarano di solito le variabili globali?","en":"Where are global variables usually declared?"}','[{"it":":root","en":":root"},{"it":"head","en":"head"},{"it":"body::before","en":"body::before"},{"it":"@global","en":"@global"}]',0,'{"it":"`:root` è l’elemento radice, cioè `html`.","en":"`:root` is the root element, that is `html`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),3,2,'{"it":"A cosa serve il secondo argomento di `var()`?","en":"What is the second argument of `var()` for?"}','[{"it":"Al tipo","en":"The type"},{"it":"Al valore di riserva","en":"The fallback value"},{"it":"Alla durata","en":"The duration"},{"it":"All’unità","en":"The unit"}]',1,'{"it":"Si usa se la variabile non è definita.","en":"It is used if the variable is not defined."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),1,3,'{"it":"Quale proprietà anima il passaggio tra due stati?","en":"Which property animates the change between two states?"}','[{"it":"animation-state","en":"animation-state"},{"it":"transition","en":"transition"},{"it":"change","en":"change"},{"it":"keyframes","en":"keyframes"}]',1,'{"it":"Si scrive sullo stato di partenza, con durata e curva.","en":"It goes on the starting state, with duration and curve."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),2,3,'{"it":"Con che cosa si definiscono i passaggi di un’animazione?","en":"What defines the steps of an animation?"}','[{"it":"@media","en":"@media"},{"it":"@keyframes","en":"@keyframes"},{"it":"@animate","en":"@animate"},{"it":"@steps","en":"@steps"}]',1,'{"it":"Poi si applica con la proprietà `animation`.","en":"It is then applied with the `animation` property."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),3,3,'{"it":"Quale media query rispetta chi chiede meno movimento?","en":"Which media query respects those asking for less motion?"}','[{"it":"prefers-reduced-motion","en":"prefers-reduced-motion"},{"it":"no-animation","en":"no-animation"},{"it":"motion: off","en":"motion: off"},{"it":"reduced-data","en":"reduced-data"}]',0,'{"it":"Il sistema operativo la espone come preferenza di accessibilità.","en":"The operating system exposes it as an accessibility preference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),1,3,'{"it":"Che cosa serve sempre a `::before`?","en":"What does `::before` always need?"}','[{"it":"content","en":"content"},{"it":"display","en":"display"},{"it":"width","en":"width"},{"it":"color","en":"color"}]',0,'{"it":"Senza `content` non viene creato nulla.","en":"Without `content` nothing is created."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),2,3,'{"it":"Quali elementi sceglie `li:nth-child(even)`?","en":"Which elements does `li:nth-child(even)` pick?"}','[{"it":"I pari","en":"The even ones"},{"it":"I dispari","en":"The odd ones"},{"it":"Il primo","en":"The first"},{"it":"Tutti","en":"All of them"}]',0,'{"it":"`even` è pari, `odd` dispari.","en":"`even` is even, `odd` is odd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),3,3,'{"it":"Come si scrive uno pseudo-elemento?","en":"How is a pseudo-element written?"}','[{"it":"Con `::`","en":"With `::`"},{"it":"Con `#`","en":"With `#`"},{"it":"Con `$`","en":"With `$`"},{"it":"Con `@`","en":"With `@`"}]',0,'{"it":"Due punti doppi lo distinguono da una pseudo-classe.","en":"The double colon sets it apart from a pseudo-class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),1,3,'{"it":"Che cosa sceglie `.card:has(img)`?","en":"What does `.card:has(img)` pick?"}','[{"it":"Le card con un’immagine","en":"Cards with an image"},{"it":"Le immagini","en":"The images"},{"it":"Tutte le card","en":"All cards"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Si guarda dentro, ma viene scelto il genitore.","en":"It looks inside, but the parent is picked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),2,3,'{"it":"A che cosa guarda `@container`?","en":"What does `@container` look at?"}','[{"it":"Al contenitore","en":"The container"},{"it":"Allo schermo","en":"The screen"},{"it":"Al font","en":"The font"},{"it":"Al server","en":"The server"}]',0,'{"it":"Un componente si adatta allo spazio che ha davvero.","en":"A component adapts to the space it really has."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),3,3,'{"it":"Il CSS moderno può annidare le regole?","en":"Can modern CSS nest rules?"}','[{"it":"Sì","en":"Yes"},{"it":"No, solo SCSS","en":"No, only SCSS"},{"it":"Solo in `@media`","en":"Only in `@media`"},{"it":"Solo con JavaScript","en":"Only with JavaScript"}]',0,'{"it":"Il nesting ora è nel CSS nativo, con `&`.","en":"Nesting is now in native CSS, with `&`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),1,2,'{"it":"Dove si scrive `transition`?","en":"Where does `transition` go?"}','[{"it":"Sullo stato normale","en":"On the normal state"},{"it":"Solo su `:hover`","en":"Only on `:hover`"},{"it":"Nell’HTML","en":"In the HTML"},{"it":"In `@media`","en":"In `@media`"}]',0,'{"it":"Così l’effetto vale nei due sensi.","en":"So the effect works both ways."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),2,2,'{"it":"Quanto dura `.3s`?","en":"How long is `.3s`?"}','[{"it":"300 millisecondi","en":"300 milliseconds"},{"it":"3 secondi","en":"3 seconds"},{"it":"30 secondi","en":"30 seconds"},{"it":"3 minuti","en":"3 minutes"}]',0,'{"it":"Tra 150 e 300ms un’interfaccia sembra rapida.","en":"Between 150 and 300ms an interface feels quick."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),3,2,'{"it":"Si può animare `display`?","en":"Can you animate `display`?"}','[{"it":"Di solito no","en":"Usually not"},{"it":"Sempre","en":"Always"},{"it":"Solo in rosso","en":"Only in red"},{"it":"Solo nei link","en":"Only in links"}]',0,'{"it":"Si anima ciò che ha valori intermedi, come `opacity`.","en":"You animate what has in-between values, like `opacity`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),1,2,'{"it":"Quale funzione sposta?","en":"Which function moves?"}','[{"it":"translate()","en":"translate()"},{"it":"move()","en":"move()"},{"it":"shift()","en":"shift()"},{"it":"go()","en":"go()"}]',0,'{"it":"Esistono `translateX` e `translateY`.","en":"There are `translateX` and `translateY`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),2,2,'{"it":"`transform` sposta gli altri elementi?","en":"Does `transform` move other elements?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo i fratelli","en":"Only siblings"},{"it":"Solo il genitore","en":"Only the parent"}]',0,'{"it":"Lo spazio occupato resta quello di prima.","en":"The space taken stays as before."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),3,2,'{"it":"Che cosa cambia `transform-origin`?","en":"What does `transform-origin` change?"}','[{"it":"Il punto di riferimento","en":"The reference point"},{"it":"La durata","en":"The duration"},{"it":"Il colore","en":"The colour"},{"it":"La curva","en":"The curve"}]',0,'{"it":"Una rotazione da un angolo sembra una porta.","en":"A rotation from a corner looks like a door."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),1,2,'{"it":"Che cosa definisce `@keyframes`?","en":"What does `@keyframes` define?"}','[{"it":"Le tappe di un’animazione","en":"The stages of an animation"},{"it":"Un font","en":"A font"},{"it":"Una variabile","en":"A variable"},{"it":"Una media query","en":"A media query"}]',0,'{"it":"Si usa poi con `animation`.","en":"It is then used with `animation`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),2,2,'{"it":"Come si ripete per sempre?","en":"How does it repeat for ever?"}','[{"it":"infinite","en":"infinite"},{"it":"loop","en":"loop"},{"it":"always","en":"always"},{"it":"repeat","en":"repeat"}]',0,'{"it":"Oppure un numero di giri.","en":"Or a number of rounds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),3,2,'{"it":"`from` e `to` equivalgono a…","en":"`from` and `to` are the same as…"}','[{"it":"0% e 100%","en":"0% e 100%"},{"it":"1 e 2","en":"1 e 2"},{"it":"start e end","en":"start e end"},{"it":"A e B","en":"A e B"}]',0,'{"it":"Per le tappe intermedie servono le percentuali.","en":"In-between stages need percentages."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),1,3,'{"it":"Quale curva frena alla fine?","en":"Which curve brakes at the end?"}','[{"it":"ease-out","en":"ease-out"},{"it":"ease-in","en":"ease-in"},{"it":"linear","en":"linear"},{"it":"step","en":"step"}]',0,'{"it":"È la più naturale per ciò che entra in scena.","en":"It is the most natural for things entering the scene."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),2,3,'{"it":"Che cosa fa `forwards`?","en":"What does `forwards` do?"}','[{"it":"Tiene l’ultima tappa","en":"Keeps the last stage"},{"it":"Salta avanti","en":"Skips ahead"},{"it":"Va più veloce","en":"Goes faster"},{"it":"Ripete","en":"Repeats"}]',0,'{"it":"Senza, l’elemento torna com’era.","en":"Without it, the element goes back to how it was."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),3,3,'{"it":"Perché scaglionare i ritardi in una lista?","en":"Why stagger delays in a list?"}','[{"it":"Per un effetto a cascata","en":"For a cascade effect"},{"it":"Per pesare meno","en":"To weigh less"},{"it":"Per la SEO","en":"For SEO"},{"it":"Per il colore","en":"For colour"}]',0,'{"it":"L’occhio segue meglio una cosa alla volta.","en":"The eye follows one thing at a time better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),1,3,'{"it":"Quali proprietà conviene animare?","en":"Which properties are best to animate?"}','[{"it":"`transform` e `opacity`","en":"`transform` and `opacity`"},{"it":"`width` e `height`","en":"`width` and `height`"},{"it":"`margin` e `top`","en":"`margin` and `top`"},{"it":"`font-size`","en":"`font-size`"}]',0,'{"it":"Non costringono a ricalcolare la pagina.","en":"They do not force the page to be recalculated."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),2,3,'{"it":"Che cosa rispetta `prefers-reduced-motion`?","en":"What does `prefers-reduced-motion` respect?"}','[{"it":"Chi chiede meno movimento","en":"People asking for less movement"},{"it":"Chi ha uno schermo piccolo","en":"People with a small screen"},{"it":"Chi usa Safari","en":"Safari users"},{"it":"Chi è offline","en":"Offline users"}]',0,'{"it":"È una preferenza del sistema operativo.","en":"It is an operating system preference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),3,3,'{"it":"A che cosa deve servire un’animazione?","en":"What should an animation do?"}','[{"it":"A spiegare","en":"Explain"},{"it":"A distrarre","en":"Distract"},{"it":"A rallentare","en":"Slow things down"},{"it":"A stupire sempre","en":"Always amaze"}]',0,'{"it":"Se non aiuta a capire, togliila.","en":"If it does not help understanding, remove it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),1,2,'{"it":"Il browser sa leggere un file `.scss`?","en":"Can the browser read a `.scss` file?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, va compilato in CSS","en":"No, it must be compiled to CSS"},{"it":"Solo Chrome","en":"Only Chrome"},{"it":"Solo con JavaScript attivo","en":"Only with JavaScript on"}]',1,'{"it":"Il compilatore trasforma SCSS in CSS.","en":"The compiler turns SCSS into CSS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),2,2,'{"it":"Con quale simbolo inizia una variabile SCSS?","en":"Which symbol starts an SCSS variable?"}','[{"it":"--","en":"--"},{"it":"@","en":"@"},{"it":"$","en":"$"},{"it":"#","en":"#"}]',2,'{"it":"`$` per Sass, `--` per le variabili CSS.","en":"`$` for Sass, `--` for CSS variables."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),3,2,'{"it":"Un file CSS valido è anche SCSS valido?","en":"Is a valid CSS file also valid SCSS?"}','[{"it":"Sì","en":"Yes"},{"it":"No","en":"No"},{"it":"Solo senza commenti","en":"Only with no comments"},{"it":"Solo senza media query","en":"Only with no media queries"}]',0,'{"it":"Per questo si può iniziare rinominando il file.","en":"That is why you can start by renaming the file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),1,2,'{"it":"Che cosa indica `&`?","en":"What does `&` stand for?"}','[{"it":"Il selettore genitore","en":"The parent selector"},{"it":"Una variabile","en":"A variable"},{"it":"Tutti i figli","en":"All the children"},{"it":"Un commento","en":"A comment"}]',0,'{"it":"Viene sostituito dal selettore che lo contiene.","en":"It is replaced by the selector containing it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),2,2,'{"it":"In che cosa si compila `.a { &:hover { … } }`?","en":"What does `.a { &:hover { … } }` compile to?"}','[{"it":".a :hover","en":".a :hover"},{"it":".a:hover","en":".a:hover"},{"it":".hover .a","en":".hover .a"},{"it":":hover.a","en":":hover.a"}]',1,'{"it":"`&` unisce senza spazio.","en":"`&` joins with no space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),3,2,'{"it":"Perché non annidare troppo?","en":"Why not nest too deep?"}','[{"it":"Il compilatore si blocca","en":"The compiler stops"},{"it":"I selettori diventano lunghi e difficili da sovrascrivere","en":"Selectors become long and hard to override"},{"it":"Il browser rallenta del tutto","en":"The browser stalls completely"},{"it":"Non è permesso","en":"It is not allowed"}]',1,'{"it":"Lo stesso annidamento aumenta anche la specificità.","en":"Nesting also raises specificity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),1,2,'{"it":"Come si usa un mixin?","en":"How do you use a mixin?"}','[{"it":"@use","en":"@use"},{"it":"@include","en":"@include"},{"it":"@mixin","en":"@mixin"},{"it":"@apply","en":"@apply"}]',1,'{"it":"`@mixin` lo definisce, `@include` lo inserisce.","en":"`@mixin` defines it, `@include` inserts it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),2,2,'{"it":"Quale vantaggio hanno i mixin rispetto a `@extend`?","en":"What advantage do mixins have over `@extend`?"}','[{"it":"Accettano parametri","en":"They accept parameters"},{"it":"Sono più corti","en":"They are shorter"},{"it":"Non si compilano","en":"They are not compiled"},{"it":"Funzionano in HTML","en":"They work in HTML"}]',0,'{"it":"Un mixin produce regole diverse a seconda degli argomenti.","en":"A mixin produces different rules depending on its arguments."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),3,2,'{"it":"Che cosa fa un selettore `%segnaposto` da solo?","en":"What does a `%placeholder` selector do alone?"}','[{"it":"Produce CSS","en":"It produces CSS"},{"it":"Nulla finché non viene esteso","en":"Nothing until it is extended"},{"it":"Dà errore","en":"It raises an error"},{"it":"Crea una classe","en":"It creates a class"}]',1,'{"it":"È pensato solo per `@extend`.","en":"It is meant only for `@extend`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),1,3,'{"it":"Con quale regola si carica un modulo?","en":"Which rule loads a module?"}','[{"it":"@use","en":"@use"},{"it":"@load","en":"@load"},{"it":"@require","en":"@require"},{"it":"@module","en":"@module"}]',0,'{"it":"`@use` sostituisce il vecchio `@import`.","en":"`@use` replaces the old `@import`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),2,3,'{"it":"Come si chiama un partial?","en":"How is a partial named?"}','[{"it":"colori.part.scss","en":"colori.part.scss"},{"it":"_colori.scss","en":"_colori.scss"},{"it":"#colori.scss","en":"#colori.scss"},{"it":"colori_.css","en":"colori_.css"}]',1,'{"it":"Il trattino basso dice di non compilarlo da solo.","en":"The underscore says not to compile it alone."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),3,3,'{"it":"A che cosa serve `#{ }`?","en":"What is `#{ }` for?"}','[{"it":"A commentare","en":"To comment"},{"it":"A interpolare un valore in un nome","en":"To interpolate a value into a name"},{"it":"A importare un file parziale nel foglio principale","en":"To import a partial file into the main stylesheet"},{"it":"A selezionare un id","en":"To select an id"}]',1,'{"it":"Si chiama interpolazione.","en":"It is called interpolation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'functions'),1,3,'{"it":"Che cosa restituisce una `@function`?","en":"What does an `@function` give back?"}','[{"it":"Un valore","en":"A value"},{"it":"Delle regole","en":"Rules"},{"it":"Un file","en":"A file"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le regole sono il lavoro dei mixin.","en":"Rules are the job of mixins."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'functions'),2,3,'{"it":"Quale parola chiude una funzione?","en":"Which word ends a function?"}','[{"it":"@return","en":"@return"},{"it":"@end","en":"@end"},{"it":"@give","en":"@give"},{"it":"@out","en":"@out"}]',0,'{"it":"`@return` indica il risultato.","en":"`@return` gives the result."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'functions'),3,3,'{"it":"Quanto vale `spazio(2)` nell’esempio?","en":"What is `spazio(2)` in the example?"}','[{"it":"16px","en":"16px"},{"it":"8px","en":"8px"},{"it":"2px","en":"2px"},{"it":"10px","en":"10px"}]',0,'{"it":"2 × 8px.","en":"2 × 8px."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),1,3,'{"it":"Con che cosa inizia un file parziale?","en":"What does a partial file start with?"}','[{"it":"_","en":"_"},{"it":"-","en":"-"},{"it":"@","en":"@"},{"it":"$","en":"$"}]',0,'{"it":"Il trattino basso dice al compilatore di non crearne un `.css`.","en":"The underscore tells the compiler not to create a `.css` for it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),2,3,'{"it":"Nel `@use` si scrive il `_`?","en":"Do you write the `_` in `@use`?"}','[{"it":"No","en":"No"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo in Sass","en":"Only in Sass"},{"it":"Solo due volte","en":"Only twice"}]',0,'{"it":"Basta il nome: `@use \\"bottoni\\"`.","en":"The name is enough: `@use \\"bottoni\\"`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),3,3,'{"it":"Quanti CSS produce di solito il progetto?","en":"How many CSS files does the project usually produce?"}','[{"it":"Uno","en":"One"},{"it":"Uno per parziale","en":"One per partial"},{"it":"Nessuno","en":"None"},{"it":"Due","en":"Two"}]',0,'{"it":"Un solo file è più veloce da scaricare.","en":"A single file is quicker to download."}',NULL);
