INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),3,2,'{"it":"Il CSS prodotto da `.sass` e `.scss` è diverso?","en":"Is the CSS produced by `.sass` and `.scss` different?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, è lo stesso","en":"No, it is the same"},{"it":"Solo nei colori","en":"Only in colours"},{"it":"Solo nelle media query","en":"Only in media queries"}]',1,'{"it":"Sono due sintassi dello stesso linguaggio.","en":"They are two syntaxes of the same language."}',NULL);
