INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'server'),3,2,'{"it":"Che cosa mostra `DESCRIBE prodotti`?","en":"What does `DESCRIBE prodotti` show?"}','[{"it":"Le righe della tabella","en":"The table rows"},{"it":"Colonne, tipi e chiavi","en":"Columns, types and keys"},{"it":"Chi ha creato la tabella","en":"Who created the table"},{"it":"Lo spazio su disco","en":"The disk space"}]',1,'{"it":"È la struttura, non il contenuto.","en":"It is the structure, not the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'types'),1,2,'{"it":"Perché preferire `utf8mb4` a `utf8`?","en":"Why prefer `utf8mb4` to `utf8`?"}','[{"it":"È più veloce","en":"It is faster"},{"it":"Regge emoji e tutti i caratteri","en":"It holds emoji and every character"},{"it":"Occupa sempre meno spazio","en":"It always takes less space"},{"it":"È l’unico con gli indici","en":"It is the only one with indexes"}]',1,'{"it":"Il vecchio `utf8` si ferma a 3 byte.","en":"The old `utf8` stops at 3 bytes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'types'),2,2,'{"it":"Che cosa fa `ENUM(''a'', ''b'')`?","en":"What does `ENUM(''a'', ''b'')` do?"}','[{"it":"Accetta solo i valori elencati","en":"Accepts only the listed values"},{"it":"Numera le righe","en":"Numbers the rows"},{"it":"Crea due colonne","en":"Creates two columns"},{"it":"Cifra il testo","en":"Encrypts the text"}]',0,'{"it":"Un elenco chiuso di valori.","en":"A closed list of values."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'types'),3,2,'{"it":"Che cosa vieta `UNSIGNED`?","en":"What does `UNSIGNED` forbid?"}','[{"it":"I valori nulli","en":"Null values"},{"it":"I numeri negativi","en":"Negative numbers"},{"it":"I doppioni","en":"Duplicates"},{"it":"I decimali","en":"Decimals"}]',1,'{"it":"In cambio il massimo positivo raddoppia.","en":"In exchange the positive maximum doubles."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'upsert'),1,2,'{"it":"Quando scatta `ON DUPLICATE KEY UPDATE`?","en":"When does `ON DUPLICATE KEY UPDATE` fire?"}','[{"it":"Sempre","en":"Always"},{"it":"Quando una chiave unica sarebbe ripetuta","en":"When a unique key would repeat"},{"it":"Quando la tabella è vuota","en":"When the table is empty"},{"it":"Solo nelle transazioni","en":"Only in transactions"}]',1,'{"it":"Serve una chiave primaria o `UNIQUE`.","en":"It needs a primary or `UNIQUE` key."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'upsert'),2,2,'{"it":"Che cosa fa `INSERT IGNORE` con una riga doppia?","en":"What does `INSERT IGNORE` do with a duplicate row?"}','[{"it":"La salta","en":"Skips it"},{"it":"La sovrascrive","en":"Overwrites it"},{"it":"Blocca tutto con un errore","en":"Stops everything with an error"},{"it":"La duplica comunque","en":"Duplicates it anyway"}]',0,'{"it":"Niente errore, niente riga.","en":"No error, no row."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'upsert'),3,2,'{"it":"Perché `REPLACE` può essere pericoloso?","en":"Why can `REPLACE` be dangerous?"}','[{"it":"Cancella e reinserisce la riga","en":"It deletes and reinserts the row"},{"it":"È lentissimo","en":"It is very slow"},{"it":"Non esiste in MySQL","en":"It does not exist in MySQL"},{"it":"Svuota la tabella","en":"It empties the table"}]',0,'{"it":"Nuovo id e cancellazioni a cascata.","en":"New id and cascading deletes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'json'),1,3,'{"it":"Che cosa restituisce `dati->>''$.nome''`?","en":"What does `dati->>''$.nome''` return?"}','[{"it":"Il nome come testo semplice","en":"The name as plain text"},{"it":"Il nome tra virgolette JSON","en":"The name in JSON quotes"},{"it":"Tutto il documento","en":"The whole document"},{"it":"Un errore","en":"An error"}]',0,'{"it":"`->` lo darebbe tra virgolette.","en":"`->` would give it in quotes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'json'),2,3,'{"it":"Da quale simbolo parte un percorso JSON?","en":"Which symbol does a JSON path start with?"}','[{"it":"$","en":"$"},{"it":"#","en":"#"},{"it":"@","en":"@"},{"it":"&","en":"&"}]',0,'{"it":"`$` è la radice del documento.","en":"`$` is the document root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'json'),3,3,'{"it":"Come indicizzi un campo dentro una colonna JSON?","en":"How do you index a field inside a JSON column?"}','[{"it":"Con una colonna generata","en":"With a generated column"},{"it":"Non si può","en":"You cannot"},{"it":"Con `ENUM`","en":"With `ENUM`"},{"it":"Con `REPLACE`","en":"With `REPLACE`"}]',0,'{"it":"La colonna generata si indicizza come le altre.","en":"The generated column is indexed like any other."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'users'),1,3,'{"it":"Che cosa significa `negozio.*` in un `GRANT`?","en":"What does `negozio.*` mean in a `GRANT`?"}','[{"it":"Tutte le tabelle di `negozio`","en":"Every table of `negozio`"},{"it":"Tutti i database","en":"Every database"},{"it":"Tutte le colonne di una tabella","en":"Every column of a table"},{"it":"Tutti gli utenti","en":"Every user"}]',0,'{"it":"database.tabella, con `*` come jolly.","en":"database.table, with `*` as wildcard."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'users'),2,3,'{"it":"Che cosa fa `ROLLBACK`?","en":"What does `ROLLBACK` do?"}','[{"it":"Annulla la transazione","en":"Undoes the transaction"},{"it":"Conferma la transazione","en":"Confirms the transaction"},{"it":"Riavvia il server","en":"Restarts the server"},{"it":"Cancella l’utente","en":"Deletes the user"}]',0,'{"it":"Come se non fosse successo niente.","en":"As if nothing had happened."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'users'),3,3,'{"it":"Perché l’app non deve usare `root`?","en":"Why should the app not use `root`?"}','[{"it":"Per il minimo privilegio","en":"For least privilege"},{"it":"`root` è più lento","en":"`root` is slower"},{"it":"`root` non può leggere","en":"`root` cannot read"},{"it":"È vietato dalla licenza","en":"The licence forbids it"}]',0,'{"it":"Una falla non deve poter fare tutto.","en":"A breach must not be able to do everything."}',NULL);
