INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'fork'),3,2,'{"it":"Il connettore MySQL di PHP funziona con MariaDB?","en":"Does PHP’s MySQL connector work with MariaDB?"}','[{"it":"Sì, il protocollo è lo stesso","en":"Yes, the protocol is the same"},{"it":"No, serve un driver diverso","en":"No, it needs another driver"},{"it":"Solo in sola lettura","en":"Only read only"},{"it":"Solo su Windows","en":"Only on Windows"}]',0,'{"it":"PDO e mysqli si collegano senza cambiare nulla.","en":"PDO and mysqli connect with no changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'returning'),1,2,'{"it":"Che cosa aggiunge `RETURNING` a un `INSERT`?","en":"What does `RETURNING` add to an `INSERT`?"}','[{"it":"Restituisce le colonne delle righe inserite","en":"Returns the columns of the inserted rows"},{"it":"Annulla l’inserimento se qualcosa va storto","en":"Undoes the insert if something goes wrong"},{"it":"Inserisce due volte","en":"Inserts twice"},{"it":"Ordina la tabella","en":"Sorts the table"}]',0,'{"it":"Niente query in più per leggere l’id.","en":"No extra query to read the id."}',NULL);
