INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'returning'),3,2,'{"it":"Qual è l’alternativa classica di MySQL per l’ultimo id?","en":"What is MySQL’s classic alternative for the last id?"}','[{"it":"LAST_INSERT_ID()","en":"LAST_INSERT_ID()"},{"it":"NEXT_ID()","en":"NEXT_ID()"},{"it":"CURRENT_ROW()","en":"CURRENT_ROW()"},{"it":"MAX_ID()","en":"MAX_ID()"}]',0,'{"it":"Vale per l’`AUTO_INCREMENT`.","en":"It covers the `AUTO_INCREMENT`."}',NULL);
