INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'types'),1,2,'{"it":"Come controlli se un array contiene `''sql''`?","en":"How do you check whether an array contains `''sql''`?"}','[{"it":"`''sql'' = ANY(tag)`","en":"`''sql'' = ANY(tag)`"},{"it":"`tag LIKE ''sql''`","en":"`tag LIKE ''sql''`"},{"it":"`tag IN ''sql''`","en":"`tag IN ''sql''`"},{"it":"`HAS(tag, ''sql'')`","en":"`HAS(tag, ''sql'')`"}]',0,'{"it":"`ANY` confronta con ogni elemento.","en":"`ANY` compares with each element."}',NULL);
