INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'jsonb'),2,3,'{"it":"Quale indice si usa per JSONB?","en":"Which index is used for JSONB?"}','[{"it":"GIN","en":"GIN"},{"it":"BTREE","en":"BTREE"},{"it":"HASH","en":"HASH"},{"it":"FULLTEXT","en":"FULLTEXT"}]',0,'{"it":"Indicizza chiavi e valori dentro il documento.","en":"It indexes keys and values inside the document."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'jsonb'),3,3,'{"it":"Perché preferire `JSONB` a `JSON`?","en":"Why prefer `JSONB` to `JSON`?"}','[{"it":"È più veloce da interrogare e si indicizza","en":"It is faster to query and can be indexed"},{"it":"Conserva gli spazi originali","en":"It keeps the original spacing"},{"it":"Occupa zero spazio","en":"It takes zero space"},{"it":"Non serve validarlo","en":"It needs no validation"}]',0,'{"it":"`JSON` tiene solo il testo.","en":"`JSON` only keeps the text."}',NULL);
