INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'roles'),2,3,'{"it":"Che cosa indica `Seq Scan` in un piano?","en":"What does `Seq Scan` mean in a plan?"}','[{"it":"Legge tutta la tabella","en":"It reads the whole table"},{"it":"Usa un indice","en":"It uses an index"},{"it":"La query è fallita","en":"The query failed"},{"it":"Legge in parallelo","en":"It reads in parallel"}]',0,'{"it":"Su tabelle grandi è un campanello.","en":"On big tables it is a warning bell."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'roles'),3,3,'{"it":"Che differenza c’è tra `EXPLAIN` e `EXPLAIN ANALYZE`?","en":"What is the difference between `EXPLAIN` and `EXPLAIN ANALYZE`?"}','[{"it":"`ANALYZE` esegue davvero la query","en":"`ANALYZE` really runs the query"},{"it":"Nessuna","en":"None"},{"it":"`ANALYZE` cancella le statistiche","en":"`ANALYZE` deletes the statistics"},{"it":"`ANALYZE` funziona solo su viste","en":"`ANALYZE` only works on views"}]',0,'{"it":"E mostra i tempi reali.","en":"And shows the real timings."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'file'),1,2,'{"it":"Dove tiene i dati SQLite?","en":"Where does SQLite keep its data?"}','[{"it":"In un unico file","en":"In a single file"},{"it":"In un server remoto","en":"On a remote server"},{"it":"Solo in memoria","en":"Only in memory"},{"it":"In un file per tabella","en":"In one file per table"}]',0,'{"it":"Copi il file e hai copiato il database.","en":"Copy the file and you have copied the database."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'file'),2,2,'{"it":"Che cosa sono i comandi come `.tables`?","en":"What are commands like `.tables`?"}','[{"it":"Comandi della shell sqlite3","en":"sqlite3 shell commands"},{"it":"Istruzioni SQL standard","en":"Standard SQL statements"},{"it":"Errori di battitura","en":"Typos"},{"it":"Funzioni di Python","en":"Python functions"}]',0,'{"it":"Non funzionano da un programma.","en":"They do not work from a program."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'file'),3,2,'{"it":"Quando SQLite non è la scelta giusta?","en":"When is SQLite not the right choice?"}','[{"it":"Con molti utenti che scrivono insieme","en":"With many users writing at once"},{"it":"In un’app mobile","en":"In a mobile app"},{"it":"Per un prototipo","en":"For a prototype"},{"it":"Per i dati di un’app desktop","en":"For a desktop app’s data"}]',0,'{"it":"Le scritture sono una alla volta.","en":"Writes happen one at a time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'types'),1,2,'{"it":"Che cosa succede inserendo `''ciao''` in una colonna `INTEGER` normale?","en":"What happens when inserting `''ciao''` into a normal `INTEGER` column?"}','[{"it":"Viene accettato come testo","en":"It is accepted as text"},{"it":"Errore","en":"Error"},{"it":"Diventa 0","en":"It becomes 0"},{"it":"Diventa NULL","en":"It becomes NULL"}]',0,'{"it":"Il tipo è solo un’affinità.","en":"The type is only an affinity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'types'),2,2,'{"it":"Che cosa fa `STRICT`?","en":"What does `STRICT` do?"}','[{"it":"Rende obbligatori i tipi delle colonne","en":"Makes column types mandatory"},{"it":"Blocca le scritture","en":"Blocks writes"},{"it":"Cifra il file","en":"Encrypts the file"},{"it":"Vieta i NULL ovunque","en":"Forbids NULL everywhere"}]',0,'{"it":"Va in fondo al `CREATE TABLE`.","en":"It goes at the end of `CREATE TABLE`."}',NULL);
