INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'what'),1,1,'{"it":"Che cosa distingue il machine learning?","en":"What sets machine learning apart?"}','[{"it":"Impara dagli esempi","en":"It learns from examples"},{"it":"Usa solo regole scritte a mano","en":"It only uses hand-written rules"},{"it":"Funziona senza dati","en":"It works without data"},{"it":"È sempre generativo","en":"It is always generative"}]',0,'{"it":"Le regole le ricava dai dati.","en":"It derives the rules from data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'what'),2,1,'{"it":"Il deep learning è…","en":"Deep learning is…"}','[{"it":"ML con reti neurali a molti strati","en":"ML with many-layered neural networks"},{"it":"Un database molto grande","en":"A very large database"},{"it":"L’opposto del ML","en":"The opposite of ML"},{"it":"Un linguaggio di programmazione","en":"A programming language"}]',0,'{"it":"“Profondo” per i tanti strati.","en":"“Deep” because of the many layers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'what'),3,1,'{"it":"Quale di questi è AI generativa?","en":"Which of these is generative AI?"}','[{"it":"Un modello che scrive un racconto","en":"A model that writes a story"},{"it":"Un termostato","en":"A thermostat"},{"it":"Un foglio di calcolo","en":"A spreadsheet"},{"it":"Un filtro a regole fisse","en":"A fixed-rule filter"}]',0,'{"it":"Crea contenuti nuovi.","en":"It creates new content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'data'),1,1,'{"it":"Che cosa succede durante l’addestramento?","en":"What happens during training?"}','[{"it":"Il modello regola i parametri sugli esempi","en":"The model tunes its parameters on examples"},{"it":"Il modello risponde agli utenti","en":"The model answers users"},{"it":"Si cancellano i dati","en":"The data is deleted"},{"it":"Si scrive il codice dell’app","en":"The app code is written"}]',0,'{"it":"L’inferenza viene dopo.","en":"Inference comes after."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'data'),2,1,'{"it":"Che cos’è l’inferenza?","en":"What is inference?"}','[{"it":"Usare il modello su dati nuovi","en":"Using the model on new data"},{"it":"Raccogliere dati","en":"Collecting data"},{"it":"Ripulire i dati","en":"Cleaning the data"},{"it":"Comprare GPU","en":"Buying GPUs"}]',0,'{"it":"È quello che fai quando chatti con un modello.","en":"It is what you do when you chat with a model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'data'),3,1,'{"it":"Perché si tiene da parte un test set?","en":"Why keep a test set aside?"}','[{"it":"Per misurare il modello su dati mai visti","en":"To measure the model on unseen data"},{"it":"Per addestrare più velocemente","en":"To train faster"},{"it":"Per risparmiare spazio","en":"To save space"},{"it":"Per fare un backup","en":"To make a backup"}]',0,'{"it":"Altrimenti il voto sarebbe falsato.","en":"Otherwise the score would be inflated."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'llm'),1,1,'{"it":"Che cosa fa, alla base, un LLM?","en":"What does an LLM do, at its core?"}','[{"it":"Prevede il token successivo","en":"Predicts the next token"},{"it":"Cerca la risposta in un database","en":"Looks the answer up in a database"},{"it":"Copia pagine web intere","en":"Copies whole web pages"},{"it":"Esegue regole scritte a mano","en":"Runs hand-written rules"}]',0,'{"it":"Un token dopo l’altro.","en":"One token after another."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'llm'),2,1,'{"it":"Che cos’è un token?","en":"What is a token?"}','[{"it":"Un pezzo di testo, spesso parte di una parola","en":"A piece of text, often part of a word"},{"it":"Una password","en":"A password"},{"it":"Una moneta digitale","en":"A digital coin"},{"it":"Una riga di codice del programma","en":"A line of the program’s code"}]',0,'{"it":"Si paga e si misura in token.","en":"You pay and measure in tokens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'llm'),3,1,'{"it":"Che cos’è la finestra di contesto?","en":"What is the context window?"}','[{"it":"Quanto testo il modello considera in una volta","en":"How much text the model considers at once"},{"it":"La finestra della chat dove scrivi","en":"The chat window where you type"},{"it":"Il tempo di risposta","en":"The response time"},{"it":"Il numero di utenti","en":"The number of users"}]',0,'{"it":"Oltre quel limite il testo non entra.","en":"Beyond that limit text does not fit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'limits'),1,2,'{"it":"Che cos’è un’allucinazione?","en":"What is a hallucination?"}','[{"it":"Un’informazione inventata detta con sicurezza","en":"Made-up information stated confidently"},{"it":"Un errore di rete durante la risposta","en":"A network error during the answer"},{"it":"Un’immagine generata","en":"A generated image"},{"it":"Un modello spento","en":"A model that is off"}]',0,'{"it":"Plausibile non vuol dire vero.","en":"Plausible does not mean true."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'limits'),2,2,'{"it":"Che cos’è la data di taglio?","en":"What is the knowledge cutoff?"}','[{"it":"Il limite dei fatti che il modello conosce","en":"The limit of facts the model knows"},{"it":"La scadenza dell’abbonamento","en":"The subscription expiry"},{"it":"La lunghezza massima della risposta","en":"The maximum answer length"},{"it":"L’ora di manutenzione","en":"The maintenance hour"}]',0,'{"it":"Dopo quella data non sa, a meno che cerchi.","en":"After that date it does not know, unless it searches."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'limits'),3,2,'{"it":"Qual è una buona difesa dalle allucinazioni?","en":"What is a good defence against hallucinations?"}','[{"it":"Verificare le fonti citate","en":"Checking the cited sources"},{"it":"Fare domande più lunghe","en":"Asking longer questions"},{"it":"Usare il maiuscolo","en":"Using capital letters"},{"it":"Ripetere la domanda finché piace la risposta","en":"Repeating the question until you like the answer"}]',0,'{"it":"Le fonti si controllano.","en":"Sources must be checked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'uses'),1,2,'{"it":"Suggerire un film in base a quelli visti è…","en":"Suggesting a film based on those you watched is…"}','[{"it":"Raccomandazione","en":"Recommendation"},{"it":"Visione","en":"Vision"},{"it":"Traduzione","en":"Translation"},{"it":"Compressione","en":"Compression"}]',0,'{"it":"Impara dai gusti simili.","en":"It learns from similar tastes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'uses'),2,2,'{"it":"Quale compito è ad alto rischio?","en":"Which task is high risk?"}','[{"it":"Decidere chi riceve un prestito","en":"Deciding who gets a loan"},{"it":"Suggerire una canzone","en":"Suggesting a song"},{"it":"Correggere un refuso","en":"Fixing a typo"},{"it":"Scegliere un emoji","en":"Picking an emoji"}]',0,'{"it":"Tocca diritti e opportunità.","en":"It touches rights and opportunities."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'uses'),3,2,'{"it":"Quale legge europea regola l’AI?","en":"Which European law regulates AI?"}','[{"it":"AI Act","en":"AI Act"},{"it":"GDPR Act","en":"GDPR Act"},{"it":"Digital Cookie Act","en":"Digital Cookie Act"},{"it":"Code Act","en":"Code Act"}]',0,'{"it":"Classifica i sistemi per livello di rischio.","en":"It classifies systems by risk level."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'clear'),1,1,'{"it":"Che cosa rende migliore un prompt?","en":"What makes a prompt better?"}','[{"it":"Compito, pubblico e vincoli precisi","en":"Precise task, audience and constraints"},{"it":"Essere il più breve possibile","en":"Being as short as possible"},{"it":"Usare tante emoji","en":"Using lots of emoji"},{"it":"Scrivere tutto in maiuscolo","en":"Writing everything in capitals"}]',0,'{"it":"Il modello non indovina quello che non dici.","en":"The model cannot guess what you do not say."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'clear'),2,1,'{"it":"Qual è il prompt più specifico?","en":"Which prompt is the most specific?"}','[{"it":"Riassumi questo articolo in 5 punti per un manager","en":"Summarise this article in 5 bullet points for a manager"},{"it":"Parlami un po’ di questo articolo, se vuoi","en":"Tell me a bit about this article, if you like"},{"it":"Fai qualcosa di bello","en":"Do something nice"},{"it":"Articolo","en":"Article"}]',0,'{"it":"Compito, formato e pubblico.","en":"Task, format and audience."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'clear'),3,1,'{"it":"Meglio dire “non essere prolisso” o…","en":"Better to say “don’t be verbose” or…"}','[{"it":"“Rispondi in massimo 3 frasi”","en":"“Answer in at most 3 sentences”"},{"it":"“Niente”","en":"“Nothing”"},{"it":"“Sii come vuoi”","en":"“Be however you like”"},{"it":"“Scrivi tanto”","en":"“Write a lot”"}]',0,'{"it":"Dire cosa fare è più chiaro.","en":"Saying what to do is clearer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'context'),1,1,'{"it":"Perché spiegare il motivo di un vincolo?","en":"Why explain the reason for a constraint?"}','[{"it":"Il modello lo applica in modo più sensato","en":"The model applies it more sensibly"},{"it":"Per allungare il prompt","en":"To make the prompt longer"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Per confondere il modello","en":"To confuse the model"}]',0,'{"it":"Capisce lo scopo, non solo la regola.","en":"It grasps the goal, not just the rule."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'context'),2,1,'{"it":"A che cosa serve assegnare un ruolo?","en":"What is assigning a role for?"}','[{"it":"Orientare stile e livello","en":"Steering style and level"},{"it":"Dare accesso a internet","en":"Giving internet access"},{"it":"Rendere il modello più veloce","en":"Making the model faster"},{"it":"Cambiare lingua","en":"Changing language"}]',0,'{"it":"Un tutor parla diverso da un avvocato.","en":"A tutor speaks differently from a lawyer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'context'),3,1,'{"it":"Come separi un documento lungo dalle istruzioni?","en":"How do you separate a long document from the instructions?"}','[{"it":"Con tag come `<documento>`","en":"With tags like `<document>`"},{"it":"Non si separa","en":"You do not"},{"it":"Con tante righe vuote","en":"With many blank lines"},{"it":"Scrivendo in rosso","en":"Writing in red"}]',0,'{"it":"Così il modello sa cosa è cosa.","en":"So the model knows what is what."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'examples'),1,1,'{"it":"Che cos’è un prompt few-shot?","en":"What is a few-shot prompt?"}','[{"it":"Un prompt con alcuni esempi","en":"A prompt with a few examples"},{"it":"Un prompt molto breve","en":"A very short prompt"},{"it":"Un prompt senza istruzioni","en":"A prompt with no instructions"},{"it":"Un prompt in più lingue","en":"A prompt in several languages"}]',0,'{"it":"Zero, uno o pochi esempi.","en":"Zero, one or a few examples."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'examples'),2,1,'{"it":"Perché gli esempi devono essere vari?","en":"Why must examples be varied?"}','[{"it":"Per non far copiare dettagli indesiderati","en":"So unwanted details are not copied"},{"it":"Per allungare la risposta","en":"To lengthen the answer"},{"it":"Perché il modello si annoia","en":"Because the model gets bored"},{"it":"Non serve","en":"It does not matter"}]',0,'{"it":"Il modello imita tutto quello che vede.","en":"The model imitates everything it sees."}',NULL);
