INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'format'),1,2,'{"it":"Quale formato è più comodo da leggere con il codice?","en":"Which format is easiest to read with code?"}','[{"it":"JSON","en":"JSON"},{"it":"Un tema libero","en":"A free essay"},{"it":"Una poesia","en":"A poem"},{"it":"Un elenco disordinato","en":"A messy list"}]',0,'{"it":"Ha una struttura precisa.","en":"It has a precise structure."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'format'),2,2,'{"it":"Perché descrivere i campi del JSON?","en":"Why describe the JSON fields?"}','[{"it":"Così il modello usa nomi e tipi giusti","en":"So the model uses the right names and types"},{"it":"Per abbellire il prompt e renderlo più lungo","en":"To decorate the prompt and make it longer"},{"it":"Non serve mai","en":"It is never needed"},{"it":"Per renderlo più lento","en":"To make it slower"}]',0,'{"it":"Il programma si aspetta quei campi.","en":"The program expects those fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'format'),3,2,'{"it":"Quando aiuta “ragiona passo per passo”?","en":"When does “reason step by step” help?"}','[{"it":"Nei problemi con più passaggi","en":"In multi-step problems"},{"it":"Per salutare","en":"For greetings"},{"it":"Mai","en":"Never"},{"it":"Solo con le immagini","en":"Only with images"}]',0,'{"it":"Spezza il problema.","en":"It breaks the problem down."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'iterate'),1,2,'{"it":"Come si migliora un prompt?","en":"How do you improve a prompt?"}','[{"it":"Provando e correggendo una cosa alla volta","en":"Trying and fixing one thing at a time"},{"it":"Cambiando tutto ogni volta","en":"Changing everything each time"},{"it":"Ripetendo la stessa richiesta","en":"Repeating the same request"},{"it":"Scrivendo più forte","en":"Writing louder"}]',0,'{"it":"Così capisci cosa ha funzionato.","en":"That way you know what worked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'iterate'),2,2,'{"it":"Come affronti un compito molto grande?","en":"How do you tackle a very large task?"}','[{"it":"Lo spezzi in passaggi","en":"Split it into steps"},{"it":"Lo chiedi tutto in una riga","en":"Ask for it all in one line"},{"it":"Lasci perdere","en":"Give up"},{"it":"Lo chiedi in un’altra lingua","en":"Ask in another language"}]',0,'{"it":"Scaletta, sezioni, revisione.","en":"Outline, sections, review."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'iterate'),3,2,'{"it":"Che cosa conviene fare con un prompt che funziona?","en":"What should you do with a prompt that works?"}','[{"it":"Salvarlo come modello","en":"Save it as a template"},{"it":"Cancellarlo","en":"Delete it"},{"it":"Non usarlo più","en":"Never use it again"},{"it":"Renderlo più vago","en":"Make it vaguer"}]',0,'{"it":"Riusarlo fa risparmiare tempo.","en":"Reusing it saves time."}',NULL);
