INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'bias'),2,1,'{"it":"Perché misurare gli errori per gruppo?","en":"Why measure errors per group?"}','[{"it":"Una buona media può nascondere un gruppo svantaggiato","en":"A good average can hide a disadvantaged group"},{"it":"Per fare più grafici e presentazioni","en":"To make more charts and presentations"},{"it":"È più veloce","en":"It is faster"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"L’equità si vede nei dettagli.","en":"Fairness shows in the details."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'bias'),3,1,'{"it":"Che cos’è una variabile “proxy”?","en":"What is a “proxy” variable?"}','[{"it":"Una che rivela indirettamente un dato sensibile","en":"One that indirectly reveals a sensitive attribute"},{"it":"Un server intermedio tra utente e modello","en":"An intermediate server between user and model"},{"it":"Una password","en":"A password"},{"it":"Un tipo di grafico","en":"A type of chart"}]',0,'{"it":"Per esempio il CAP.","en":"For example the postcode."}',NULL);
