INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'privacy'),2,1,'{"it":"Che cosa significa anonimizzare?","en":"What does anonymising mean?"}','[{"it":"Togliere ciò che identifica le persone","en":"Removing what identifies people"},{"it":"Cifrare il computer","en":"Encrypting the computer"},{"it":"Cambiare nome utente","en":"Changing username"},{"it":"Usare la modalità scura","en":"Using dark mode"}]',0,'{"it":"Nomi, email, numeri, indirizzi.","en":"Names, emails, numbers, addresses."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'privacy'),3,1,'{"it":"Quale principio chiede il GDPR?","en":"Which principle does the GDPR require?"}','[{"it":"Usare il minimo di dati necessario","en":"Using the minimum data necessary"},{"it":"Raccogliere più dati possibile","en":"Collecting as much data as possible"},{"it":"Pubblicare i dati","en":"Publishing the data"},{"it":"Nessuna regola","en":"No rules"}]',0,'{"it":"Minimizzazione dei dati.","en":"Data minimisation."}',NULL);
