INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'classification'),2,3,'{"it":"Perché un albero di decisione è facile da spiegare?","en":"Why is a decision tree easy to explain?"}','[{"it":"È una serie di domande sì/no","en":"It is a series of yes/no questions"},{"it":"Non usa dati","en":"It uses no data"},{"it":"È sempre perfetto","en":"It is always perfect"},{"it":"È una rete neurale","en":"It is a neural network"}]',0,'{"it":"Si può disegnare.","en":"You can draw it."}',NULL);
