INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'metrics'),1,3,'{"it":"Perché l’accuratezza può ingannare?","en":"Why can accuracy mislead?"}','[{"it":"Con classi sbilanciate premia chi dice sempre la classe comune","en":"With unbalanced classes it rewards always saying the common class"},{"it":"È sempre sbagliata","en":"It is always wrong"},{"it":"Funziona solo con le immagini e mai con i testi","en":"It only works with images and never with text"},{"it":"Non si può calcolare","en":"It cannot be computed"}]',0,'{"it":"Il 99% può essere inutile.","en":"99% can be useless."}',NULL);
