INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'features'),1,2,'{"it":"Che cosa fa il one-hot encoding?","en":"What does one-hot encoding do?"}','[{"it":"Trasforma categorie in colonne 0/1","en":"Turns categories into 0/1 columns"},{"it":"Cancella le categorie","en":"Deletes categories"},{"it":"Ordina i dati","en":"Sorts the data"},{"it":"Riempie i valori mancanti","en":"Fills missing values"}]',0,'{"it":"Una colonna per categoria.","en":"One column per category."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'features'),2,2,'{"it":"Che cos’è il data leakage?","en":"What is data leakage?"}','[{"it":"Informazioni del test che finiscono nell’addestramento","en":"Test information leaking into training"},{"it":"Un furto di dati dal server di addestramento","en":"A data theft from the training server"},{"it":"Un file corrotto","en":"A corrupted file"},{"it":"Un errore di rete","en":"A network error"}]',0,'{"it":"Rende il voto troppo ottimista.","en":"It makes the score too optimistic."}',NULL);
