INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pipeline'),1,2,'{"it":"Perché usare una pipeline?","en":"Why use a pipeline?"}','[{"it":"Preparazione e modello insieme, senza leakage","en":"Preparation and model together, without leakage"},{"it":"Per rendere il modello più grande","en":"To make the model bigger"},{"it":"Per disegnare grafici","en":"To draw charts"},{"it":"Non serve mai","en":"It is never useful"}]',0,'{"it":"Impara tutto solo sul train.","en":"It learns everything on train only."}',NULL);
