INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pipeline'),3,2,'{"it":"Come salvi una pipeline addestrata?","en":"How do you save a trained pipeline?"}','[{"it":"joblib.dump","en":"joblib.dump"},{"it":"print","en":"print"},{"it":"pipe.close()","en":"pipe.close()"},{"it":"export()","en":"export()"}]',0,'{"it":"E `joblib.load` per ricaricarla.","en":"And `joblib.load` to reload it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'ensembles'),1,2,'{"it":"Come decide una random forest?","en":"How does a random forest decide?"}','[{"it":"Fa votare molti alberi","en":"Many trees vote"},{"it":"Usa un solo albero profondo","en":"It uses one deep tree"},{"it":"A caso","en":"At random"},{"it":"Con una rete neurale","en":"With a neural network"}]',0,'{"it":"La saggezza della folla.","en":"Wisdom of the crowd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'ensembles'),2,2,'{"it":"Che cosa fa ogni nuovo albero nel boosting?","en":"What does each new tree do in boosting?"}','[{"it":"Corregge gli errori dei precedenti","en":"Fixes the previous ones’ errors"},{"it":"Cancella gli altri","en":"Deletes the others"},{"it":"Ripete lo stesso albero","en":"Repeats the same tree"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Un passo alla volta.","en":"One step at a time."}',NULL);
