INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'neurons'),2,2,'{"it":"Perché servono le attivazioni non lineari?","en":"Why are non-linear activations needed?"}','[{"it":"Altrimenti più strati equivalgono a uno","en":"Otherwise many layers equal one"},{"it":"Per velocizzare","en":"To speed up"},{"it":"Per usare meno memoria","en":"To use less memory"},{"it":"Non servono","en":"They are not needed"}]',0,'{"it":"La non linearità dà potenza.","en":"Non-linearity gives power."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'neurons'),3,2,'{"it":"`nn.Linear(4, 16)` collega…","en":"`nn.Linear(4, 16)` connects…"}','[{"it":"4 input a 16 neuroni","en":"4 inputs to 16 neurons"},{"it":"16 input a 4 neuroni","en":"16 inputs to 4 neurons"},{"it":"4 strati","en":"4 layers"},{"it":"16 immagini","en":"16 images"}]',0,'{"it":"Prima gli input, poi le uscite.","en":"Inputs first, then outputs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'tensors'),1,2,'{"it":"Che cosa fa `y.backward()`?","en":"What does `y.backward()` do?"}','[{"it":"Calcola le derivate","en":"Computes the derivatives"},{"it":"Torna indietro di un passo","en":"Goes back one step"},{"it":"Cancella y","en":"Deletes y"},{"it":"Inverte il tensore","en":"Reverses the tensor"}]',0,'{"it":"Autograd.","en":"Autograd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'tensors'),2,2,'{"it":"Che cosa indica `requires_grad=True`?","en":"What does `requires_grad=True` mean?"}','[{"it":"Che servono le derivate di quel tensore","en":"That tensor’s derivatives are needed"},{"it":"Che il tensore viene spostato sulla GPU","en":"That the tensor is moved to the GPU"},{"it":"Che è un intero","en":"That it is an integer"},{"it":"Che è costante","en":"That it is constant"}]',0,'{"it":"Tipico dei pesi.","en":"Typical of weights."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'tensors'),3,2,'{"it":"Come sposti un tensore sulla GPU?","en":"How do you move a tensor to the GPU?"}','[{"it":"Con `.to(\\"cuda\\")`","en":"With `.to(\\"cuda\\")`"},{"it":"Con `.gpu = True`","en":"With `.gpu = True`"},{"it":"Non si può","en":"You cannot"},{"it":"Con `print`","en":"With `print`"}]',0,'{"it":"E il modello va spostato insieme.","en":"And the model must move too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'training'),1,2,'{"it":"Perché si chiama `zero_grad()`?","en":"Why call `zero_grad()`?"}','[{"it":"I gradienti altrimenti si sommano","en":"Otherwise gradients accumulate"},{"it":"Per cancellare il modello","en":"To delete the model"},{"it":"Per fermare l’addestramento","en":"To stop training"},{"it":"Per salvare","en":"To save"}]',0,'{"it":"PyTorch accumula per scelta.","en":"PyTorch accumulates by design."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'training'),2,2,'{"it":"Che cos’è un’epoca?","en":"What is an epoch?"}','[{"it":"Un giro completo sui dati","en":"One full pass over the data"},{"it":"Un solo esempio","en":"A single example"},{"it":"Un’ora di calcolo","en":"An hour of compute"},{"it":"Uno strato","en":"A layer"}]',0,'{"it":"Fatta di tanti batch.","en":"Made of many batches."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'training'),3,2,'{"it":"Quale loss per la classificazione?","en":"Which loss for classification?"}','[{"it":"CrossEntropyLoss","en":"CrossEntropyLoss"},{"it":"MSELoss","en":"MSELoss"},{"it":"L1Loss","en":"L1Loss"},{"it":"ReLU","en":"ReLU"}]',0,'{"it":"MSE è per la regressione.","en":"MSE is for regression."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'cnn'),1,3,'{"it":"Che cosa impara uno strato convoluzionale?","en":"What does a convolutional layer learn?"}','[{"it":"Filtri che riconoscono motivi visivi","en":"Filters recognising visual patterns"},{"it":"Le parole di una frase","en":"The words of a sentence"},{"it":"Le tabelle di un database","en":"Database tables"},{"it":"Il colore dello schermo","en":"The screen colour"}]',0,'{"it":"Bordi, forme, oggetti.","en":"Edges, shapes, objects."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'cnn'),2,3,'{"it":"Che cosa fa `MaxPool2d(2)`?","en":"What does `MaxPool2d(2)` do?"}','[{"it":"Dimezza larghezza e altezza","en":"Halves width and height"},{"it":"Raddoppia l’immagine","en":"Doubles the image"},{"it":"Aggiunge colori","en":"Adds colours"},{"it":"Ruota l’immagine","en":"Rotates the image"}]',0,'{"it":"Tiene il valore massimo di ogni blocco.","en":"Keeps the max of each block."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'cnn'),3,3,'{"it":"Che cos’è il transfer learning?","en":"What is transfer learning?"}','[{"it":"Adattare una rete già addestrata","en":"Adapting an already trained network"},{"it":"Copiare dati da un server","en":"Copying data from a server"},{"it":"Tradurre un modello","en":"Translating a model"},{"it":"Comprimere le immagini","en":"Compressing images"}]',0,'{"it":"Pochi dati, buoni risultati.","en":"Little data, good results."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'regularize'),1,3,'{"it":"Che cosa fa il dropout?","en":"What does dropout do?"}','[{"it":"Spegne a caso dei neuroni in addestramento","en":"Randomly switches off neurons in training"},{"it":"Cancella dati","en":"Deletes data"},{"it":"Ferma la rete","en":"Stops the network"},{"it":"Aggiunge strati nascosti durante l’addestramento","en":"Adds hidden layers during training"}]',0,'{"it":"La rete non dipende da un solo neurone.","en":"The network does not rely on a single neuron."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'regularize'),2,3,'{"it":"Che cos’è l’early stopping?","en":"What is early stopping?"}','[{"it":"Fermarsi quando la validazione non migliora più","en":"Stopping when validation stops improving"},{"it":"Fermarsi alla prima epoca","en":"Stopping at the first epoch"},{"it":"Spegnere il computer","en":"Turning off the computer"},{"it":"Un errore di PyTorch","en":"A PyTorch error"}]',0,'{"it":"Prima di imparare il rumore.","en":"Before learning the noise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'regularize'),3,3,'{"it":"Che cosa fa `rete.eval()`?","en":"What does `rete.eval()` do?"}','[{"it":"Mette la rete in modalità valutazione","en":"Puts the network in evaluation mode"},{"it":"Valuta il codice Python","en":"Evaluates Python code"},{"it":"Addestra la rete","en":"Trains the network"},{"it":"Cancella i pesi","en":"Deletes the weights"}]',0,'{"it":"Il dropout si spegne.","en":"Dropout turns off."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'system'),1,2,'{"it":"Chi scrive di solito il system prompt?","en":"Who usually writes the system prompt?"}','[{"it":"Chi costruisce il servizio","en":"Whoever builds the service"},{"it":"L’utente a ogni messaggio","en":"The user in each message"},{"it":"Il modello da solo","en":"The model itself"},{"it":"Nessuno","en":"Nobody"}]',0,'{"it":"Vale per tutta la conversazione.","en":"It applies to the whole conversation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'system'),2,2,'{"it":"Che cosa conviene mettere in un system prompt?","en":"What belongs in a system prompt?"}','[{"it":"Ruolo, regole, tono e casi limite","en":"Role, rules, tone and edge cases"},{"it":"La domanda dell’utente","en":"The user’s question"},{"it":"Le password","en":"Passwords"},{"it":"Niente, meglio vuoto","en":"Nothing, better empty"}]',0,'{"it":"Il quadro generale.","en":"The general frame."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'system'),3,2,'{"it":"Perché prevedere i casi limite?","en":"Why plan for edge cases?"}','[{"it":"Così il modello sa cosa fare quando la richiesta esce dal previsto","en":"So the model knows what to do when a request goes off-script"},{"it":"Per allungare il testo e sembrare più completi","en":"To lengthen the text and look more thorough"},{"it":"Non serve","en":"It is not needed"},{"it":"Per confondere l’utente","en":"To confuse the user"}]',0,'{"it":"Sono lì che si sbaglia.","en":"That is where mistakes happen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning'),1,2,'{"it":"Quando conviene chiedere di ragionare?","en":"When is asking for reasoning worth it?"}','[{"it":"Nei problemi con più passaggi","en":"In multi-step problems"},{"it":"Per dire “ciao”","en":"To say “hello”"},{"it":"Sempre, anche per compiti banali","en":"Always, even trivial tasks"},{"it":"Mai","en":"Never"}]',0,'{"it":"Costa tempo e token.","en":"It costs time and tokens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning'),2,2,'{"it":"Perché separare ragionamento e risposta con tag?","en":"Why separate reasoning and answer with tags?"}','[{"it":"Per mostrare all’utente solo la risposta","en":"To show the user only the answer"},{"it":"Per abbellire","en":"To decorate"},{"it":"Per rallentare","en":"To slow down"},{"it":"È obbligatorio per legge","en":"The law requires it"}]',0,'{"it":"Il programma estrae `<risposta>`.","en":"The program extracts `<answer>`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning'),3,2,'{"it":"Che cos’è il “thinking” integrato?","en":"What is built-in “thinking”?"}','[{"it":"Un ragionamento del modello prima della risposta","en":"The model’s reasoning before the answer"},{"it":"Un plugin del browser che legge la pagina","en":"A browser plugin that reads the page"},{"it":"Un tipo di database","en":"A kind of database"},{"it":"Una modalità scura","en":"A dark mode"}]',0,'{"it":"Molti modelli recenti lo hanno.","en":"Many recent models have it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'structured'),1,2,'{"it":"Che cosa fa `enum` in uno schema?","en":"What does `enum` do in a schema?"}','[{"it":"Limita i valori ammessi","en":"Limits the allowed values"},{"it":"Numera i campi","en":"Numbers the fields"},{"it":"Cifra il testo","en":"Encrypts text"},{"it":"Rende il campo facoltativo","en":"Makes the field optional"}]',0,'{"it":"Un elenco chiuso.","en":"A closed list."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'structured'),2,2,'{"it":"Perché validare l’output nel codice?","en":"Why validate output in code?"}','[{"it":"Un modello può comunque sbagliare formato","en":"A model can still get the format wrong"},{"it":"Per allungare il programma","en":"To lengthen the program"},{"it":"Non serve mai","en":"It is never needed"},{"it":"Per cambiare lingua","en":"To change language"}]',0,'{"it":"Fidarsi è bene, controllare è meglio.","en":"Trust, but verify."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'structured'),3,2,'{"it":"Che cosa vieta `additionalProperties: false`?","en":"What does `additionalProperties: false` forbid?"}','[{"it":"Campi non previsti","en":"Unexpected fields"},{"it":"I numeri","en":"Numbers"},{"it":"Gli array","en":"Arrays"},{"it":"Le stringhe vuote","en":"Empty strings"}]',0,'{"it":"Solo i campi dello schema.","en":"Only the schema’s fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'chaining'),1,3,'{"it":"Perché spezzare un compito in una catena di prompt?","en":"Why split a task into a prompt chain?"}','[{"it":"Ogni passo è più semplice e verificabile","en":"Each step is simpler and verifiable"},{"it":"Per spendere di più","en":"To spend more"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Per confondere il modello","en":"To confuse the model"}]',0,'{"it":"E puoi scegliere il modello per passo.","en":"And you can pick a model per step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'chaining'),2,3,'{"it":"Che cos’è una eval?","en":"What is an eval?"}','[{"it":"Un insieme di casi di test con risultato atteso","en":"A set of test cases with expected results"},{"it":"Una funzione di JavaScript che esegue il codice","en":"A JavaScript function that runs code"},{"it":"Un tipo di modello","en":"A model type"},{"it":"Un abbonamento","en":"A subscription"}]',0,'{"it":"Misura invece di intuire.","en":"Measure instead of guessing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'chaining'),3,3,'{"it":"Che cos’è LLM-as-judge?","en":"What is LLM-as-judge?"}','[{"it":"Un modello che valuta le risposte secondo criteri","en":"A model grading answers against criteria"},{"it":"Un tribunale digitale per le dispute online","en":"A digital court for online disputes"},{"it":"Un errore di sistema","en":"A system error"},{"it":"Un gioco","en":"A game"}]',0,'{"it":"Utile quando non c’è una sola risposta giusta.","en":"Useful when there is no single right answer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'injection'),1,3,'{"it":"Che cos’è la prompt injection?","en":"What is prompt injection?"}','[{"it":"Istruzioni nascoste in un testo esterno","en":"Instructions hidden in external text"},{"it":"Un modo per velocizzare il modello","en":"A way to speed up the model"},{"it":"Un vaccino","en":"A vaccine"},{"it":"Un formato di file","en":"A file format"}]',0,'{"it":"Il dato si finge istruzione.","en":"Data pretending to be instructions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'injection'),2,3,'{"it":"Qual è la difesa più solida?","en":"What is the sturdiest defence?"}','[{"it":"Limitare i permessi e chiedere conferma per le azioni rischiose","en":"Limiting permissions and confirming risky actions"},{"it":"Scrivere nel prompt “non farti ingannare da nessun testo”","en":"Writing “do not be fooled by any text” in the prompt"},{"it":"Usare il maiuscolo","en":"Using capitals"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Il prompt da solo non basta.","en":"The prompt alone is not enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'injection'),3,3,'{"it":"Perché mettere il testo esterno tra tag?","en":"Why put external text between tags?"}','[{"it":"Per separare dati e istruzioni","en":"To separate data from instructions"},{"it":"Per colorarlo","en":"To colour it"},{"it":"Per tradurlo","en":"To translate it"},{"it":"Per accorciarlo e risparmiare token","en":"To shorten it and save tokens"}]',0,'{"it":"Aiuta, ma non è una garanzia.","en":"It helps, but it is no guarantee."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'messages'),1,2,'{"it":"L’API ricorda la conversazione precedente?","en":"Does the API remember the previous conversation?"}','[{"it":"No, si rimanda la storia a ogni chiamata","en":"No, you resend the history each call"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo il lunedì","en":"Only on Mondays"},{"it":"Solo con la chiave premium","en":"Only with a premium key"}]',0,'{"it":"Ogni richiesta è indipendente.","en":"Each request is independent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'messages'),2,2,'{"it":"Quale ruolo ha il messaggio di chi chiede?","en":"Which role does the asker’s message have?"}','[{"it":"user","en":"user"},{"it":"assistant","en":"assistant"},{"it":"system","en":"system"},{"it":"admin","en":"admin"}]',0,'{"it":"`assistant` è il modello.","en":"`assistant` is the model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'messages'),3,2,'{"it":"Che cosa succede se la risposta raggiunge `max_tokens`?","en":"What happens if the answer hits `max_tokens`?"}','[{"it":"Si interrompe a metà","en":"It stops midway"},{"it":"Continua lo stesso","en":"It continues anyway"},{"it":"Dà errore 404","en":"It returns a 404"},{"it":"Si ripete","en":"It repeats"}]',0,'{"it":"Meglio non tenerlo troppo basso.","en":"Better not set it too low."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tokens'),1,2,'{"it":"Che cosa si paga in un’API LLM?","en":"What do you pay for in an LLM API?"}','[{"it":"Token in ingresso e in uscita","en":"Input and output tokens"},{"it":"Il numero di parole del titolo","en":"The words in the title"},{"it":"Le ore di connessione","en":"Connection hours"},{"it":"I clic","en":"Clicks"}]',0,'{"it":"Con prezzi diversi.","en":"At different prices."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tokens'),2,2,'{"it":"Dove leggi i token usati?","en":"Where do you read the tokens used?"}','[{"it":"usage","en":"usage"},{"it":"headers","en":"headers"},{"it":"model","en":"model"},{"it":"system","en":"system"}]',0,'{"it":"`input_tokens` e `output_tokens`.","en":"`input_tokens` and `output_tokens`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tokens'),3,2,'{"it":"Come risparmi su un prompt lungo che si ripete?","en":"How do you save on a long prompt that repeats?"}','[{"it":"Con il prompt caching","en":"With prompt caching"},{"it":"Scrivendolo in maiuscolo","en":"Writing it in capitals"},{"it":"Rimandandolo due volte","en":"Sending it twice"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Le parti in cache costano molto meno.","en":"Cached parts cost much less."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'streaming'),1,2,'{"it":"Perché usare lo streaming?","en":"Why use streaming?"}','[{"it":"L’utente vede il testo mentre arriva","en":"The user sees text as it arrives"},{"it":"Costa meno token","en":"It costs fewer tokens"},{"it":"Migliora la grammatica","en":"It improves grammar"},{"it":"È obbligatorio","en":"It is mandatory"}]',0,'{"it":"E si evitano i timeout.","en":"And timeouts are avoided."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'streaming'),2,2,'{"it":"Con quale tecnologia arriva spesso lo streaming al browser?","en":"Which technology often carries streaming to the browser?"}','[{"it":"Server-Sent Events","en":"Server-Sent Events"},{"it":"FTP","en":"FTP"},{"it":"SMTP","en":"SMTP"},{"it":"CSV","en":"CSV"}]',0,'{"it":"O i WebSocket.","en":"Or WebSockets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'streaming'),3,2,'{"it":"A che cosa serve `get_final_message()`?","en":"What is `get_final_message()` for?"}','[{"it":"Avere la risposta completa alla fine","en":"Getting the complete answer at the end"},{"it":"Annullare lo stream se è troppo lungo","en":"Cancelling the stream if it is too long"},{"it":"Ricominciare","en":"Restarting"},{"it":"Cambiare modello","en":"Changing model"}]',0,'{"it":"Con testo e usage.","en":"With text and usage."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tools'),1,3,'{"it":"Chi esegue davvero lo strumento?","en":"Who actually runs the tool?"}','[{"it":"Il tuo programma","en":"Your program"},{"it":"Il modello","en":"The model"},{"it":"Il browser dell’utente","en":"The user’s browser"},{"it":"Nessuno","en":"Nobody"}]',0,'{"it":"Il modello chiede, tu esegui.","en":"The model asks, you run."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tools'),2,3,'{"it":"Che cosa indica `stop_reason == \\"tool_use\\"`?","en":"What does `stop_reason == \\"tool_use\\"` mean?"}','[{"it":"Il modello vuole usare uno strumento","en":"The model wants to use a tool"},{"it":"La risposta è finita","en":"The answer is over"},{"it":"C’è un errore","en":"There is an error"},{"it":"Il token è scaduto","en":"The token expired"}]',0,'{"it":"Esegui e rimanda il risultato.","en":"Run it and send the result back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tools'),3,3,'{"it":"Che cosa descrive `input_schema`?","en":"What does `input_schema` describe?"}','[{"it":"Gli argomenti dello strumento","en":"The tool’s arguments"},{"it":"Il risultato","en":"The result"},{"it":"Il prezzo","en":"The price"},{"it":"L’utente","en":"The user"}]',0,'{"it":"Uno schema JSON.","en":"A JSON schema."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'production'),1,3,'{"it":"Dove va tenuta la chiave API?","en":"Where should the API key be kept?"}','[{"it":"In una variabile d’ambiente sul server","en":"In an environment variable on the server"},{"it":"Nel JavaScript del sito","en":"In the site’s JavaScript"},{"it":"Nel README pubblico","en":"In the public README"},{"it":"In un commento del codice","en":"In a code comment"}]',0,'{"it":"Chi la vede la può usare.","en":"Whoever sees it can use it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'production'),2,3,'{"it":"Che cosa fai con un errore 429?","en":"What do you do with a 429 error?"}','[{"it":"Aspetti e riprovi","en":"Wait and retry"},{"it":"Cambi chiave a caso","en":"Swap keys at random"},{"it":"Riprovi all’infinito subito","en":"Retry forever at once"},{"it":"Cancelli l’account","en":"Delete the account"}]',0,'{"it":"Troppe richieste.","en":"Too many requests."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'production'),3,3,'{"it":"Riprovare serve con un errore 400?","en":"Does retrying help with a 400 error?"}','[{"it":"No, la richiesta va corretta","en":"No, the request must be fixed"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo di notte","en":"Only at night"},{"it":"Solo con streaming","en":"Only with streaming"}]',0,'{"it":"L’errore è nella richiesta.","en":"The error is in the request."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'embeddings'),1,3,'{"it":"Che cosa fa il tokenizzatore?","en":"What does the tokeniser do?"}','[{"it":"Divide il testo in token e li numera","en":"Splits text into tokens and numbers them"},{"it":"Traduce il testo in inglese prima del modello","en":"Translates the text into English before the model"},{"it":"Corregge gli errori","en":"Fixes mistakes"},{"it":"Comprime il file","en":"Compresses the file"}]',0,'{"it":"Ogni token ha un id.","en":"Each token has an id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'embeddings'),2,3,'{"it":"Che cosa produce uno strato di embedding?","en":"What does an embedding layer produce?"}','[{"it":"Un vettore per ogni token","en":"A vector per token"},{"it":"Una sola parola","en":"A single word"},{"it":"Un’immagine","en":"An image"},{"it":"Una probabilità","en":"A probability"}]',0,'{"it":"Imparato durante il training.","en":"Learned during training."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'embeddings'),3,3,'{"it":"Che cosa manca a un embedding da solo?","en":"What does an embedding alone lack?"}','[{"it":"Il contesto della frase","en":"The sentence context"},{"it":"I numeri","en":"Numbers"},{"it":"Il vocabolario","en":"The vocabulary"},{"it":"La GPU","en":"The GPU"}]',0,'{"it":"Ci pensa l’attention.","en":"Attention handles it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'attention'),1,3,'{"it":"Che cosa rappresenta la query?","en":"What does the query represent?"}','[{"it":"Che cosa cerca il token","en":"What the token is looking for"},{"it":"Il contenuto da passare","en":"The content to pass on"},{"it":"La posizione","en":"The position"},{"it":"Il vocabolario","en":"The vocabulary"}]',0,'{"it":"La key è cosa offre.","en":"The key is what it offers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'attention'),2,3,'{"it":"Perché si divide per √d?","en":"Why divide by √d?"}','[{"it":"Per tenere stabili i valori prima della softmax","en":"To keep values stable before softmax"},{"it":"Per risparmiare memoria sulla GPU durante il calcolo","en":"To save GPU memory during computation"},{"it":"Per arrotondare","en":"To round"},{"it":"Non si divide","en":"You do not"}]',0,'{"it":"Prodotti troppo grandi saturano la softmax.","en":"Large products saturate the softmax."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'attention'),3,3,'{"it":"A che cosa servono più teste di attention?","en":"What are multiple attention heads for?"}','[{"it":"Imparare relazioni diverse in parallelo","en":"Learning different relations in parallel"},{"it":"Elaborare più lingue nello stesso momento","en":"Handling several languages at the same time"},{"it":"Usare meno GPU","en":"Using fewer GPUs"},{"it":"Leggere immagini","en":"Reading images"}]',0,'{"it":"Una guarda la sintassi, una i riferimenti…","en":"One watches syntax, one references…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'transformer'),1,3,'{"it":"Perché si aggiunge la posizione agli embedding?","en":"Why add position to the embeddings?"}','[{"it":"L’attention da sola non conosce l’ordine","en":"Attention alone does not know order"},{"it":"Per colorare i token","en":"To colour tokens"},{"it":"Per comprimere la frase e usare meno token","en":"To compress the sentence and use fewer tokens"},{"it":"Non si aggiunge","en":"It is not added"}]',0,'{"it":"“Cane morde uomo” ≠ “uomo morde cane”.","en":"“Dog bites man” ≠ “man bites dog”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'transformer'),2,3,'{"it":"Che cosa vede un token in un decoder-only?","en":"What does a token see in a decoder-only model?"}','[{"it":"Solo i token precedenti","en":"Only the previous tokens"},{"it":"Tutta la frase","en":"The whole sentence"},{"it":"Solo il successivo","en":"Only the next one"},{"it":"Nessun token","en":"No tokens"}]',0,'{"it":"Attention mascherata.","en":"Masked attention."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'transformer'),3,3,'{"it":"Per creare embedding di frasi è ottimo un modello…","en":"For making sentence embeddings a good model is…"}','[{"it":"Encoder, come BERT","en":"Encoder, like BERT"},{"it":"Solo decoder","en":"Decoder only"},{"it":"Convoluzionale","en":"Convolutional"},{"it":"K-means","en":"K-means"}]',0,'{"it":"Vede tutto il contesto.","en":"It sees the whole context."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'finetune'),1,3,'{"it":"Che cosa insegna bene il fine-tuning?","en":"What does fine-tuning teach well?"}','[{"it":"Uno stile o un comportamento","en":"A style or a behaviour"},{"it":"I fatti di ieri","en":"Yesterday’s facts"},{"it":"Una nuova lingua di programmazione dal nulla","en":"A new programming language from scratch"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Per i fatti c’è RAG.","en":"For facts there is RAG."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'finetune'),2,3,'{"it":"Che cosa provare prima del fine-tuning?","en":"What should you try before fine-tuning?"}','[{"it":"Prompt migliori e RAG","en":"Better prompts and RAG"},{"it":"Un modello più vecchio","en":"An older model"},{"it":"Più GPU","en":"More GPUs"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Più economici e flessibili.","en":"Cheaper and more flexible."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'finetune'),3,3,'{"it":"Che cos’è RLHF?","en":"What is RLHF?"}','[{"it":"Addestramento con feedback umano","en":"Training with human feedback"},{"it":"Un formato di file","en":"A file format"},{"it":"Un tipo di GPU","en":"A type of GPU"},{"it":"Un linguaggio","en":"A language"}]',0,'{"it":"Reinforcement learning from human feedback.","en":"Reinforcement learning from human feedback."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'lora'),1,3,'{"it":"Che cosa addestra LoRA?","en":"What does LoRA train?"}','[{"it":"Piccole matrici aggiuntive","en":"Small extra matrices"},{"it":"Tutti i parametri","en":"All parameters"},{"it":"Solo il tokenizzatore","en":"Only the tokeniser"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Il modello base resta congelato.","en":"The base model stays frozen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'lora'),2,3,'{"it":"Che cosa fa la quantizzazione?","en":"What does quantisation do?"}','[{"it":"Usa meno bit per i pesi","en":"Uses fewer bits for weights"},{"it":"Aggiunge parametri","en":"Adds parameters"},{"it":"Traduce il modello","en":"Translates the model"},{"it":"Cifra i dati","en":"Encrypts data"}]',0,'{"it":"Meno memoria, poca perdita.","en":"Less memory, little loss."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'lora'),3,3,'{"it":"Che cos’è QLoRA?","en":"What is QLoRA?"}','[{"it":"LoRA su un modello quantizzato","en":"LoRA on a quantised model"},{"it":"Una GPU","en":"A GPU"},{"it":"Un dataset","en":"A dataset"},{"it":"Un tokenizzatore","en":"A tokeniser"}]',0,'{"it":"Fine-tuning su una sola GPU.","en":"Fine-tuning on a single GPU."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'why'),1,3,'{"it":"Che cosa fa la “R” di RAG?","en":"What does the “R” in RAG do?"}','[{"it":"Cerca i passaggi rilevanti","en":"Retrieves the relevant passages"},{"it":"Riaddestra il modello","en":"Retrains the model"},{"it":"Riavvia il server","en":"Restarts the server"},{"it":"Riduce il prompt","en":"Reduces the prompt"}]',0,'{"it":"Retrieval.","en":"Retrieval."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'why'),2,3,'{"it":"Qual è un vantaggio di RAG sul fine-tuning per i fatti?","en":"What is an advantage of RAG over fine-tuning for facts?"}','[{"it":"Si aggiorna cambiando i documenti","en":"It updates by changing documents"},{"it":"Non serve nessun documento","en":"No documents needed"},{"it":"Costa sempre di più","en":"It always costs more"},{"it":"Rende il modello più grande","en":"It makes the model bigger"}]',0,'{"it":"Niente riaddestramento.","en":"No retraining."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'why'),3,3,'{"it":"Quando si può fare a meno della ricerca?","en":"When can you skip retrieval?"}','[{"it":"Se i documenti stanno tutti nel contesto","en":"If all documents fit in the context"},{"it":"Mai","en":"Never"},{"it":"Se i documenti sono milioni","en":"If there are millions of documents"},{"it":"Se il modello è piccolo","en":"If the model is small"}]',0,'{"it":"La soluzione più semplice prima.","en":"Simplest solution first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'chunking'),1,3,'{"it":"Perché aggiungere sovrapposizione tra blocchi?","en":"Why add overlap between chunks?"}','[{"it":"Per non spezzare un concetto a metà","en":"To avoid cutting a concept in half"},{"it":"Per occupare più spazio","en":"To use more space"},{"it":"Per confondere la ricerca","en":"To confuse search"},{"it":"Non serve","en":"It is useless"}]',0,'{"it":"Il contesto attraversa il taglio.","en":"Context crosses the cut."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'chunking'),2,3,'{"it":"Qual è il modo migliore di dividere un manuale?","en":"What is the best way to split a manual?"}','[{"it":"Per titoli e paragrafi","en":"By headings and paragraphs"},{"it":"Ogni 10 caratteri","en":"Every 10 characters"},{"it":"A caso","en":"At random"},{"it":"Un blocco unico gigante","en":"One giant chunk"}]',0,'{"it":"Segui la struttura.","en":"Follow the structure."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'chunking'),3,3,'{"it":"A che cosa servono i metadati?","en":"What is metadata for?"}','[{"it":"Filtrare e citare le fonti","en":"Filtering and citing sources"},{"it":"Colorare il testo","en":"Colouring text"},{"it":"Aumentare i token","en":"Increasing tokens"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Documento, pagina, data.","en":"Document, page, date."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'vectors'),1,3,'{"it":"Che cosa misura `<=>` in pgvector?","en":"What does `<=>` measure in pgvector?"}','[{"it":"La distanza del coseno","en":"Cosine distance"},{"it":"L’uguaglianza esatta","en":"Exact equality"},{"it":"La lunghezza del testo","en":"Text length"},{"it":"La data","en":"The date"}]',0,'{"it":"Più piccola, più simile.","en":"Smaller, more similar."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'vectors'),2,3,'{"it":"A che cosa serve l’indice HNSW?","en":"What is the HNSW index for?"}','[{"it":"Ricerca veloce dei vettori vicini","en":"Fast nearest-vector search"},{"it":"Ordinare per data","en":"Sorting by date"},{"it":"Cifrare i dati","en":"Encrypting data"},{"it":"Comprimere il testo","en":"Compressing text"}]',0,'{"it":"Approssimata ma rapidissima.","en":"Approximate but very fast."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'vectors'),3,3,'{"it":"Che cos’è la ricerca ibrida?","en":"What is hybrid search?"}','[{"it":"Vettori più parole chiave","en":"Vectors plus keywords"},{"it":"Ricerca su due server","en":"Search on two servers"},{"it":"Ricerca a voce","en":"Voice search"},{"it":"Ricerca senza indice","en":"Search without an index"}]',0,'{"it":"Trova anche codici e nomi esatti.","en":"It also finds exact codes and names."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'prompt'),1,3,'{"it":"Che cosa deve fare il modello se la risposta non è nei documenti?","en":"What should the model do if the answer is not in the documents?"}','[{"it":"Dirlo chiaramente","en":"Say so clearly"},{"it":"Inventarla","en":"Make it up"},{"it":"Rispondere a un’altra domanda","en":"Answer another question"},{"it":"Non rispondere mai più","en":"Never answer again"}]',0,'{"it":"Meglio “non lo so” che un’invenzione.","en":"Better “I don’t know” than a fabrication."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'prompt'),2,3,'{"it":"Perché indicare la fonte di ogni blocco?","en":"Why give each chunk’s source?"}','[{"it":"Per poter citare e verificare","en":"To be able to cite and verify"},{"it":"Per allungare il prompt","en":"To lengthen the prompt"},{"it":"Per il copyright del modello","en":"For the model’s copyright"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"L’utente può controllare.","en":"The user can check."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'prompt'),3,3,'{"it":"Che cosa succede con troppi blocchi poco pertinenti?","en":"What happens with too many barely relevant chunks?"}','[{"it":"Il modello si confonde e si spende di più","en":"The model gets confused and costs rise"},{"it":"La risposta migliora sempre","en":"The answer always improves"},{"it":"Niente","en":"Nothing"},{"it":"Il database si cancella","en":"The database is deleted"}]',0,'{"it":"Qualità prima della quantità.","en":"Quality over quantity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'evaluate'),1,3,'{"it":"Quali sono i due punti di errore di RAG?","en":"What are RAG’s two failure points?"}','[{"it":"Ricerca e generazione","en":"Retrieval and generation"},{"it":"Tastiera e mouse","en":"Keyboard and mouse"},{"it":"Server e client","en":"Server and client"},{"it":"Token e byte","en":"Tokens and bytes"}]',0,'{"it":"Vanno valutati separatamente.","en":"They must be evaluated separately."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'evaluate'),2,3,'{"it":"Che cosa fa un reranker?","en":"What does a reranker do?"}','[{"it":"Riordina i risultati con un modello più preciso","en":"Reorders results with a more precise model"},{"it":"Cancella i documenti","en":"Deletes documents"},{"it":"Traduce la domanda","en":"Translates the question"},{"it":"Aumenta il numero di blocchi passati al modello","en":"Increases the number of chunks passed to the model"}]',0,'{"it":"Prima ampio, poi preciso.","en":"Broad first, then precise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'evaluate'),3,3,'{"it":"Che cosa significa risposta “fedele”?","en":"What does a “faithful” answer mean?"}','[{"it":"Basata solo sui documenti","en":"Based only on the documents"},{"it":"Molto lunga","en":"Very long"},{"it":"Scritta in rima","en":"Written in rhyme"},{"it":"Data velocemente","en":"Given quickly"}]',0,'{"it":"Niente aggiunte inventate.","en":"No invented additions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'what'),1,3,'{"it":"Chi decide i passi in un workflow?","en":"Who decides the steps in a workflow?"}','[{"it":"Il tuo codice","en":"Your code"},{"it":"Il modello","en":"The model"},{"it":"L’utente a ogni passo","en":"The user at each step"},{"it":"Nessuno","en":"Nobody"}]',0,'{"it":"Nell’agente li decide il modello.","en":"In an agent the model decides."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'what'),2,3,'{"it":"Quando ha senso un agente?","en":"When does an agent make sense?"}','[{"it":"Per compiti aperti e difficili da prevedere","en":"For open-ended, hard-to-predict tasks"},{"it":"Per tradurre una parola alla volta in modo preciso","en":"To translate one word at a time precisely"},{"it":"Sempre","en":"Always"},{"it":"Mai","en":"Never"}]',0,'{"it":"Altrimenti basta un flusso.","en":"Otherwise a workflow is enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'what'),3,3,'{"it":"Da dove conviene partire?","en":"Where should you start?"}','[{"it":"Dalla soluzione più semplice","en":"From the simplest solution"},{"it":"Dall’agente più complesso","en":"From the most complex agent"},{"it":"Da dieci agenti insieme","en":"From ten agents at once"},{"it":"Dal fine-tuning","en":"From fine-tuning"}]',0,'{"it":"Complessità solo se serve.","en":"Complexity only when needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'loop'),1,3,'{"it":"Quando finisce il ciclo?","en":"When does the loop end?"}','[{"it":"Quando il modello non chiede più strumenti","en":"When the model stops asking for tools"},{"it":"Dopo un passo, sempre","en":"After one step, always"},{"it":"Mai","en":"Never"},{"it":"Quando l’utente spegne il PC","en":"When the user turns off the PC"}]',0,'{"it":"O quando scatta il limite.","en":"Or when the limit trips."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'loop'),2,3,'{"it":"Perché serve un limite di passi?","en":"Why do you need a step limit?"}','[{"it":"Per evitare cicli infiniti e spese","en":"To avoid endless loops and spending"},{"it":"Per far contento il modello","en":"To please the model"},{"it":"Non serve","en":"It is not needed"},{"it":"Per l’estetica","en":"For looks"}]',0,'{"it":"Sicurezza prima di tutto.","en":"Safety first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'loop'),3,3,'{"it":"Come rimandi più risultati di strumenti?","en":"How do you send back several tool results?"}','[{"it":"Tutti insieme in un solo messaggio","en":"All together in one message"},{"it":"Uno per chiamata separata","en":"One per separate call"},{"it":"Non si rimandano","en":"You do not"},{"it":"Solo il primo","en":"Only the first"}]',0,'{"it":"Ognuno con il suo tool_use_id.","en":"Each with its tool_use_id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'tools'),1,3,'{"it":"Che cosa deve dire la descrizione di uno strumento?","en":"What should a tool description say?"}','[{"it":"Cosa fa, quando usarlo, cosa restituisce","en":"What it does, when to use it, what it returns"},{"it":"Chi l’ha scritto e in quale data","en":"Who wrote it and on what date"},{"it":"Il prezzo","en":"The price"},{"it":"Niente, basta il nome","en":"Nothing, the name is enough"}]',0,'{"it":"È la guida del modello.","en":"It is the model’s guide."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'tools'),2,3,'{"it":"Perché i risultati devono essere brevi?","en":"Why should results be short?"}','[{"it":"Per non riempire il contesto","en":"So they do not fill the context"},{"it":"Per risparmiare inchiostro","en":"To save ink"},{"it":"Per sembrare eleganti","en":"To look elegant"},{"it":"Non devono","en":"They need not be"}]',0,'{"it":"Il contesto è prezioso.","en":"Context is precious."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'tools'),3,3,'{"it":"Che cosa restituire in caso di errore?","en":"What should you return on error?"}','[{"it":"Un messaggio che aiuti a correggersi","en":"A message that helps self-correction"},{"it":"Niente","en":"Nothing"},{"it":"Un codice incomprensibile","en":"An incomprehensible code"},{"it":"Lo stack trace intero","en":"The whole stack trace"}]',0,'{"it":"Il modello può riprovare meglio.","en":"The model can retry better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp'),1,3,'{"it":"Che cos’è MCP?","en":"What is MCP?"}','[{"it":"Uno standard per collegare modelli a strumenti e dati","en":"A standard to connect models to tools and data"},{"it":"Un modello linguistico creato da Anthropic per gli agenti","en":"A language model built by Anthropic for agents"},{"it":"Un linguaggio di programmazione","en":"A programming language"},{"it":"Un formato di immagine","en":"An image format"}]',0,'{"it":"Model Context Protocol.","en":"Model Context Protocol."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp'),2,3,'{"it":"Che cosa espone un server MCP?","en":"What does an MCP server expose?"}','[{"it":"Strumenti, risorse e prompt","en":"Tools, resources and prompts"},{"it":"Solo immagini","en":"Only images"},{"it":"Password","en":"Passwords"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"In un formato comune.","en":"In a common format."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp'),3,3,'{"it":"Che cosa controllare prima di installare un server MCP di terzi?","en":"What should you check before installing a third-party MCP server?"}','[{"it":"Chi l’ha scritto e quali permessi ottiene","en":"Who wrote it and what permissions it gets"},{"it":"Il colore del logo","en":"The logo colour"},{"it":"Niente","en":"Nothing"},{"it":"Solo il nome e il numero di download","en":"Only the name and the download count"}]',0,'{"it":"Agisce a tuo nome.","en":"It acts on your behalf."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'safety'),1,3,'{"it":"Quali azioni richiedono conferma umana?","en":"Which actions need human confirmation?"}','[{"it":"Quelle irreversibili","en":"Irreversible ones"},{"it":"Leggere un file","en":"Reading a file"},{"it":"Fare una somma","en":"Doing a sum"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Inviare, pagare, cancellare.","en":"Sending, paying, deleting."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'safety'),2,3,'{"it":"Come va trattato un testo letto da una pagina web?","en":"How should text read from a web page be treated?"}','[{"it":"Come dato, mai come istruzione","en":"As data, never as instructions"},{"it":"Come un ordine del capo","en":"As an order from the boss"},{"it":"Va ignorato sempre","en":"Always ignored"},{"it":"Va eseguito","en":"Executed"}]',0,'{"it":"Può contenere prompt injection.","en":"It may contain prompt injection."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'safety'),3,3,'{"it":"Perché eseguire più volte la valutazione di un agente?","en":"Why run an agent’s evaluation several times?"}','[{"it":"Il comportamento varia tra un’esecuzione e l’altra","en":"Behaviour varies from run to run"},{"it":"Per spendere di più e avere più dati","en":"To spend more and get more data"},{"it":"Non serve","en":"It is not needed"},{"it":"Per stancarlo","en":"To tire it"}]',0,'{"it":"Una sola prova può ingannare.","en":"One try can mislead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'tracking'),1,3,'{"it":"Che cosa si traccia in un esperimento?","en":"What do you track in an experiment?"}','[{"it":"Parametri, metriche, versioni e modello","en":"Parameters, metrics, versions and model"},{"it":"Solo il nome del file del modello finale","en":"Only the file name of the final model"},{"it":"L’ora di pranzo","en":"Lunch time"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Tutto quello che serve a ripeterlo.","en":"Everything needed to repeat it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'tracking'),2,3,'{"it":"Che cos’è la riproducibilità?","en":"What is reproducibility?"}','[{"it":"Stessi dati e codice danno lo stesso modello","en":"Same data and code give the same model"},{"it":"Copiare un modello altrui per confrontarlo","en":"Copying someone else’s model to compare it"},{"it":"Stampare i risultati","en":"Printing results"},{"it":"Ridurre il dataset","en":"Shrinking the dataset"}]',0,'{"it":"La base della fiducia.","en":"The basis of trust."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'tracking'),3,3,'{"it":"Che cosa fa `mlflow.log_metric`?","en":"What does `mlflow.log_metric` do?"}','[{"it":"Salva una metrica dell’esperimento","en":"Saves an experiment metric"},{"it":"Addestra il modello","en":"Trains the model"},{"it":"Cancella il run","en":"Deletes the run"},{"it":"Scarica dati","en":"Downloads data"}]',0,'{"it":"Per confrontare i run.","en":"To compare runs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'serving'),1,3,'{"it":"Quando va caricato il modello?","en":"When should the model be loaded?"}','[{"it":"Una volta all’avvio","en":"Once at startup"},{"it":"A ogni richiesta","en":"On every request"},{"it":"Mai","en":"Never"},{"it":"Ogni ora","en":"Every hour"}]',0,'{"it":"Caricare è lento.","en":"Loading is slow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'serving'),2,3,'{"it":"A che cosa serve Pydantic qui?","en":"What is Pydantic for here?"}','[{"it":"Validare gli input","en":"Validating inputs"},{"it":"Addestrare","en":"Training"},{"it":"Disegnare grafici","en":"Drawing charts"},{"it":"Comprimere","en":"Compressing"}]',0,'{"it":"Tipi e campi obbligatori.","en":"Types and required fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'serving'),3,3,'{"it":"A che cosa serve Docker?","en":"What is Docker for?"}','[{"it":"Impacchettare il servizio con le sue dipendenze","en":"Packaging the service with its dependencies"},{"it":"Addestrare il modello più in fretta sulla GPU","en":"Training the model faster on the GPU"},{"it":"Scrivere i test","en":"Writing tests"},{"it":"Gestire le password","en":"Managing passwords"}]',0,'{"it":"Gira uguale ovunque.","en":"It runs the same everywhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'monitoring'),1,3,'{"it":"Che cos’è il data drift?","en":"What is data drift?"}','[{"it":"I dati in ingresso cambiano rispetto all’addestramento","en":"Input data changes compared to training"},{"it":"Un furto di dati dal server di produzione","en":"A data theft from the production server"},{"it":"Un disco pieno","en":"A full disk"},{"it":"Un errore di battitura","en":"A typo"}]',0,'{"it":"Il mondo cambia.","en":"The world changes."}',NULL);
