INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'branches'),2,1,'{"it":"Quando nasce un conflitto?","en":"When does a conflict arise?"}','[{"it":"Quando due branch cambiano le stesse righe","en":"When two branches change the same lines"},{"it":"A ogni merge, anche senza modifiche in comune","en":"On every merge, even with no shared changes"},{"it":"Quando il disco è pieno","en":"When the disk is full"},{"it":"Mai","en":"Never"}]',0,'{"it":"Git non sa quale versione scegliere.","en":"Git cannot pick a version."}',NULL);
