INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'e2e-ci'),3,3,'{"it":"Che cosa fa la CI con i test?","en":"What does CI do with tests?"}','[{"it":"Li esegue a ogni push e pull request","en":"Runs them on every push and pull request"},{"it":"Li cancella","en":"Deletes them"},{"it":"Li scrive da sola leggendo il codice","en":"Writes them by itself by reading the code"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Niente merge se rosso.","en":"No merge if red."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'principles'),1,2,'{"it":"Che cosa dice il principio DRY?","en":"What does the DRY principle say?"}','[{"it":"Non duplicare la logica","en":"Do not duplicate logic"},{"it":"Scrivi meno commenti","en":"Write fewer comments"},{"it":"Usa solo variabili globali","en":"Use only global variables"},{"it":"Non testare","en":"Do not test"}]',0,'{"it":"Don’t Repeat Yourself.","en":"Don’t Repeat Yourself."}',NULL);
