INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'principles'),3,2,'{"it":"Perché i nomi chiari sono importanti?","en":"Why do clear names matter?"}','[{"it":"Il codice si legge molte più volte di quante si scriva","en":"Code is read far more often than written"},{"it":"Occupano meno spazio nel file compilato","en":"They take less space in the compiled file"},{"it":"Il compilatore lo richiede","en":"The compiler requires it"},{"it":"Non lo sono","en":"They do not"}]',0,'{"it":"Leggibilità prima di tutto.","en":"Readability first."}',NULL);
