INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'creational'),2,2,'{"it":"Quando è utile un Builder?","en":"When is a Builder useful?"}','[{"it":"Per oggetti complessi con molte opzioni","en":"For complex objects with many options"},{"it":"Per numeri interi","en":"For integers"},{"it":"Mai","en":"Never"},{"it":"Per cancellare oggetti non più usati","en":"For deleting objects no longer used"}]',0,'{"it":"Passo dopo passo.","en":"Step by step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'creational'),3,2,'{"it":"Perché usare il Singleton con parsimonia?","en":"Why use the Singleton sparingly?"}','[{"it":"È stato globale e complica i test","en":"It is global state and complicates tests"},{"it":"È troppo veloce","en":"It is too fast"},{"it":"Non esiste in TypeScript","en":"It does not exist in TypeScript"},{"it":"Consuma troppa memoria","en":"It uses too much memory"}]',0,'{"it":"Meglio passare le dipendenze.","en":"Better to pass dependencies."}',NULL);
