INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'structural'),2,3,'{"it":"Come aggiunge comportamento un Decorator?","en":"How does a Decorator add behaviour?"}','[{"it":"Avvolgendo l’oggetto originale","en":"By wrapping the original object"},{"it":"Modificando la classe originale","en":"By modifying the original class"},{"it":"Copiando il codice","en":"By copying code"},{"it":"Non lo aggiunge","en":"It does not"}]',0,'{"it":"Stessa interfaccia, più funzioni.","en":"Same interface, more features."}',NULL);
