INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'quantifiers'),2,1,'{"it":"Perché usare `^` e `$` nella validazione?","en":"Why use `^` and `$` in validation?"}','[{"it":"Per controllare tutto il campo, non una parte","en":"To check the whole field, not a part"},{"it":"Per rendere la regex più veloce da eseguire","en":"To make the regex faster to run"},{"it":"Non servono","en":"They are not needed"},{"it":"Per i colori","en":"For colours"}]',0,'{"it":"Altrimenti “abc12345xyz” passerebbe per un CAP.","en":"Otherwise “abc12345xyz” would pass as a postcode."}',NULL);
