INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'graphql'),3,3,'{"it":"Qual è un vantaggio di GraphQL?","en":"What is an advantage of GraphQL?"}','[{"it":"Il client chiede esattamente i campi che servono","en":"The client asks for exactly the fields it needs"},{"it":"Si mette in cache più facilmente di REST","en":"It caches more easily than REST"},{"it":"Non ha bisogno di uno schema","en":"It needs no schema"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Niente dati in più.","en":"No extra data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'keys'),1,2,'{"it":"Dove tiene i dati Redis?","en":"Where does Redis keep data?"}','[{"it":"In memoria","en":"In memory"},{"it":"Solo su carta","en":"Only on paper"},{"it":"In un foglio Excel","en":"In an Excel sheet"},{"it":"Solo su disco, mai in memoria","en":"Only on disk, never in memory"}]',0,'{"it":"Per questo è velocissimo.","en":"That is why it is so fast."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'keys'),2,2,'{"it":"Che cosa fa `EX 3600` in un SET?","en":"What does `EX 3600` do in a SET?"}','[{"it":"Fa scadere la chiave dopo un’ora","en":"Expires the key after an hour"},{"it":"Esporta i dati","en":"Exports the data"},{"it":"Crea 3600 copie","en":"Creates 3600 copies"},{"it":"Cifra il valore","en":"Encrypts the value"}]',0,'{"it":"In secondi.","en":"In seconds."}',NULL);
