INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'injection'),1,2,'{"it":"Che cos’è una SQL injection?","en":"What is SQL injection?"}','[{"it":"Dati dell’utente interpretati come codice SQL","en":"User data interpreted as SQL code"},{"it":"Un database lento per troppe richieste","en":"A database slowed by too many requests"},{"it":"Un backup","en":"A backup"},{"it":"Un errore di battitura","en":"A typo"}]',0,'{"it":"Può esporre tutto il database.","en":"It can expose the whole database."}',NULL);
