INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),1,2,'{"it":"Che cosa fa un attacco XSS?","en":"What does an XSS attack do?"}','[{"it":"Esegue JavaScript dell’attaccante nel browser della vittima","en":"Runs the attacker’s JavaScript in the victim’s browser"},{"it":"Rallenta il server con richieste ripetute","en":"Slows the server with repeated requests"},{"it":"Cancella il disco","en":"Wipes the disk"},{"it":"Cambia la password del Wi-Fi","en":"Changes the Wi-Fi password"}]',0,'{"it":"Può rubare le sessioni.","en":"It can steal sessions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),2,2,'{"it":"Che cosa usare al posto di innerHTML per testo dell’utente?","en":"What to use instead of innerHTML for user text?"}','[{"it":"textContent","en":"textContent"},{"it":"outerHTML","en":"outerHTML"},{"it":"eval","en":"eval"},{"it":"document.write","en":"document.write"}]',0,'{"it":"Il testo resta testo.","en":"Text stays text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),3,2,'{"it":"Che cosa fa una Content Security Policy?","en":"What does a Content Security Policy do?"}','[{"it":"Limita da dove possono arrivare gli script","en":"Limits where scripts can come from"},{"it":"Cifra il database","en":"Encrypts the database"},{"it":"Blocca le immagini sempre","en":"Always blocks images"},{"it":"Velocizza il sito","en":"Speeds up the site"}]',0,'{"it":"Una seconda difesa.","en":"A second defence."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),1,3,'{"it":"Come si salvano le password?","en":"How should passwords be stored?"}','[{"it":"Con un hash lento e con salt come bcrypt","en":"With a slow, salted hash like bcrypt"},{"it":"In chiaro","en":"In plain text"},{"it":"Con MD5, veloce e facile da verificare","en":"With MD5, fast and easy to verify"},{"it":"In un file di testo","en":"In a text file"}]',0,'{"it":"`password_hash` in PHP.","en":"`password_hash` in PHP."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),2,3,'{"it":"Che cosa fa il flag `httponly` di un cookie?","en":"What does a cookie’s `httponly` flag do?"}','[{"it":"Impedisce a JavaScript di leggerlo","en":"Prevents JavaScript from reading it"},{"it":"Lo rende pubblico","en":"Makes it public"},{"it":"Lo cancella subito","en":"Deletes it at once"},{"it":"Lo cifra con la password","en":"Encrypts it with the password"}]',0,'{"it":"Protegge dall’XSS.","en":"It protects against XSS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),3,3,'{"it":"Nascondere un pulsante basta a proteggere una funzione?","en":"Is hiding a button enough to protect a feature?"}','[{"it":"No, serve il controllo sul server","en":"No, a server-side check is needed"},{"it":"Sì","en":"Yes"},{"it":"Solo su mobile","en":"Only on mobile"},{"it":"Sì, se lo nascondi anche con il CSS","en":"Yes, if you also hide it with CSS"}]',0,'{"it":"Le richieste si possono fare a mano.","en":"Requests can be crafted by hand."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'csrf'),1,3,'{"it":"Che cosa sfrutta un attacco CSRF?","en":"What does a CSRF attack exploit?"}','[{"it":"La sessione già aperta della vittima","en":"The victim’s already open session"},{"it":"Una password debole scelta dalla vittima","en":"A weak password chosen by the victim"},{"it":"Un server lento","en":"A slow server"},{"it":"Il Wi-Fi pubblico","en":"Public Wi-Fi"}]',0,'{"it":"Il browser invia i cookie da solo.","en":"The browser sends cookies by itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'csrf'),2,3,'{"it":"Che cosa fa l’intestazione HSTS?","en":"What does the HSTS header do?"}','[{"it":"Obbliga il browser a usare HTTPS","en":"Forces the browser to use HTTPS"},{"it":"Blocca i cookie","en":"Blocks cookies"},{"it":"Cifra il database","en":"Encrypts the database"},{"it":"Nasconde il sito","en":"Hides the site"}]',0,'{"it":"Strict-Transport-Security.","en":"Strict-Transport-Security."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'csrf'),3,3,'{"it":"Quale difesa contro il CSRF?","en":"Which defence against CSRF?"}','[{"it":"Token CSRF nei moduli e cookie SameSite","en":"CSRF tokens in forms and SameSite cookies"},{"it":"Password più lunghe e cambiate spesso","en":"Longer passwords changed often"},{"it":"Più RAM","en":"More RAM"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Il server verifica il token.","en":"The server checks the token."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'passwords'),1,1,'{"it":"Che cosa rende forte una password?","en":"What makes a password strong?"}','[{"it":"Essere lunga e unica","en":"Being long and unique"},{"it":"Contenere il tuo nome","en":"Containing your name"},{"it":"Essere corta e facile","en":"Being short and easy"},{"it":"Essere uguale ovunque","en":"Being the same everywhere"}]',0,'{"it":"Lunghezza e unicità.","en":"Length and uniqueness."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'passwords'),2,1,'{"it":"Perché non riutilizzare le password?","en":"Why not reuse passwords?"}','[{"it":"Un furto su un sito apre anche gli altri account","en":"One breach opens your other accounts too"},{"it":"Perché le password si consumano con l’uso","en":"Because passwords wear out with use"},{"it":"Non c’è motivo","en":"There is no reason"},{"it":"Perché sono a pagamento","en":"Because they cost money"}]',0,'{"it":"Effetto domino.","en":"Domino effect."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'passwords'),3,1,'{"it":"Che cosa fa un gestore di password?","en":"What does a password manager do?"}','[{"it":"Genera, conserva cifrate e compila le password","en":"Generates, stores encrypted and fills passwords"},{"it":"Pubblica le password","en":"Publishes passwords"},{"it":"Le stampa","en":"Prints them"},{"it":"Le cambia a caso ogni giorno su tutti i siti","en":"Changes them randomly every day on every site"}]',0,'{"it":"Una sola password da ricordare.","en":"One password to remember."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = '2fa'),1,1,'{"it":"Che vantaggio dà il 2FA?","en":"What does 2FA give you?"}','[{"it":"Una password rubata non basta per entrare","en":"A stolen password is not enough to get in"},{"it":"Non serve più la password","en":"The password is no longer needed"},{"it":"Internet più veloce","en":"Faster internet"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Serve una seconda prova.","en":"A second proof is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = '2fa'),2,1,'{"it":"Quale secondo fattore è il più debole?","en":"Which second factor is weakest?"}','[{"it":"SMS","en":"SMS"},{"it":"Chiave di sicurezza","en":"Security key"},{"it":"App di autenticazione","en":"Authenticator app"},{"it":"Passkey","en":"Passkey"}]',0,'{"it":"Attaccabile con lo scambio di SIM.","en":"Vulnerable to SIM swapping."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = '2fa'),3,1,'{"it":"Qualcuno al telefono ti chiede il codice di verifica appena ricevuto. Che fai?","en":"Someone on the phone asks for the verification code you just got. What do you do?"}','[{"it":"Non lo do e riattacco","en":"Do not give it and hang up"},{"it":"Glielo leggo","en":"Read it out"},{"it":"Glielo mando per SMS","en":"Text it to them"},{"it":"Lo pubblico","en":"Post it"}]',0,'{"it":"È sempre una truffa.","en":"It is always a scam."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'phishing'),1,2,'{"it":"Qual è un segnale tipico di phishing?","en":"What is a typical phishing sign?"}','[{"it":"Urgenza e richiesta di dati","en":"Urgency and a request for data"},{"it":"Un messaggio di un amico che conosci, senza richieste","en":"A message from a friend with no requests"},{"it":"Una newsletter a cui sei iscritto","en":"A newsletter you subscribed to"},{"it":"Una fattura attesa dal portale ufficiale","en":"An expected invoice from the official portal"}]',0,'{"it":"Fretta = attenzione.","en":"Hurry = caution."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'phishing'),2,2,'{"it":"Ricevi un SMS dalla “banca” con un link. Che fai?","en":"You get an SMS from the “bank” with a link. What do you do?"}','[{"it":"Apro io l’app ufficiale senza usare il link","en":"Open the official app myself without the link"},{"it":"Clicco subito","en":"Click at once"},{"it":"Rispondo chiedendo se il messaggio è vero","en":"Reply asking whether the message is genuine"},{"it":"Inoltro a tutti","en":"Forward to everyone"}]',0,'{"it":"Mai i link del messaggio.","en":"Never the message’s links."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'phishing'),3,2,'{"it":"Che cosa fare se hai inserito la password su un sito falso?","en":"What to do if you entered your password on a fake site?"}','[{"it":"Cambiarla subito e attivare il 2FA","en":"Change it at once and enable 2FA"},{"it":"Niente","en":"Nothing"},{"it":"Aspettare un mese","en":"Wait a month"},{"it":"Cancellare il browser","en":"Delete the browser"}]',0,'{"it":"Prima si agisce, meglio è.","en":"The sooner the better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'devices'),1,2,'{"it":"Perché installare gli aggiornamenti?","en":"Why install updates?"}','[{"it":"Chiudono falle di sicurezza note","en":"They close known security holes"},{"it":"Per cambiare i colori","en":"To change colours"},{"it":"Rallentano il dispositivo","en":"They slow the device"},{"it":"Non servono","en":"They are not needed"}]',0,'{"it":"Meglio automatici.","en":"Better automatic."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'devices'),2,2,'{"it":"Che cosa dice la regola 3-2-1 dei backup?","en":"What does the 3-2-1 backup rule say?"}','[{"it":"Tre copie, due supporti, una fuori casa","en":"Three copies, two media, one off-site"},{"it":"Tre password, due email, un telefono","en":"Three passwords, two emails, one phone"},{"it":"Un backup ogni tre anni","en":"One backup every three years"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Contro guasti e ransomware.","en":"Against failures and ransomware."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'devices'),3,2,'{"it":"Che cos’è il ransomware?","en":"What is ransomware?"}','[{"it":"Malware che cifra i file e chiede un riscatto","en":"Malware that encrypts files and demands ransom"},{"it":"Un antivirus che blocca i file sospetti","en":"An antivirus that blocks suspicious files"},{"it":"Un tipo di backup","en":"A kind of backup"},{"it":"Una rete Wi-Fi","en":"A Wi-Fi network"}]',0,'{"it":"Il backup è la difesa migliore.","en":"Backup is the best defence."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'why'),1,1,'{"it":"Che cos’è uno screen reader?","en":"What is a screen reader?"}','[{"it":"Un software che legge ad alta voce la pagina","en":"Software reading the page aloud"},{"it":"Un monitor speciale","en":"A special monitor"},{"it":"Un’estensione per i colori","en":"A colour extension"},{"it":"Un browser per bambini","en":"A browser for children"}]',0,'{"it":"Usato da chi non vede.","en":"Used by blind people."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'why'),2,1,'{"it":"Quali sono i quattro principi WCAG?","en":"What are the four WCAG principles?"}','[{"it":"Percepibile, utilizzabile, comprensibile, robusto","en":"Perceivable, operable, understandable, robust"},{"it":"Veloce, bello, economico, nuovo","en":"Fast, pretty, cheap, new"},{"it":"Rosso, verde, blu, nero","en":"Red, green, blue, black"},{"it":"Nessuno","en":"None"}]',0,'{"it":"POUR in inglese.","en":"POUR in English."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'why'),3,1,'{"it":"Quale legge europea rende obbligatoria l’accessibilità per molti servizi digitali?","en":"Which European law makes accessibility mandatory for many digital services?"}','[{"it":"European Accessibility Act","en":"European Accessibility Act"},{"it":"GDPR","en":"GDPR"},{"it":"AI Act","en":"AI Act"},{"it":"Digital Markets Act","en":"Digital Markets Act"}]',0,'{"it":"Applicata dal giugno 2025.","en":"Applied since June 2025."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'semantic'),1,1,'{"it":"Perché usare `<button>` invece di un `<div>` cliccabile?","en":"Why use `<button>` instead of a clickable `<div>`?"}','[{"it":"È accessibile da tastiera e annunciato come pulsante","en":"It is keyboard-accessible and announced as a button"},{"it":"È più colorato","en":"It is more colourful"},{"it":"Non c’è differenza","en":"There is no difference"},{"it":"Il div è più veloce da disegnare per il browser","en":"The div is faster for the browser to draw"}]',0,'{"it":"Semantica gratis.","en":"Free semantics."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'semantic'),2,1,'{"it":"Che alt dare a un’immagine solo decorativa?","en":"What alt should a purely decorative image get?"}','[{"it":"alt vuoto: alt=\\"\\"","en":"Empty alt: alt=\\"\\""},{"it":"alt=\\"immagine\\"","en":"alt=\\"image\\""},{"it":"Nessun attributo","en":"No attribute"},{"it":"Il nome del file","en":"The file name"}]',0,'{"it":"Lo screen reader la salta.","en":"The screen reader skips it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'semantic'),3,1,'{"it":"Qual è un buon testo per un link?","en":"What is good link text?"}','[{"it":"Scarica il listino prezzi 2026 (PDF)","en":"Download the 2026 price list (PDF)"},{"it":"Clicca qui per il documento","en":"Click here for the document"},{"it":"Link","en":"Link"},{"it":"Qui","en":"Here"}]',0,'{"it":"Chiaro anche fuori contesto.","en":"Clear even out of context."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),1,2,'{"it":"Quale tasto sposta il focus all’elemento successivo?","en":"Which key moves focus to the next element?"}','[{"it":"Tab","en":"Tab"},{"it":"Esc","en":"Esc"},{"it":"F5","en":"F5"},{"it":"Ctrl","en":"Ctrl"}]',0,'{"it":"Maiusc+Tab torna indietro.","en":"Shift+Tab goes back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),2,2,'{"it":"Qual è il contrasto minimo AA per il testo normale?","en":"What is the minimum AA contrast for normal text?"}','[{"it":"4,5:1","en":"4,5:1"},{"it":"1:1","en":"1:1"},{"it":"2:1","en":"2:1"},{"it":"10:1","en":"10:1"}]',0,'{"it":"3:1 per il testo grande.","en":"3:1 for large text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),3,2,'{"it":"Perché non usare solo il colore per segnalare un errore?","en":"Why not use colour alone to signal an error?"}','[{"it":"Chi non distingue i colori non lo vede","en":"People with colour blindness miss it"},{"it":"Il rosso è vietato dalle linee guida","en":"Red is forbidden by the guidelines"},{"it":"Costa di più","en":"It costs more"},{"it":"Non c’è motivo","en":"There is no reason"}]',0,'{"it":"Aggiungi testo o icona.","en":"Add text or an icon."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),1,2,'{"it":"Perché il placeholder non basta come etichetta?","en":"Why is a placeholder not enough as a label?"}','[{"it":"Sparisce mentre scrivi e non sempre viene letto","en":"It vanishes while typing and is not always read"},{"it":"È troppo lungo per i campi piccoli","en":"It is too long for small fields"},{"it":"È vietato","en":"It is forbidden"},{"it":"Basta sempre","en":"It is always enough"}]',0,'{"it":"Serve un label collegato.","en":"A linked label is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),2,2,'{"it":"Qual è la prima regola di ARIA?","en":"What is the first rule of ARIA?"}','[{"it":"Usa un elemento HTML adatto se esiste","en":"Use a suitable HTML element if one exists"},{"it":"Metti ARIA ovunque","en":"Put ARIA everywhere"},{"it":"Non usare mai HTML","en":"Never use HTML"},{"it":"ARIA sostituisce il CSS","en":"ARIA replaces CSS"}]',0,'{"it":"HTML prima di ARIA.","en":"HTML before ARIA."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),3,2,'{"it":"Gli strumenti automatici trovano tutti i problemi di accessibilità?","en":"Do automated tools find every accessibility problem?"}','[{"it":"No, solo una parte","en":"No, only some"},{"it":"Sì, tutti","en":"Yes, all"},{"it":"Solo quelli di colore","en":"Only colour ones"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Servono anche prove manuali.","en":"Manual tests are needed too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'formulas'),1,1,'{"it":"Con che carattere inizia una formula?","en":"What character does a formula start with?"}','[{"it":"=","en":"="},{"it":"+","en":"+"},{"it":"#","en":"#"},{"it":"$","en":"$"}]',0,'{"it":"Sempre.","en":"Always."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'formulas'),2,1,'{"it":"Che cosa fa il dollaro in `$F$1`?","en":"What does the dollar in `$F$1` do?"}','[{"it":"Rende fisso il riferimento quando copi","en":"Keeps the reference fixed when copying"},{"it":"Indica che la cella contiene una valuta","en":"Shows the cell holds a currency"},{"it":"Cancella la cella","en":"Clears the cell"},{"it":"Somma la colonna","en":"Sums the column"}]',0,'{"it":"Riferimento assoluto.","en":"Absolute reference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'formulas'),3,1,'{"it":"Come si separano gli argomenti nell’Excel italiano?","en":"How are arguments separated in Italian Excel?"}','[{"it":"Con il punto e virgola","en":"With semicolons"},{"it":"Con la virgola sempre","en":"Always with commas"},{"it":"Con gli spazi","en":"With spaces"},{"it":"Con i trattini","en":"With dashes"}]',0,'{"it":"=SOMMA(A1;A2)","en":"=SOMMA(A1;A2)"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'functions'),1,1,'{"it":"Che cosa fa `SE` / `IF`?","en":"What does `IF` / `SE` do?"}','[{"it":"Restituisce un valore o un altro secondo una condizione","en":"Returns one value or another based on a condition"},{"it":"Somma una colonna solo se non è vuota","en":"Sums a column only if it is not empty"},{"it":"Ordina i dati","en":"Sorts data"},{"it":"Crea un grafico","en":"Creates a chart"}]',0,'{"it":"Condizione, se vero, se falso.","en":"Condition, if true, if false."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'functions'),2,1,'{"it":"Quale funzione somma solo le righe che rispettano dei criteri?","en":"Which function sums only rows meeting criteria?"}','[{"it":"SUMIFS / SOMMA.PIÙ.SE","en":"SUMIFS / SOMMA.PIÙ.SE"},{"it":"SUM / SOMMA","en":"SUM / SOMMA"},{"it":"COUNT / CONTA.NUMERI","en":"COUNT / CONTA.NUMERI"},{"it":"MAX","en":"MAX"}]',0,'{"it":"Più criteri insieme.","en":"Several criteria at once."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'functions'),3,1,'{"it":"Che cosa indica l’errore `#NAME?`?","en":"What does the `#NAME?` error mean?"}','[{"it":"Nome di funzione non riconosciuto","en":"Function name not recognised"},{"it":"Divisione per zero","en":"Division by zero"},{"it":"Valore non trovato","en":"Value not found"},{"it":"Foglio pieno","en":"Sheet full"}]',0,'{"it":"Spesso inglese nell’Excel italiano.","en":"Often English names in Italian Excel."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'lookup'),1,2,'{"it":"Che cosa fa CERCA.X / XLOOKUP?","en":"What does XLOOKUP / CERCA.X do?"}','[{"it":"Cerca un valore e restituisce il corrispondente di un’altra colonna","en":"Looks up a value and returns the matching one from another column"},{"it":"Ordina i dati di una colonna dal più piccolo al più grande","en":"Sorts a column from smallest to largest"},{"it":"Cancella i doppioni","en":"Removes duplicates"},{"it":"Crea una tabella pivot","en":"Creates a pivot table"}]',0,'{"it":"Come una piccola query.","en":"Like a small query."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'lookup'),2,2,'{"it":"Perché preferirlo a CERCA.VERT?","en":"Why prefer it to VLOOKUP?"}','[{"it":"Non si rompe inserendo colonne e cerca in ogni direzione","en":"It does not break on inserted columns and searches any direction"},{"it":"È più vecchio e quindi più compatibile con tutti i file","en":"It is older, so more compatible with every file"},{"it":"Non c’è differenza","en":"There is no difference"},{"it":"Funziona solo su Mac","en":"It only works on Mac"}]',0,'{"it":"Più robusto.","en":"More robust."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'lookup'),3,2,'{"it":"A che cosa serve il quarto argomento?","en":"What is the fourth argument for?"}','[{"it":"Il valore da mostrare se non trova niente","en":"The value shown if nothing is found"},{"it":"Il colore della cella quando trova il valore","en":"The cell colour when the value is found"},{"it":"Il numero di righe","en":"The number of rows"},{"it":"Il nome del foglio","en":"The sheet name"}]',0,'{"it":"Niente #N/A.","en":"No #N/A."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'pivot'),1,2,'{"it":"Che cosa fa una tabella pivot?","en":"What does a pivot table do?"}','[{"it":"Riassume i dati per categorie","en":"Summarises data by categories"},{"it":"Disegna immagini","en":"Draws images"},{"it":"Cancella righe","en":"Deletes rows"},{"it":"Invia email","en":"Sends email"}]',0,'{"it":"Righe, colonne, valori.","en":"Rows, columns, values."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'pivot'),2,2,'{"it":"Quale grafico per l’andamento nel tempo?","en":"Which chart for trends over time?"}','[{"it":"A linee","en":"Line"},{"it":"A torta","en":"Pie"},{"it":"A dispersione 3D","en":"3D scatter"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Le barre confrontano categorie.","en":"Bars compare categories."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'pivot'),3,2,'{"it":"Che cosa evitare nei dati da analizzare?","en":"What should you avoid in data to analyse?"}','[{"it":"Le celle unite","en":"Merged cells"},{"it":"Le intestazioni","en":"Headers"},{"it":"Una riga per record","en":"One row per record"},{"it":"I numeri","en":"Numbers"}]',0,'{"it":"Rompono filtri e pivot.","en":"They break filters and pivots."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'query'),1,1,'{"it":"A che cosa serve Power Query?","en":"What is Power Query for?"}','[{"it":"Pulire e trasformare i dati prima dell’analisi","en":"Cleaning and transforming data before analysis"},{"it":"Disegnare loghi","en":"Drawing logos"},{"it":"Inviare email","en":"Sending email"},{"it":"Scrivere documenti partendo dai dati","en":"Writing documents from data"}]',0,'{"it":"L’editor delle trasformazioni.","en":"The transformation editor."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'query'),2,1,'{"it":"Che cosa succede ai passaggi di Power Query quando aggiorni i dati?","en":"What happens to Power Query steps when you refresh data?"}','[{"it":"Vengono ripetuti automaticamente","en":"They are repeated automatically"},{"it":"Si perdono","en":"They are lost"},{"it":"Vanno rifatti a mano","en":"They must be redone by hand"},{"it":"Si cancellano i dati","en":"Data is deleted"}]',0,'{"it":"Tutto registrato.","en":"All recorded."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'query'),3,1,'{"it":"Dove si crea un report di solito?","en":"Where is a report usually built?"}','[{"it":"Power BI Desktop","en":"Power BI Desktop"},{"it":"Paint","en":"Paint"},{"it":"Outlook","en":"Outlook"},{"it":"Il blocco note","en":"Notepad"}]',0,'{"it":"Poi si pubblica online.","en":"Then published online."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),1,1,'{"it":"Che cosa c’è al centro di uno schema a stella?","en":"What sits at the centre of a star schema?"}','[{"it":"La tabella dei fatti","en":"The fact table"},{"it":"La tabella dei colori","en":"The colour table"},{"it":"Un grafico","en":"A chart"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le dimensioni intorno.","en":"Dimensions around it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),2,1,'{"it":"Che tipo di relazione collega Prodotti e Vendite?","en":"What relationship type links Products and Sales?"}','[{"it":"Uno-a-molti","en":"One-to-many"},{"it":"Molti-a-molti sempre","en":"Always many-to-many"},{"it":"Nessuna","en":"None"},{"it":"Uno-a-uno sempre","en":"Always one-to-one"}]',0,'{"it":"Un prodotto, tante vendite.","en":"One product, many sales."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),3,1,'{"it":"Perché serve una tabella Calendario?","en":"Why is a Calendar table needed?"}','[{"it":"Per analizzare l’andamento nel tempo","en":"To analyse trends over time"},{"it":"Per le ferie","en":"For holidays"},{"it":"Per i compleanni","en":"For birthdays"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Anno, mese, trimestre…","en":"Year, month, quarter…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),1,2,'{"it":"Che cosa fa CALCULATE?","en":"What does CALCULATE do?"}','[{"it":"Calcola una misura cambiando i filtri","en":"Computes a measure while changing filters"},{"it":"Somma due numeri scritti nella formula","en":"Adds two numbers written in the formula"},{"it":"Crea una tabella","en":"Creates a table"},{"it":"Ordina i dati","en":"Sorts data"}]',0,'{"it":"Il cuore di DAX.","en":"The heart of DAX."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),2,2,'{"it":"Perché usare DIVIDE invece di /?","en":"Why use DIVIDE instead of /?"}','[{"it":"Gestisce la divisione per zero","en":"It handles division by zero"},{"it":"È più veloce sempre","en":"It is always faster"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Non c’è motivo","en":"There is no reason"}]',0,'{"it":"Niente errori nei visual.","en":"No errors in visuals."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),3,2,'{"it":"Le funzioni DAX hanno nomi italiani nella versione italiana?","en":"Do DAX functions have Italian names in the Italian version?"}','[{"it":"No, restano in inglese","en":"No, they stay in English"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo SUM","en":"Only SUM"},{"it":"Dipende dal giorno","en":"It depends on the day"}]',0,'{"it":"A differenza di Excel.","en":"Unlike Excel."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),1,2,'{"it":"Che cos’è uno slicer?","en":"What is a slicer?"}','[{"it":"Un filtro visivo che l’utente usa nel report","en":"A visual filter the user uses in the report"},{"it":"Un tipo di grafico a torta tagliato","en":"A kind of sliced pie chart"},{"it":"Un errore","en":"An error"},{"it":"Un file","en":"A file"}]',0,'{"it":"Per esplorare i dati.","en":"To explore data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),2,2,'{"it":"Che cosa fa la sicurezza a livello di riga?","en":"What does row-level security do?"}','[{"it":"Mostra a ciascuno solo i propri dati","en":"Shows each person only their own data"},{"it":"Cifra il computer di chi apre il report","en":"Encrypts the computer of whoever opens the report"},{"it":"Cancella le righe","en":"Deletes rows"},{"it":"Blocca il report","en":"Locks the report"}]',0,'{"it":"Per regione, reparto…","en":"By region, department…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),3,2,'{"it":"Che cosa mettere in alto in un report?","en":"What goes at the top of a report?"}','[{"it":"I numeri chiave","en":"The key numbers"},{"it":"I dettagli di ogni riga","en":"Every row’s details"},{"it":"Il logo enorme","en":"A huge logo"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Poi andamenti e dettagli.","en":"Then trends and details."}',NULL);
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["<!doctype html>","<html lang=\\"it\\">","<head>","  <title>Fucina</title>","</head>","<body>","  <h1>Ciao!</h1>","</body>","</html>"],"why":{"it":"Prima il doctype, poi `html` con dentro `head` e `body`.","en":"First the doctype, then `html` holding `head` and `body`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<title>` si scrive dentro `<head>`","en":"`<title>` goes inside `<head>`"},true],[{"it":"Quello che si vede nella pagina sta in `<body>`","en":"What you see on the page lives in `<body>`"},true],[{"it":"Una pagina può avere due `<body>`","en":"A page can have two `<body>` elements"},false],[{"it":"`<!doctype html>` è l’ultima riga del file","en":"`<!doctype html>` is the last line of the file"},false],[{"it":"I tag di solito si aprono e si chiudono","en":"Tags usually open and close"},true]],"why":{"it":"`head` descrive la pagina, `body` la mostra.","en":"`head` describes the page, `body` shows it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<html>","  <body>","    <h1>Benvenuto</h2>","  </body>","</html>"],"bug":2,"fix":"    <h1>Benvenuto</h1>","why":{"it":"Un tag si chiude con lo stesso nome con cui si apre.","en":"A tag closes with the same name it opens with."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["<h1>",{"it":"Titolo principale","en":"Main heading"}],["<p>",{"it":"Paragrafo","en":"Paragraph"}],["<strong>",{"it":"Testo importante","en":"Important text"}],["<em>",{"it":"Testo enfatizzato","en":"Emphasised text"}],["<br>",{"it":"A capo","en":"Line break"}]],"why":{"it":"Ogni tag dice che cosa è il testo, non solo come appare.","en":"Every tag says what the text is, not just how it looks."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<___>Le novità</h2>\\n<p>Oggi è <___>importante</strong>.</p>","gaps":["h2","strong"],"extra":["p","b","h1"],"why":{"it":"Il nome di apertura deve coincidere con quello di chiusura.","en":"The opening name must match the closing one."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<h1>` è il titolo più importante","en":"`<h1>` is the most important heading"},true],[{"it":"`<h6>` è più grande di `<h1>`","en":"`<h6>` is bigger than `<h1>`"},false],[{"it":"`<br>` non ha un tag di chiusura","en":"`<br>` has no closing tag"},true],[{"it":"I titoli si scelgono in base alla grandezza che piace","en":"Headings are chosen by the size you like"},false],[{"it":"`<p>` crea un paragrafo","en":"`<p>` creates a paragraph"},true]],"why":{"it":"I titoli seguono la struttura del testo: la grandezza si cambia con il CSS.","en":"Headings follow the structure of the text: size is changed with CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<a ___=\\"https://example.com\\">Scopri</a>\\n<img ___=\\"logo.png\\" ___=\\"Il logo\\">","gaps":["href","src","alt"],"extra":["link","title","url"],"why":{"it":"`href` è la destinazione, `src` il file, `alt` la descrizione.","en":"`href` is the destination, `src` the file, `alt` the description."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<p>Guarda la foto:</p>","<img href=\\"gatto.jpg\\" alt=\\"Un gatto\\">","<a href=\\"info.html\\">Altre info</a>"],"bug":1,"fix":"<img src=\\"gatto.jpg\\" alt=\\"Un gatto\\">","why":{"it":"Le immagini usano `src`, i link usano `href`.","en":"Images use `src`, links use `href`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["href",{"it":"Dove porta il link","en":"Where the link goes"}],["src",{"it":"Il file da mostrare","en":"The file to show"}],["alt",{"it":"La descrizione dell’immagine","en":"The description of the image"}],["target=\\"_blank\\"",{"it":"Apre in una nuova scheda","en":"Opens in a new tab"}]],"why":{"it":"Gli attributi aggiungono informazioni a un tag.","en":"Attributes add information to a tag."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),1,'order','{"prompt":{"it":"Costruisci una lista numerata.","en":"Build a numbered list."},"lines":["<ol>","  <li>Accendi la forgia</li>","  <li>Scalda il ferro</li>","  <li>Batti il martello</li>","</ol>"],"why":{"it":"`ol` avvolge gli elementi `li` e li numera da solo.","en":"`ol` wraps the `li` items and numbers them by itself."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<ul>` è una lista puntata","en":"`<ul>` is a bullet list"},true],[{"it":"`<ol>` è una lista numerata","en":"`<ol>` is a numbered list"},true],[{"it":"`<li>` può stare fuori da una lista","en":"`<li>` can stay outside a list"},false],[{"it":"I numeri di `<ol>` vanno scritti a mano","en":"The numbers of `<ol>` must be typed by hand"},false],[{"it":"Una lista può contenerne un’altra","en":"A list can contain another one"},true]],"why":{"it":"Il browser numera `ol`, tu scrivi solo gli `li`.","en":"The browser numbers `ol`, you only write the `li` items."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<ul>","  <li>Pane</li>","  <p>Latte</p>","  <li>Uova</li>","</ul>"],"bug":2,"fix":"  <li>Latte</li>","why":{"it":"Dentro `ul` e `ol` ci vanno solo elementi `li`.","en":"Only `li` items go directly inside `ul` and `ol`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),1,'order','{"prompt":{"it":"Costruisci la tabella.","en":"Build the table."},"lines":["<table>","  <tr>","    <th>Nome</th>","    <th>Punti</th>","  </tr>","  <tr>","    <td>Sav</td>","    <td>42</td>","  </tr>","</table>"],"why":{"it":"Una riga `tr` contiene le celle: `th` per le intestazioni, `td` per i dati.","en":"A `tr` row holds the cells: `th` for headers, `td` for data."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["<table>",{"it":"Tutta la tabella","en":"The whole table"}],["<tr>",{"it":"Una riga","en":"A row"}],["<th>",{"it":"Cella di intestazione","en":"Header cell"}],["<td>",{"it":"Cella di dati","en":"Data cell"}]],"why":{"it":"Righe dentro la tabella, celle dentro le righe.","en":"Rows inside the table, cells inside the rows."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<tr>\\n  <td ___=\\"2\\">Totale</td>\\n  <td>10</td>\\n</___>","gaps":["colspan","tr"],"extra":["rowspan","td","span"],"why":{"it":"`colspan` allarga una cella su più colonne.","en":"`colspan` stretches a cell over several columns."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<label ___=\\"mail\\">Email</label>\\n<input ___=\\"mail\\" type=\\"___\\" required>","gaps":["for","id","email"],"extra":["name","text","href"],"why":{"it":"`for` della label deve coincidere con `id` del campo.","en":"The `for` of the label must match the `id` of the field."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["type=\\"email\\"",{"it":"Un indirizzo email","en":"An email address"}],["type=\\"password\\"",{"it":"Testo nascosto","en":"Hidden text"}],["type=\\"checkbox\\"",{"it":"Una casella da spuntare","en":"A box to tick"}],["required",{"it":"Campo obbligatorio","en":"Mandatory field"}],["placeholder",{"it":"Testo di esempio","en":"Sample text"}]],"why":{"it":"Il tipo giusto dà al browser controlli e tastiere adatte.","en":"The right type gives the browser fitting checks and keyboards."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<form>","  <label for=\\"nome\\">Nome</label>","  <input id=\\"cognome\\" type=\\"text\\">","  <button>Invia</button>","</form>"],"bug":2,"fix":"  <input id=\\"nome\\" type=\\"text\\">","why":{"it":"La label punta al campo con lo stesso `id`.","en":"The label points to the field with the same `id`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),1,'order','{"prompt":{"it":"Metti in ordine la struttura della pagina.","en":"Put the page structure in order."},"lines":["<header>Logo</header>","<nav>Menu</nav>","<main>","  <article>Il mio post</article>","</main>","<footer>Contatti</footer>"],"why":{"it":"Dall’alto in basso: testata, menu, contenuto, piè di pagina.","en":"From top to bottom: header, menu, content, footer."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["<header>",{"it":"La testata","en":"The page header"}],["<nav>",{"it":"I link di navigazione","en":"The navigation links"}],["<main>",{"it":"Il contenuto principale","en":"The main content"}],["<article>",{"it":"Un contenuto autonomo","en":"A self-contained piece"}],["<aside>",{"it":"Un contenuto laterale","en":"Side content"}],["<footer>",{"it":"Il piè di pagina","en":"The page footer"}]],"why":{"it":"I tag semantici spiegano la pagina anche a chi non la vede.","en":"Semantic tags explain the page even to those who cannot see it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Ci dovrebbe essere un solo `<main>` visibile","en":"There should be just one visible `<main>`"},true],[{"it":"`<div>` ha un significato preciso","en":"`<div>` has a precise meaning"},false],[{"it":"`<section>` raggruppa contenuti su un tema","en":"`<section>` groups content on a topic"},true],[{"it":"I tag semantici aiutano i lettori di schermo","en":"Semantic tags help screen readers"},true],[{"it":"`<nav>` serve per le immagini","en":"`<nav>` is for images"},false]],"why":{"it":"`div` è un contenitore neutro: usalo solo se non esiste un tag migliore.","en":"`div` is a neutral container: use it only when no better tag exists."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<fieldset>\\n  <___>Piano</legend>\\n  <input type=\\"___\\" name=\\"piano\\">\\n  <input type=\\"radio\\" ___=\\"piano\\">\\n</fieldset>","gaps":["legend","radio","name"],"extra":["label","checkbox","id"],"why":{"it":"I radio con lo stesso `name` formano un gruppo: se ne sceglie uno solo.","en":"Radios with the same `name` form a group: only one can be picked."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["min / max",{"it":"Limiti di un numero","en":"Limits of a number"}],["pattern",{"it":"Regola con un’espressione regolare","en":"Rule with a regular expression"}],["<select>",{"it":"Menu a tendina","en":"Drop-down menu"}],["<textarea>",{"it":"Testo su più righe","en":"Multi-line text"}],["<datalist>",{"it":"Suggerimenti per un campo","en":"Suggestions for a field"}]],"why":{"it":"Il browser sa validare molti campi senza una riga di JavaScript.","en":"The browser can validate many fields without a line of JavaScript."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Le checkbox permettono più scelte","en":"Checkboxes allow several choices"},true],[{"it":"Due radio con `name` diversi si escludono","en":"Two radios with different `name` exclude each other"},false],[{"it":"`required` blocca l’invio se il campo è vuoto","en":"`required` blocks sending when the field is empty"},true],[{"it":"La validazione del browser basta da sola sul server","en":"Browser validation alone is enough for the server"},false],[{"it":"`<fieldset>` raggruppa campi correlati","en":"`<fieldset>` groups related fields"},true]],"why":{"it":"Il browser aiuta chi compila, ma il server deve sempre ricontrollare.","en":"The browser helps people filling in, but the server must always check again."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<video src=\\"film.mp4\\" ___></video>\\n<img src=\\"foto.jpg\\" alt=\\"Mare\\" loading=\\"___\\">","gaps":["controls","lazy"],"extra":["play","slow","autoload"],"why":{"it":"`controls` mostra i pulsanti, `loading=\\"lazy\\"` rimanda il caricamento.","en":"`controls` shows the buttons, `loading=\\"lazy\\"` delays the loading."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),2,'order','{"prompt":{"it":"Costruisci l’immagine responsive.","en":"Build the responsive image."},"lines":["<picture>","  <source media=\\"(min-width: 800px)\\" srcset=\\"grande.jpg\\">","  <img src=\\"piccola.jpg\\" alt=\\"Paesaggio\\">","</picture>"],"why":{"it":"Il browser sceglie la prima `source` adatta; `img` è la riserva e va per ultima.","en":"The browser picks the first fitting `source`; `img` is the fallback and comes last."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`srcset` offre più versioni di un’immagine","en":"`srcset` offers several versions of an image"},true],[{"it":"`<audio>` può avere dei `controls`","en":"`<audio>` can have `controls`"},true],[{"it":"`alt` serve solo se l’immagine è grande","en":"`alt` is only needed for large images"},false],[{"it":"`loading=\\"lazy\\"` rende la pagina più pesante","en":"`loading=\\"lazy\\"` makes the page heavier"},false],[{"it":"`<figcaption>` è la didascalia di `<figure>`","en":"`<figcaption>` is the caption of `<figure>`"},true]],"why":{"it":"Immagini giuste e caricate al momento giusto rendono la pagina veloce.","en":"The right images, loaded at the right moment, make a page fast."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<h1>Il negozio</h1>","<img src=\\"scarpe.jpg\\">","<button>Compra</button>"],"bug":1,"fix":"<img src=\\"scarpe.jpg\\" alt=\\"Scarpe rosse\\">","why":{"it":"Senza `alt`, chi usa un lettore di schermo non sa che cosa c’è nell’immagine.","en":"Without `alt`, screen reader users cannot know what the image shows."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<button ___=\\"Chiudi\\">✕</button>\\n<nav aria-___=\\"Menu principale\\">…</nav>","gaps":["aria-label","label"],"extra":["title","name","alt"],"why":{"it":"`aria-label` dà un nome a ciò che non ha testo visibile.","en":"`aria-label` names what has no visible text."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un `<button>` si usa anche da tastiera","en":"A `<button>` also works from the keyboard"},true],[{"it":"Un `<div>` cliccabile è accessibile come un bottone","en":"A clickable `<div>` is as accessible as a button"},false],[{"it":"Il testo deve avere abbastanza contrasto","en":"Text must have enough contrast"},true],[{"it":"Va bene saltare da `<h1>` a `<h4>`","en":"It is fine to jump from `<h1>` to `<h4>`"},false],[{"it":"Il colore non deve essere l’unico segnale","en":"Colour must not be the only signal"},true]],"why":{"it":"Prima i tag nativi: ARIA serve solo dove l’HTML non basta.","en":"Native tags first: ARIA is only for where HTML is not enough."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),1,'order','{"prompt":{"it":"Ordina la testata del documento.","en":"Order the head of the document."},"lines":["<head>","  <meta charset=\\"utf-8\\">","  <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">","  <title>Fucina</title>","</head>"],"why":{"it":"`charset` va per primo: il browser deve sapere subito come leggere il testo.","en":"`charset` comes first: the browser must know at once how to read the text."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["charset",{"it":"La codifica del testo","en":"The text encoding"}],["viewport",{"it":"L’adattamento ai telefoni","en":"Fitting mobile screens"}],["description",{"it":"Il riassunto per i motori di ricerca","en":"The summary for search engines"}],["<details>",{"it":"Contenuto che si apre e si chiude","en":"Content that opens and closes"}],["<dialog>",{"it":"Una finestra di dialogo","en":"A dialog window"}]],"why":{"it":"I metadati parlano al browser, non al lettore.","en":"Metadata speaks to the browser, not to the reader."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<___>\\n  <summary>Spoiler</___>\\n  <p>Vince la forgia.</p>\\n</details>","gaps":["details","summary"],"extra":["dialog","title"],"why":{"it":"`details` si apre da solo quando tocchi il suo `summary`: niente JavaScript.","en":"`details` opens by itself when you tap its `summary`: no JavaScript."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["p",{"it":"Tutti i paragrafi","en":"All paragraphs"}],[".nota",{"it":"La classe nota","en":"The class nota"}],["#box",{"it":"L’id box","en":"The id box"}],["nav a",{"it":"I link dentro nav","en":"Links inside nav"}],["a:hover",{"it":"Il link sotto al mouse","en":"The link under the mouse"}]],"why":{"it":"Punto per le classi, cancelletto per gli id, spazio per «dentro».","en":"A dot for classes, a hash for ids, a space for “inside”."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___nota { color: red; }\\n___box { width: 200px; }\\nnav ___ { color: navy; }","gaps":[".","#","a"],"extra":["*","@",":"],"why":{"it":"`.` sceglie una classe, `#` un id.","en":"`.` picks a class, `#` an id."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".card {","  color: navy","  padding: 12px;","}"],"bug":1,"fix":"  color: navy;","why":{"it":"Ogni dichiarazione finisce con il punto e virgola: senza, si perde anche quella dopo.","en":"Every declaration ends with a semicolon: without it, the next one is lost too."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),1,'tune','{"prompt":{"it":"Copia il bersaglio: stesso colore e stessa trasparenza.","en":"Copy the target: same colour and same transparency."},"layout":"box","items":1,"props":[{"prop":"background-color","choices":["#FF5B2E","#3D9BFF","#12B886","#FFC53D"],"target":"#3D9BFF"},{"prop":"opacity","unit":"","min":0.25,"max":1,"step":0.25,"target":0.5,"start":1}],"base":[],"itemBase":{"width":"55%","height":"60%","border-radius":"16px"},"why":{"it":"`opacity` va da 0 (invisibile) a 1 (pieno).","en":"`opacity` goes from 0 (invisible) to 1 (solid)."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["#FF0000",{"it":"Rosso, in esadecimale","en":"Red, in hexadecimal"}],["rgb(0 0 255)",{"it":"Blu, in RGB","en":"Blue, in RGB"}],["hsl(120 100% 25%)",{"it":"Verde, in HSL","en":"Green, in HSL"}],["transparent",{"it":"Nessun colore","en":"No colour"}]],"why":{"it":"Lo stesso colore si può scrivere in molti modi.","en":"The same colour can be written in many ways."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`color` cambia il colore del testo","en":"`color` changes the text colour"},true],[{"it":"`2rem` con base 16px vale 32px","en":"`2rem` on a 16px base is 32px"},true],[{"it":"`font-color` è una proprietà CSS","en":"`font-color` is a CSS property"},false],[{"it":"`#000` è il bianco","en":"`#000` is white"},false],[{"it":"`font-weight: 700` è il grassetto","en":"`font-weight: 700` is bold"},true]],"why":{"it":"In esadecimale `#000` è nero, `#fff` è bianco.","en":"In hexadecimal `#000` is black, `#fff` is white."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),1,'tune','{"prompt":{"it":"Muovi i comandi finché la tua figura è uguale al bersaglio.","en":"Move the controls until your figure matches the target."},"layout":"box","items":1,"props":[{"prop":"padding","unit":"px","min":0,"max":40,"step":4,"target":24},{"prop":"border-radius","unit":"px","min":0,"max":48,"step":4,"target":28},{"prop":"border-width","unit":"px","min":0,"max":12,"step":2,"target":6}],"base":{"padding":"10px"},"itemBase":{"border-style":"solid","border-color":"#1B1B4B","background-clip":"content-box","background-color":"#FF5B2E","width":"60%","height":"70%","box-sizing":"border-box"},"why":{"it":"Il `padding` spinge il contenuto verso l’interno, il bordo lo racchiude.","en":"`padding` pushes the content inwards, the border wraps it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),2,'order','{"prompt":{"it":"Metti gli strati in ordine, dall’interno verso l’esterno.","en":"Put the layers in order, from the inside out."},"lines":["content","padding","border","margin"],"why":{"it":"Contenuto, spazio interno, bordo, spazio esterno.","en":"Content, inner space, border, outer space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Il `margin` è lo spazio esterno","en":"`margin` is the outer space"},true],[{"it":"Con `border-box` il padding allarga la scatola","en":"With `border-box` padding widens the box"},false],[{"it":"`margin: 0 auto` centra un blocco con una larghezza","en":"`margin: 0 auto` centres a block with a width"},true],[{"it":"`padding` accetta valori negativi","en":"`padding` accepts negative values"},false],[{"it":"`border-radius` arrotonda gli angoli","en":"`border-radius` rounds the corners"},true]],"why":{"it":"Con `border-box` la larghezza comprende padding e bordo.","en":"With `border-box` the width includes padding and border."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),1,'tune','{"prompt":{"it":"Fai stare le tre scatole una accanto all’altra, come nel bersaglio.","en":"Put the three boxes side by side, like in the target."},"layout":"box","items":3,"props":[{"prop":"display","choices":["block","inline-block","none"],"target":"inline-block"},{"prop":"margin-right","unit":"px","min":0,"max":24,"step":4,"target":12}],"base":[],"itemBase":{"width":"26%","height":"44px","background-color":"#12B886","border-radius":"10px","margin-bottom":"6px"},"why":{"it":"`inline-block` sta in riga ma accetta larghezza e altezza.","en":"`inline-block` stays in line but accepts width and height."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["block",{"it":"Occupa tutta la riga","en":"Takes the whole row"}],["inline",{"it":"Sta nel testo, ignora la larghezza","en":"Sits in the text, ignores width"}],["inline-block",{"it":"In riga, ma con larghezza e altezza","en":"In line, but with width and height"}],["none",{"it":"Sparisce del tutto","en":"Disappears completely"}]],"why":{"it":"`display` decide come un elemento occupa lo spazio.","en":"`display` decides how an element takes up space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<div>` è un blocco per natura","en":"`<div>` is a block by nature"},true],[{"it":"`<span>` è in riga per natura","en":"`<span>` is inline by nature"},true],[{"it":"`display: none` lascia il posto vuoto","en":"`display: none` leaves an empty gap"},false],[{"it":"`visibility: hidden` lascia il posto vuoto","en":"`visibility: hidden` leaves an empty gap"},true],[{"it":"`width` funziona su `display: inline`","en":"`width` works on `display: inline`"},false]],"why":{"it":"`none` toglie l’elemento dalla pagina, `hidden` lo rende solo invisibile.","en":"`none` removes the element from the page, `hidden` only makes it invisible."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),1,'tune','{"prompt":{"it":"Porta il quadrato nel punto del bersaglio.","en":"Move the square to the spot of the target."},"layout":"box","items":1,"props":[{"prop":"top","unit":"px","min":0,"max":120,"step":10,"target":70},{"prop":"left","unit":"px","min":0,"max":180,"step":10,"target":120}],"base":{"position":"relative"},"itemBase":{"position":"absolute","width":"48px","height":"48px","background-color":"#FF4D8D","border-radius":"12px"},"why":{"it":"Con `position: absolute`, `top` e `left` contano dal contenitore posizionato.","en":"With `position: absolute`, `top` and `left` count from the positioned container."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["static",{"it":"Il flusso normale","en":"The normal flow"}],["relative",{"it":"Si sposta dal suo posto","en":"Moves from its own place"}],["absolute",{"it":"Esce dal flusso","en":"Leaves the flow"}],["fixed",{"it":"Resta fermo sullo schermo","en":"Stays still on the screen"}],["sticky",{"it":"Si aggancia scorrendo","en":"Sticks while scrolling"}]],"why":{"it":"`position` cambia il punto di riferimento di un elemento.","en":"`position` changes the reference point of an element."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".padre {","  position: static;","}",".figlio {","  position: absolute;","  top: 0;","}"],"bug":1,"fix":"  position: relative;","why":{"it":"Un elemento `absolute` si aggancia al primo antenato posizionato: `static` non conta.","en":"An `absolute` element anchors to the first positioned ancestor: `static` does not count."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),1,'order','{"prompt":{"it":"Ordina dal selettore più debole al più forte.","en":"Order from the weakest selector to the strongest."},"lines":["p",".nota","#box","style=\\"…\\"","!important"],"why":{"it":"Tag, classe, id, stile in linea e infine `!important`.","en":"Tag, class, id, inline style and finally `!important`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"A parità di forza vince la regola scritta dopo","en":"With equal strength the rule written last wins"},true],[{"it":"Un id batte dieci classi","en":"One id beats ten classes"},true],[{"it":"`color` si eredita dai genitori","en":"`color` is inherited from parents"},true],[{"it":"`padding` si eredita dai genitori","en":"`padding` is inherited from parents"},false],[{"it":"`!important` va usato ovunque","en":"`!important` should be used everywhere"},false]],"why":{"it":"Cascata: prima conta la specificità, poi l’ordine.","en":"Cascade: specificity counts first, then order."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),3,'bug','{"prompt":{"it":"Il testo dovrebbe essere blu: tocca la riga che lo impedisce.","en":"The text should be blue: tap the line that prevents it."},"lines":["p.nota { color: red; }",".nota { color: blue; }"],"bug":0,"fix":"p { color: red; }","why":{"it":"`p.nota` è più specifico di `.nota`, anche se è scritto prima.","en":"`p.nota` is more specific than `.nota`, even if it comes first."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),1,'tune','{"prompt":{"it":"Disponi le scatole come nel bersaglio.","en":"Arrange the boxes like the target."},"layout":"flex","items":3,"props":[{"prop":"justify-content","choices":["flex-start","center","space-between","flex-end"],"target":"space-between"},{"prop":"align-items","choices":["flex-start","center","flex-end"],"target":"center"}],"base":[],"itemBase":[],"why":{"it":"`justify-content` lavora sull’asse principale, `align-items` su quello trasversale.","en":"`justify-content` works on the main axis, `align-items` on the cross axis."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),2,'tune','{"prompt":{"it":"Ora in colonna, con più respiro.","en":"Now in a column, with more room."},"layout":"flex","items":3,"props":[{"prop":"flex-direction","choices":["row","column","row-reverse"],"target":"column"},{"prop":"align-items","choices":["flex-start","center","flex-end"],"target":"flex-end"},{"prop":"gap","unit":"px","min":0,"max":24,"step":4,"target":12}],"base":[],"itemBase":[],"why":{"it":"Con `flex-direction: column` gli assi si scambiano: `align-items` ora è orizzontale.","en":"With `flex-direction: column` the axes swap: `align-items` is now horizontal."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".barra {\\n  display: ___;\\n  ___: center;\\n  gap: 12px;\\n}","gaps":["flex","justify-content"],"extra":["block","text-align","float"],"why":{"it":"`display: flex` si scrive sul contenitore, non sugli elementi.","en":"`display: flex` goes on the container, not on the items."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),1,'tune','{"prompt":{"it":"Muovi i comandi finché la tua figura è uguale al bersaglio.","en":"Move the controls until your figure matches the target."},"layout":"grid","items":6,"props":[{"prop":"grid-template-columns","choices":["1fr","1fr 1fr","1fr 1fr 1fr","2fr 1fr"],"target":"1fr 1fr 1fr"},{"prop":"gap","unit":"px","min":0,"max":24,"step":4,"target":16}],"base":[],"itemBase":[],"why":{"it":"`fr` divide lo spazio libero in parti uguali.","en":"`fr` splits the free space into equal parts."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),2,'tune','{"prompt":{"it":"Una colonna larga e una stretta: trova la griglia.","en":"One wide column and a narrow one: find the grid."},"layout":"grid","items":4,"props":[{"prop":"grid-template-columns","choices":["1fr 1fr","1fr 2fr","2fr 1fr","1fr 1fr 1fr"],"target":"2fr 1fr"},{"prop":"gap","unit":"px","min":0,"max":24,"step":4,"target":8}],"base":[],"itemBase":[],"why":{"it":"`2fr 1fr` dà alla prima colonna il doppio dello spazio.","en":"`2fr 1fr` gives the first column twice the space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".lista {\\n  display: ___;\\n  grid-template-columns: ___(3, 1fr);\\n  ___: 12px;\\n}","gaps":["grid","repeat","gap"],"extra":["flex","columns","margin"],"why":{"it":"`repeat(3, 1fr)` è il modo breve per scrivere `1fr 1fr 1fr`.","en":"`repeat(3, 1fr)` is the short way of writing `1fr 1fr 1fr`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),1,'order','{"prompt":{"it":"Scrivi la media query mobile first.","en":"Write the mobile-first media query."},"lines":[".lista { display: block; }","@media (min-width: 700px) {","  .lista { display: flex; }","}"],"why":{"it":"Prima lo stile per il telefono, poi le aggiunte per gli schermi più larghi.","en":"First the phone style, then the additions for wider screens."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Mobile first parte dallo schermo piccolo","en":"Mobile first starts from the small screen"},true],[{"it":"`min-width: 700px` vale sotto i 700px","en":"`min-width: 700px` applies below 700px"},false],[{"it":"`vw` è una percentuale della larghezza dello schermo","en":"`vw` is a percentage of the screen width"},true],[{"it":"`clamp()` limita un valore tra minimo e massimo","en":"`clamp()` keeps a value between a minimum and a maximum"},true],[{"it":"Senza meta viewport il telefono rimpicciolisce la pagina","en":"Without the viewport meta the phone shrinks the page"},true],[{"it":"`max-width: 100%` ingrandisce le immagini oltre il contenitore","en":"`max-width: 100%` enlarges images beyond the container"},false]],"why":{"it":"`min-width` si attiva da quella larghezza in su.","en":"`min-width` applies from that width upwards."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".card { width: 100%; }","@media (max-width: 700px {","  .card { width: 50%; }","}"],"bug":1,"fix":"@media (max-width: 700px) {","why":{"it":"Manca la parentesi che chiude la condizione: tutto il blocco verrebbe ignorato.","en":"The bracket closing the condition is missing: the whole block would be ignored."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":":root {\\n  ___brand: #FF5B2E;\\n}\\n.card {\\n  color: ___(--brand);\\n  width: ___(100% - 32px);\\n}","gaps":["--","var","calc"],"extra":["$","@","val"],"why":{"it":"Le variabili CSS iniziano con `--` e si leggono con `var()`.","en":"CSS variables start with `--` and are read with `var()`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[":root { --spazio: 16px; }",".card {","  padding: --spazio;","}"],"bug":2,"fix":"  padding: var(--spazio);","why":{"it":"Per leggere una variabile serve sempre `var()`.","en":"Reading a variable always takes `var()`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["var(--x)",{"it":"Legge una variabile","en":"Reads a variable"}],["calc()",{"it":"Fa un calcolo","en":"Does a calculation"}],["min()",{"it":"Sceglie il valore minore","en":"Picks the smaller value"}],["clamp()",{"it":"Limita tra due estremi","en":"Limits between two ends"}],[":root",{"it":"Il posto delle variabili globali","en":"The home of global variables"}]],"why":{"it":"Funzioni e variabili rendono il CSS facile da cambiare.","en":"Functions and variables make CSS easy to change."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),1,'tune','{"prompt":{"it":"Ruota e ingrandisci la scatola come il bersaglio.","en":"Rotate and enlarge the box like the target."},"layout":"box","items":1,"props":[{"prop":"rotate","unit":"deg","min":0,"max":90,"step":15,"target":45},{"prop":"scale","unit":"","min":0.5,"max":1.5,"step":0.25,"target":1.25,"start":0.5}],"base":{"display":"grid","place-items":"center"},"itemBase":{"width":"70px","height":"70px","background-color":"#FFC53D","border-radius":"14px"},"why":{"it":"`rotate` e `scale` cambiano l’aspetto senza spostare gli altri elementi.","en":"`rotate` and `scale` change the look without moving other elements."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),2,'order','{"prompt":{"it":"Componi l’animazione.","en":"Put the animation together."},"lines":["@keyframes pulsa {","  from { opacity: 1; }","  to { opacity: .4; }","}",".luce { animation: pulsa 1s infinite; }"],"why":{"it":"Prima si definiscono i `@keyframes`, poi li si usa con `animation`.","en":"First you define the `@keyframes`, then you use them with `animation`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".card {\\n  ___: transform .2s;\\n}\\n.card:___ {\\n  transform: ___(1.05);\\n}","gaps":["transition","hover","scale"],"extra":["animation","active","zoom"],"why":{"it":"`transition` si scrive sullo stato di partenza, così vale andando e tornando.","en":"`transition` goes on the starting state, so it works both ways."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___: #FF5B2E;\\n.titolo {\\n  color: ___;\\n}","gaps":["$brand","$brand"],"extra":["--brand","@brand"],"why":{"it":"In SCSS una variabile inizia con `$`.","en":"In SCSS a variable starts with `$`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Il browser legge direttamente lo SCSS","en":"The browser reads SCSS directly"},false],[{"it":"Lo SCSS viene compilato in CSS","en":"SCSS is compiled into CSS"},true],[{"it":"Ogni file CSS valido è anche SCSS valido","en":"Every valid CSS file is also valid SCSS"},true],[{"it":"Le variabili `$` esistono ancora nel CSS finale","en":"`$` variables still exist in the final CSS"},false],[{"it":"I file parziali iniziano con `_`","en":"Partial files start with `_`"},true]],"why":{"it":"Lo SCSS esiste solo prima della compilazione: al browser arriva CSS puro.","en":"SCSS exists only before compiling: the browser gets plain CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$bordo: 2px;",".card {","  border: bordo solid red;","}"],"bug":2,"fix":"  border: $bordo solid red;","why":{"it":"Il nome della variabile si scrive sempre con il `$`.","en":"The name of a variable is always written with `$`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"a {\\n  color: navy;\\n  ___:hover { color: red; }\\n  ___-attivo { color: green; }\\n}","gaps":["&","&"],"extra":["#",".","*"],"why":{"it":"`&` è il selettore genitore: `&:hover` diventa `a:hover`.","en":"`&` is the parent selector: `&:hover` becomes `a:hover`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),2,'match','{"prompt":{"it":"Abbina lo SCSS al CSS che produce.","en":"Match the SCSS with the CSS it produces."},"pairs":[["nav { a { … } }","nav a"],["a { &:hover { … } }","a:hover"],[".btn { &-big { … } }",".btn-big"],[".card { .titolo & { … } }",".titolo .card"]],"why":{"it":"La posizione di `&` decide dove finisce il genitore.","en":"The position of `&` decides where the parent ends up."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),3,'bug','{"prompt":{"it":"Una di queste righe non produce `.menu:hover`: trovala.","en":"One of these lines does not produce `.menu:hover`: find it."},"lines":[".menu {","  color: navy;","  :hover { color: red; }","}"],"bug":2,"fix":"  &:hover { color: red; }","why":{"it":"Senza `&` c’è uno spazio: il risultato è `.menu :hover`, tutta un’altra cosa.","en":"Without `&` there is a space: you get `.menu :hover`, something else entirely."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),1,'order','{"prompt":{"it":"Definisci il mixin e poi usalo.","en":"Define the mixin, then use it."},"lines":["@mixin ombra($colore) {","  box-shadow: 0 2px 8px $colore;","}",".card {","  @include ombra(gray);","}"],"why":{"it":"Prima `@mixin` lo definisce, poi `@include` lo inserisce dove serve.","en":"First `@mixin` defines it, then `@include` puts it where needed."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___ tondo($r: 8px) {\\n  border-radius: $r;\\n}\\n.foto {\\n  ___ tondo(50%);\\n}\\n.grande {\\n  ___ .foto;\\n}","gaps":["@mixin","@include","@extend"],"extra":["@use","@function"],"why":{"it":"`@mixin` e `@include` copiano regole, `@extend` condivide un selettore.","en":"`@mixin` and `@include` copy rules, `@extend` shares a selector."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["@mixin",{"it":"Definisce un blocco riutilizzabile","en":"Defines a reusable block"}],["@include",{"it":"Usa un mixin","en":"Uses a mixin"}],["@extend",{"it":"Eredita da un altro selettore","en":"Inherits from another selector"}],["%segnaposto",{"it":"Selettore che non finisce nel CSS","en":"Selector that never reaches the CSS"}]],"why":{"it":"Un mixin può avere parametri, `@extend` no.","en":"A mixin can have parameters, `@extend` cannot."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___ \\"colori\\";\\n.card {\\n  color: colori___$brand;\\n}","gaps":["@use","."],"extra":["@import","::","->"],"why":{"it":"`@use` carica un modulo; i suoi nomi si leggono con `modulo.nome`.","en":"`@use` loads a module; its names are read with `module.name`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),2,'order','{"prompt":{"it":"Scrivi il ciclo sulla mappa.","en":"Write the loop over the map."},"lines":["$temi: (ok: green, ko: red);","@each $nome, $tinta in $temi {","  .avviso-#{$nome} {","    color: $tinta;","  }","}"],"why":{"it":"`@each` scorre la mappa, `#{…}` mette il valore nel nome del selettore.","en":"`@each` walks the map, `#{…}` puts the value in the selector name."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["@use",{"it":"Carica un modulo","en":"Loads a module"}],["@each",{"it":"Scorre una lista o una mappa","en":"Walks a list or a map"}],["@if",{"it":"Applica una condizione","en":"Applies a condition"}],["#{$x}",{"it":"Inserisce un valore nel testo","en":"Puts a value into text"}],["map.get()",{"it":"Legge una voce della mappa","en":"Reads an entry of a map"}]],"why":{"it":"Con moduli e cicli lo stile si genera da pochi dati.","en":"With modules and loops, style is generated from little data."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".titolo","  color: red;","  font-size: 2rem"],"bug":1,"fix":"  color: red","why":{"it":"Nella sintassi indentata non ci sono né graffe né punti e virgola.","en":"The indented syntax has no braces and no semicolons."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),2,'order','{"prompt":{"it":"Rimetti in ordine il codice Sass.","en":"Put the Sass code back in order."},"lines":["$brand: orange",".card","  color: $brand","  .titolo","    font-size: 2rem"],"why":{"it":"Il rientro dice che cosa sta dentro che cosa.","en":"Indentation says what goes inside what."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In Sass contano i rientri","en":"In Sass indentation matters"},true],[{"it":"I file Sass finiscono in `.sass`","en":"Sass files end in `.sass`"},true],[{"it":"Sass usa le parentesi graffe","en":"Sass uses curly braces"},false],[{"it":"Un rientro sbagliato cambia il significato","en":"A wrong indent changes the meaning"},true],[{"it":"Ogni riga finisce con `;`","en":"Every line ends with `;`"},false]],"why":{"it":"Meno simboli, ma il rientro diventa parte del codice.","en":"Fewer symbols, but indentation becomes part of the code."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___tondo\\n  border-radius: 50%\\n\\n.avatar\\n  ___tondo","gaps":["=","+"],"extra":["@","&","$"],"why":{"it":"`=` definisce un mixin, `+` lo usa.","en":"`=` defines a mixin, `+` uses it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),2,'match','{"prompt":{"it":"Abbina la scrittura Sass a quella SCSS.","en":"Match the Sass form with the SCSS form."},"pairs":[["=tondo","@mixin tondo"],["+tondo","@include tondo"],["=box($r)","@mixin box($r)"],["+box(4px)","@include box(4px)"]],"why":{"it":"Stessa logica: cambiano solo i simboli.","en":"Same logic: only the symbols change."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["=ombra","  box-shadow: 0 2px 8px gray",".card","  =ombra"],"bug":3,"fix":"  +ombra","why":{"it":"Dentro una regola il mixin si usa con `+`: `=` serve a definirlo.","en":"Inside a rule a mixin is used with `+`: `=` is for defining it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),1,'match','{"prompt":{"it":"Di quale sintassi è la caratteristica?","en":"Which syntax does each feature belong to?"},"pairs":[["{ }  ;","SCSS"],[{"it":"Rientri","en":"Indentation"},"Sass"],[".css",{"it":"Lo diventano entrambe","en":"Both become this"}]],"why":{"it":"Stesso motore, due modi di scrivere.","en":"Same engine, two ways of writing."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"SCSS e Sass hanno le stesse funzioni","en":"SCSS and Sass have the same features"},true],[{"it":"Un file CSS valido è valido anche in `.sass`","en":"A valid CSS file is also valid in `.sass`"},false],[{"it":"Lo SCSS è la scelta più diffusa","en":"SCSS is the most widespread choice"},true],[{"it":"Il browser preferisce Sass","en":"The browser prefers Sass"},false],[{"it":"Si possono usare entrambi nello stesso progetto","en":"You can use both in the same project"},true]],"why":{"it":"Per il browser non cambia nulla: alla fine arriva sempre CSS.","en":"Nothing changes for the browser: in the end it always gets CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),3,'order','{"prompt":{"it":"Rimetti in ordine la strada del tuo stile.","en":"Put the journey of your style in order."},"lines":["main.scss",{"it":"compilatore Sass","en":"Sass compiler"},"main.css","<link rel=\\"stylesheet\\">",{"it":"browser","en":"browser"}],"why":{"it":"Si scrive lo SCSS, si compila, e la pagina collega il CSS.","en":"You write SCSS, compile it, and the page links the CSS."}}');
