INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<head>","  <title>Fucina</title>","  <meta name=\\"description\\" value=\\"Impara\\">","</head>"],"bug":2,"fix":"  <meta name=\\"description\\" content=\\"Impara\\">","why":{"it":"I `meta` usano `content`, non `value`.","en":"`meta` tags use `content`, not `value`."}}');
