INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".finestra {","  z-index: 100;","  background: white;","}"],"bug":1,"fix":"  position: fixed; z-index: 100;","why":{"it":"Senza `position`, `z-index` non ha effetto.","en":"Without `position`, `z-index` has no effect."}}');
