INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un link può sembrare un bottone","en":"A link can look like a button"},true],[{"it":"`cursor: pointer` serve sui bottoni","en":"`cursor: pointer` is for buttons"},true],[{"it":"`padding` allarga l’area da toccare","en":"`padding` widens the tap area"},true],[{"it":"`text-decoration: none` toglie il colore","en":"`text-decoration: none` removes the colour"},false]],"why":{"it":"Il `padding` rende più grande anche l’area cliccabile.","en":"`padding` also enlarges the clickable area."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".nuovo::after {","  testo: \\"!\\";","  color: gold;","}"],"bug":1,"fix":"  content: \\"!\\";","why":{"it":"La proprietà si chiama `content`: senza, lo pseudo-elemento non esiste.","en":"The property is called `content`: without it the pseudo-element does not exist."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[":first-child",{"it":"Il primo figlio","en":"The first child"}],[":last-child",{"it":"L’ultimo figlio","en":"The last child"}],[":nth-child(3)",{"it":"Il terzo figlio","en":"The third child"}],[":nth-child(odd)",{"it":"I dispari","en":"The odd ones"}],["::after",{"it":"Un elemento finto alla fine","en":"A fake element at the end"}]],"why":{"it":"Selezioni precise, senza classi in più.","en":"Precise selection, with no extra classes."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".card___(img) { padding: 0; }\\n.card {\\n  ___:hover { color: red; }\\n}\\n___ (min-width: 400px) { … }","gaps":[":has","&","@container"],"extra":[":with","@media-box","#"],"why":{"it":"Tre novità che fanno risparmiare molto JavaScript.","en":"Three features that save a lot of JavaScript."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`:has()` può scegliere un genitore","en":"`:has()` can pick a parent"},true],[{"it":"Le container query guardano allo schermo","en":"Container queries look at the screen"},false],[{"it":"`&` funziona nel CSS nativo","en":"`&` works in native CSS"},true],[{"it":"Serve un compilatore per `:has()`","en":"`:has()` needs a compiler"},false]],"why":{"it":"Tutto questo funziona nel browser, senza strumenti.","en":"All of this works in the browser, with no tools."}}');
