INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`transition` funziona nei due sensi se sta sullo stato normale","en":"`transition` works both ways on the normal state"},true],[{"it":"`opacity` si può animare","en":"`opacity` can be animated"},true],[{"it":"`.2s` sono due secondi","en":"`.2s` is two seconds"},false],[{"it":"Si possono animare più proprietà insieme","en":"Several properties can be animated together"},true],[{"it":"La transizione serve solo ai colori","en":"Transitions are only for colours"},false]],"why":{"it":"Brevi e mirate: le transizioni migliori quasi non si notano.","en":"Short and focused: the best transitions are barely noticed."}}');
