INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Animare `transform` è più leggero di `left`","en":"Animating `transform` is lighter than `left`"},true],[{"it":"`opacity` è economica da animare","en":"`opacity` is cheap to animate"},true],[{"it":"Più animazioni ci sono, meglio è","en":"The more animations, the better"},false],[{"it":"Il movimento può far stare male","en":"Movement can make people feel ill"},true],[{"it":"Animare `height` è gratis","en":"Animating `height` is free"},false]],"why":{"it":"Bella, leggera e rispettosa: così si anima.","en":"Beautiful, light and respectful: that is how to animate."}}');
