INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`_bottoni.scss` è un parziale","en":"`_bottoni.scss` is a partial"},true],[{"it":"Ogni parziale diventa un `.css`","en":"Every partial becomes a `.css`"},false],[{"it":"`@use` si scrive in cima al file","en":"`@use` goes at the top of the file"},true],[{"it":"Dividere i file rallenta il sito","en":"Splitting files slows the site down"},false]],"why":{"it":"Tanti file per chi scrive, uno solo per chi visita.","en":"Many files for the author, one for the visitor."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'maps-sass'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$colore: red",".card {","  color: $colore","}"],"bug":1,"fix":".card","why":{"it":"In Sass non ci sono graffe: basta il rientro.","en":"There are no braces in Sass: the indent is enough."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'maps-sass'),2,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["$temi: (ok: green)","@each $nome, $tinta in $temi","  .avviso-#{$nome}","    color: $tinta"],"why":{"it":"Prima i dati, poi il ciclo, poi quello che genera.","en":"First the data, then the loop, then what it generates."}}');
