INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'convert'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Lo stesso CSS si può ottenere da SCSS o Sass","en":"The same CSS can come from SCSS or Sass"},true],[{"it":"In Sass i rientri sono facoltativi","en":"In Sass indents are optional"},false],[{"it":"`+x` usa un mixin","en":"`+x` uses a mixin"},true],[{"it":"In Sass ogni riga finisce con `}`","en":"In Sass every line ends with `}`"},false]],"why":{"it":"Le due sintassi portano allo stesso risultato.","en":"Both syntaxes lead to the same result."}}');
