INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'utilities'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Tailwind ha bottoni già pronti","en":"Tailwind has ready-made buttons"},false],[{"it":"`p-8` è più grande di `p-4`","en":"`p-8` is bigger than `p-4`"},true],[{"it":"Le classi si possono combinare","en":"Classes can be combined"},true],[{"it":"`text-gray-600` cambia il colore del testo","en":"`text-gray-600` changes the text colour"},true]],"why":{"it":"Tailwind dà i mattoni, non i componenti.","en":"Tailwind gives bricks, not components."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'flex-grid'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<div class=\\"___ items-center gap-2\\">…</div>\\n<ul class=\\"grid ___ gap-4\\">…</ul>","gaps":["flex","grid-cols-2"],"extra":["block","cols-2","inline"],"why":{"it":"Flex in riga, griglia a due colonne.","en":"Flex in a row, a two-column grid."}}');
