INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'search-sort'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["while basso <= alto:","    medio = (basso + alto) // 2","    if lista[medio] < obiettivo:","        basso = medio","    else:","        alto = medio - 1"],"bug":3,"fix":"        basso = medio + 1","why":{"it":"Senza +1 il ciclo può non finire mai.","en":"Without +1 the loop may never end."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'recursion'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Ricorsione","en":"Recursion"},{"it":"Funzione che chiama sé stessa","en":"Function calling itself"}],[{"it":"Caso base","en":"Base case"},{"it":"Ferma la ricorsione","en":"Stops recursion"}],[{"it":"Albero","en":"Tree"},{"it":"Struttura gerarchica","en":"Hierarchical structure"}],[{"it":"Grafo","en":"Graph"},{"it":"Nodi e archi","en":"Nodes and edges"}],["BFS",{"it":"Percorsi più brevi","en":"Shortest paths"}]],"why":{"it":"Strutture annidate.","en":"Nested structures."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'recursion'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["def conto_alla_rovescia(n):","    print(n)","    conto_alla_rovescia(n - 1)"],"bug":2,"fix":"    if n > 0: conto_alla_rovescia(n - 1)","why":{"it":"Senza caso base la ricorsione non finisce.","en":"Without a base case recursion never ends."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'injection'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$nome = $_GET[\\"nome\\"];","$st = $pdo->query(\\"SELECT * FROM prodotti WHERE nome = ''$nome''\\");","$righe = $st->fetchAll();"],"bug":1,"fix":"$st = $pdo->prepare(\\"SELECT * FROM prodotti WHERE nome = ?\\"); $st->execute([$nome]);","why":{"it":"I dati dell’utente non vanno mai concatenati nella query.","en":"User data must never be concatenated into the query."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'injection'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Le query preparate separano dati e codice","en":"Prepared statements separate data from code"},true],[{"it":"Togliere gli apici basta sempre a proteggersi","en":"Removing quotes is always enough"},false],[{"it":"L’injection può riguardare anche i comandi di sistema","en":"Injection can also affect system commands"},true],[{"it":"L’injection è un rischio minore","en":"Injection is a minor risk"},false]],"why":{"it":"Il dato resta dato.","en":"Data stays data."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["const box = document.querySelector(\\"#saluto\\");","const nome = new URLSearchParams(location.search).get(\\"nome\\");","box.innerHTML = \\"Ciao \\" + nome;"],"bug":2,"fix":"box.textContent = \\"Ciao \\" + nome;","why":{"it":"Dati dall’URL con innerHTML aprono la porta all’XSS.","en":"URL data with innerHTML opens the door to XSS."}}');
