INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Tabella dei fatti","en":"Fact table"},{"it":"Eventi e importi","en":"Events and amounts"}],[{"it":"Tabella dimensione","en":"Dimension table"},{"it":"Chi, cosa, quando","en":"Who, what, when"}],[{"it":"Uno-a-molti","en":"One-to-many"},{"it":"Relazione tipica","en":"Typical relationship"}],[{"it":"Calendario","en":"Calendar"},{"it":"Analisi nel tempo","en":"Time analysis"}],[{"it":"Schema a stella","en":"Star schema"},{"it":"Modello consigliato","en":"Recommended model"}]],"why":{"it":"Modellare i dati.","en":"Modelling data."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Lo schema a stella ha una tabella dei fatti al centro","en":"The star schema has a fact table at the centre"},true],[{"it":"Una tabella unica con tutto è sempre meglio","en":"One table with everything is always better"},false],[{"it":"Le relazioni permettono di filtrare tra tabelle","en":"Relationships allow filtering across tables"},true],[{"it":"La tabella Calendario è inutile","en":"The Calendar table is useless"},false]],"why":{"it":"Fondamenta solide.","en":"Solid foundations."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["SUM",{"it":"Somma una colonna","en":"Sums a column"}],["DISTINCTCOUNT",{"it":"Conta i valori distinti","en":"Counts distinct values"}],["DIVIDE",{"it":"Divisione sicura","en":"Safe division"}],["CALCULATE",{"it":"Cambia i filtri","en":"Changes filters"}],["SAMEPERIODLASTYEAR",{"it":"Stesso periodo anno prima","en":"Same period last year"}]],"why":{"it":"Le funzioni DAX.","en":"DAX functions."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["Vendite Totali = SUM(Vendite[Importo])","Margine % = [Margine] / [Vendite Totali]"],"bug":1,"fix":"Margine % = DIVIDE([Margine], [Vendite Totali])","why":{"it":"Con / un mese senza vendite dà errore: usa DIVIDE.","en":"With / a month without sales errors out: use DIVIDE."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Scheda","en":"Card"},{"it":"Un numero chiave","en":"A key number"}],["Slicer",{"it":"Filtro interattivo","en":"Interactive filter"}],[{"it":"Grafico a linee","en":"Line chart"},{"it":"Andamento","en":"Trend"}],["RLS",{"it":"Dati per persona","en":"Data per person"}],[{"it":"Aggiornamento pianificato","en":"Scheduled refresh"},{"it":"Dati sempre freschi","en":"Always fresh data"}]],"why":{"it":"Report che parlano.","en":"Reports that speak."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Cliccare su un grafico può filtrare gli altri","en":"Clicking a chart can filter the others"},true],[{"it":"Più colori diversi rendono il report più chiaro","en":"More different colours make the report clearer"},false],[{"it":"Un titolo può dire la conclusione","en":"A title can state the conclusion"},true],[{"it":"Un report pubblicato non si può aggiornare","en":"A published report cannot be refreshed"},false]],"why":{"it":"Dai numeri alle decisioni.","en":"From numbers to decisions."}}');
